insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('ABP100Y1', 'Introduction to Academic Studies', '72S', 'This interdisciplinary, skills-focused course parallels the other component courses of the full-time Academic Bridging Program, supplementing those courses and helping students integrate their entire Academic Bridging experience, while providing intensive, workshop-style training in the fundamental skills needed for success in further university studies in the Humanities and Social Sciences. The course will also provide academic advising and planning, to help students understand and navigate university culture. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ABP101Y1', 'Introduction to Academic Studies in the Sciences', '72S', 'This interdisciplinary, skills-focused course parallels the other component courses of the full-time ABP Science Option, supplementing those courses and helping students integrate their entire Academic Bridging experience, while providing intensive, workshop-style training in the fundamental skills needed for success in further university studies in Mathematics and the Sciences. The course will also provide academic advising and planning, to help students understand and navigate university culture. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ABP102Y1', 'Diversity and Social Justice in Canada', '72L', 'Despite its image as a multicultural nation, non-dominant groups have often experienced discrimination and injustice within Canada. The course examines experiences of injustice in Canada from diverse perspectives, amplifying voices of marginalized communities (e.g., Indigenous and other racialized peoples, LGBTQ2S+) and providing a more nuanced and critical view of diversity in Canada, historically and in the present. The course will also highlight the ways diverse communities have resisted injustices and have worked towards the creation of more just futures in Canada. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW102Y1', 3, null::jsonb),
    ('ABP103Y1', 'Exploring Literature: From Conventional to Cutting Edge', '72L', 'This course introduces students to the study of literature through an exploration of the conventional to the cutting edge, in terms of literary content, genre, and form. Students will learn to identify and challenge literary conventions and structures while exploring new formats and media. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'ENG185Y1,  WDW103Y1', 1, null::jsonb),
    ('ABP104Y1', 'Environmental Issues Today', '72L', 'This interdisciplinary course introduces the major issues regarding the sustainability of the global environment in the face of human development by integrating humanities and social science with the fundamental concept of environmental science. It examines major environmental problems, such as rapid climate change and land degradation as well as the role and impact of government, economics, and ethics on environmental issues. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW104Y1', 3, null::jsonb),
    ('ABP105Y1', 'Indigenous Cultures and Societies', '72L', 'This course provides an interdisciplinary focus on key topics relevant to Indigenous communities, historically and in the present. Students will be introduced to diverse cultures, communities, and worldviews of Indigenous peoples of Turtle Island (particularly Canada) and how they have been affected by colonialism. Emphasis will be placed on the ways Indigenous peoples are resisting social, economic, political, and environmental injustices, while revitalizing their identities, knowledges, and communities and creating space for the expression of Indigenous voices. Storytelling that prioritizes the perspectives and worldviews of Indigenous peoples will guide students'' learning about course topics, issues, and concepts. Students will be encouraged to connect their own storied identities and perspectives to course themes and issues. Classes will involve a mix of interactive lectures, class discussion, student-led learning opportunities, and field trips. Class time and assignments will also be devoted to helping students build their critical thinking, reading, and writing skills towards the completion of a research-based essay due at the end of the year. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW105Y1', 3, null::jsonb),
    ('ABP106Y1', 'Media, Culture, and Society', '72L', 'This interdisciplinary course provides an introduction to the cultural and social impacts of present-day popular mass media. Themes explored include the economic and political forces that shape the media world, the role of technology, and issues of representation, gender, and social justice. The course examines a wide range of texts, emphasizing popular culture produced in Canada, and students will have the opportunity to draw extensively on their own interactions with popular media. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW106Y1', 1, null::jsonb),
    ('ABP107Y1', 'Introduction to University Studies in Mathematics', '72L', 'This course focuses on mathematical concepts and skills needed for success in First Year university Math and Science courses. Students will develop quantitative reasoning abilities required to critique arguments and make decisions, and will gain a deep understanding of functions modeling relationships. The course highlights multiple representations of each topic, emphasizing connections, and workshop-style sessions enable students to strengthen the skills they learn. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW107Y1', 5, null::jsonb),
    ('ABP108Y1', 'Introduction to University Studies in Chemistry', '72L', 'This course covers the fundamental knowledge and skills needed for success in First Year university Chemistry and other Sciences such as Biology. Topics include atoms, elements, and compounds; the chemical and physical properties of gases, liquids, and solids; chemical reactions; and the importance of chemistry in understanding the world around us, with attention to how it can address issues in medicine, the environment, and sustainability. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW108Y1', 5, null::jsonb),
    ('ABP109Y1', 'Diverse Histories of Canada', '72L', 'This course explores diverse, under-acknowledged narratives of people, such as Indigenous and racialized peoples, within the territories currently known as Canada to challenge monolithic, linear, and uncritical representations of this country''s past and future. Archival materials, maps, place names, art, literature, film, and other texts will be approached from interdisciplinary perspectives to reveal different orientations to historical events, social injustices, and futures of this territory. Open only to Academic Bridging Program students. Not eligible for CR/NCR option.', 'WDW101Y1', 3, null::jsonb),
    ('ACT100H1', 'Wizard Managers of Risks: Exploring Actuarial Science', '24L/12T', 'Are you curious about the world of risk and insurance? This first-year introduction to Actuarial Science course takes you on a journey through the fascinating intersection of mathematics, finance, and risk management. This course will equip you with the foundational knowledge of actuarial principles while exploring real-world applications through engaging case studies. Whether you''re aiming for a future career as an actuary or simply looking to enhance your analytical skills, this course is your gateway to understanding how actuaries shape the financial stability of our world.', null, 5, null::jsonb),
    ('ACT199H1', 'Decipher Financial Puzzles in the Media and Pop Culture', '24L', 'Have you ever watched a pundit''s passionate rant over financial crisis on TV and wondered whether he was right or wrong? Did you get the full story after watching movies like Margin Call or The Big Short? What was the efficiency market versus behavioral finance debate all about? Did you wonder why everyone in the financial press seem to be calling for a lower debt/equity ratio on banks in the post-crisis era? If you find yourself think about those questions, this is the course for you. We will start from some basic building blocks of finance, such as time value of money and discounting, and proceed to look at some of the important financial controversies you have read or heard in the pop culture or media. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT230H1', 'Mathematics of Finance for Non-Actuaries', '24L/12T', 'Introduction to financial mathematics, interest measurement, present value calculation, annuity valuation, loan amortization, consumer financing arrangements, bond valuation. The course is aimed at a general audience who will not be continuing in the actuarial science program. Course manuals fee: $30.', 'ACT240H1', 5, null::jsonb),
    ('ACT240H1', 'Mathematics of Investment & Credit', '24L/12T', 'Interest, discount and present values, as applied to determine prices and values of annuities, mortgages, bonds, equities; loan repayment schedules and consumer finance payments in general; yield rates on investments given the costs on investments. Course manuals fee: $45.', 'ACT230H1', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}'::jsonb),
    ('ACT245H1', 'Financial Principles for Actuarial Science I', '24L/12T', 'Term structure of interest rates, cashflow duration, convexity and immunization, forward and futures contracts, interest rate swaps, introduction to investment derivatives and hedging strategies.', null, 5, '{"operator": "AND", "items": ["ACT240H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ACT247H1', 'Introductory Life Contingencies', '36L', 'Probability theory applied to survival and to costs and risks of life assurances, life annuities, and pensions; analysis of survival distributions; international actuarial notation. Course manuals fee: $35.', null, 5, '{"operator": "AND", "items": ["ACT240H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('ACT348H1', 'Life Contingencies II', '36L', 'Determination of benefit premium and benefit reserves for life insurance and annuities; analysis of insurance loss random variables; theory of life contingencies for multiple lives. This is the second course in the life contingencies series, following  ACT247H1. Course manuals fee: $40.', null, 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1"]}'::jsonb),
    ('ACT349H1', 'Corporate Finance for Actuarial Science', '24L/12T', 'Corporate finance for actuarial science students.', 'ECO358H1,  ECO359H1,  RSM332H1,  RSM333H1', 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1"]}'::jsonb),
    ('ACT350H1', 'Applied Probability for Actuarial Science', '24L/12T', 'The course offers an introduction to elementary probability theory and stochastic processes. The main goal of the course is to help actuarial students understand the concept of stochastic processes with particular emphasis on Markov chains that are of great importance in Life Contingencies and Property and Casualty insurance. The course will cover the following topics: a basic review of probabilities with emphasis on conditional probabilities and expectations, discrete time Markov chains, Poisson processes, continuous time Markov chains, renewal theory and some applications, queueing theory.', null, 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1", {"operator": "OR", "items": ["STA257H1", "STA237H1"]}]}'::jsonb),
    ('ACT351H1', 'Loss Models: From Data to Decisions', '36L', 'This course will introduce the probability models central to actuarial loss analysis. We will explore frequency and severity models, compound distributions, and the transformations of random variables to account for policy adjustments, such as deductibles, policy limits, and reinsurance structures. We will also discuss simulation techniques to estimate the distribution of aggregate losses and risk measures associated with these distributions.', 'ACT451H1', 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1"]}'::jsonb),
    ('ACT352H1', 'Statistical Methods for Actuarial Loss Models', '36L', 'Insurance data often exhibits unique characteristics such as deductibles, policy limits, and truncation, requiring specialized statistical methods to model and analyze losses and survival outcomes. This course introduces statistical methods for modelling and analyzing loss and survival data in actuarial science. Key topics include product-limit estimation, empirical estimation methods, moment and percentile estimation, maximum likelihood estimation, and simulation techniques. Emphasis is placed on understanding the theoretical foundations of these methods and applying them to real loss data using R.', 'ACT452H1', 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1", {"operator": "OR", "items": ["ACT351H1", "ACT451H1"]}]}'::jsonb),
    ('ACT370H1', 'Financial Principles for Actuarial Science II', '36L', 'Mathematical theory of financial derivatives, discrete and continuous option pricing models, hedging strategies and exotic option valuation. Arts and Science students must be enrolled in the Actuarial Science Major or Specialist, the Data Science Specialist, or the Specialist in Statistical Science: Theory and Methods.', 'RSM435H1', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1"]}, {"operator": "AND", "items": ["STA261H1", {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}]}]}'::jsonb),
    ('ACT371H1', 'Reserving Methods For Property & Casualty Insurance', '24L/12T', 'Topics covered include reserving data and triangles, diagnoses methods that range from triangle of ratios of paid claims to reported claims to triangle of reported claim ratios. The syllabus also includes projection techniques. Not eligible for CR/NCR option.', null, 5, '{"operator": "AND", "items": ["ACT240H1", {"operator": "OR", "items": ["STA257H1", "STA237H1"]}]}'::jsonb),
    ('ACT372H1', 'Ratemaking Methods For Property & Casualty Insurance', '24L/12T', 'This course covers the basic ratemaking methods for P&C insurance. It assumes that students are familiar with traditional reserving diagnoses and projection methods. The syllabus would introduce concepts related to earning of exposures, on-level factors, catastrophe loading, large loss loading and credibility. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["ACT371H1"]}'::jsonb),
    ('ACT390H1', 'Professional Experience in Actuarial Science', '24S', 'This course is preparation for an internship work term. It includes various professional skill workshops, networking activities and an invited speaker series. The course is mandatory for students in the Actuarial Science Specialist program. A limited number of spots in the course are open for students in the Actuarial Science Major program. Students in the major program must apply to the department for permission to take the course. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however a $651 ancillary fee will be assessed towards Professional Experience preparatory program costs.', null, null, null::jsonb),
    ('ACT391H1', 'Professional Internship', null, 'Internship course for students enrolled in the Actuarial Science Specialist, fulfilled as a 420-hour work term at a minimum (maybe longer based on professional and academic needs) in a workplace related to actuarial science in third or fourth year.  ACT390H1 must be completed first in preparation. Contact Department for more information. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee of $822 will be assessed towards Professional Experience placement.', null, null, '{"operator": "AND", "items": ["ACT390H1"]}'::jsonb),
    ('ACT398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT455H1', 'Advanced Life Contingencies - Modeling and Applications', '36L', 'The course explores advanced actuarial topics such as multi-decrement theory, multi-state transition models, profit testing, pension mathematics, and retirement benefits. It places a strong emphasis on practical applications within the life insurance industry, examining areas such as disability income insurance, long-term care, critical illness insurance, workers'' compensation, continuing care insurance, and universal life insurance. Additionally, the course delves into the complexities of embedded options in life insurance and annuity products, providing students with in-depth knowledge of how these concepts are applied in real-world scenarios. This course is the last in the three-course series for life contingencies, following  ACT247H1 and  ACT348H1.', null, 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1", "ACT348H1"]}'::jsonb),
    ('ACT460H1', 'Stochastic Methods for Finance', '36L', 'Applications of the lognormal distribution, Brownian motion, geometric Brownian motion, martingales, Ito''s lemma, stochastic differential equations, interest rate models, the Black-Scholes model, volatility, value at risk, conditional tail expectation. Topics in advanced financial mathematics. Arts and Science students must be enrolled in the Actuarial Science Major or Specialist, the Data Science Specialist, or the Specialist in Statistical Science: Theory and Methods.', null, 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1", {"operator": "OR", "items": ["ACT350H1", "STA347H1"]}]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ACT350H1", "STA347H1"]}, {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}]}]}'::jsonb),
    ('ACT466H1', 'Advanced Statistical Modeling in Property & Casualty Insurance', '36L', 'This course provides an in-depth exploration of advanced pricing and reserving techniques in Property and Casualty (P&C) insurance, with a strong focus on methodologies. It covers fundamental topics in P&C insurance ratemaking and reserving, such as Bayes credibility, Bulhmann credibility, nonparametric Bayes credibility, deterministic and stochastic Chain Ladder, Bornhuetter-Ferguson, over-dispersed Poisson model, as well as a brief introduction to modern micro level reserving approaches. Through numerous examples, case studies, and applied models, the course emphasizes the practical application of these mathematical concepts in real-world insurance scenarios.', null, 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1", "ACT351H1"]}'::jsonb),
    ('ACT470H1', 'Advanced Pension Mathematics', '36L', 'Topics in pension mathematics; funding methods for pension plans. (Offered in alternate years)', null, 5, '{"operator": "AND", "items": ["ACT348H1"]}'::jsonb),
    ('ACT473H1', 'Issues In Actuarial Practice', '24L/24T', 'Case study approach to current issues in life insurance, pension consulting and casualty actuarial practice. The focus of the course will be on communication and presentation. This course is Pass/Fail. Not eligible for Credit/No Credit.  The course is open to students in the specialist program in actuarial science. Students in the major program in actuarial science can enrol into the course with permission of the department.', null, 5, '{"operator": "AND", "items": ["ACT348H1", "ACT349H1"]}'::jsonb),
    ('ACT475H1', 'Insurance Products and Regulation with AXIS', '36L', 'Case studies using leading actuarial application AXIS. Examine key types of insurance products and their pricing and valuation. Review representative developments in insurance regulations in US, Europe and Canada. Other topics include a brief introduction of the use of AI in life insurance.', null, 5, '{"operator": "AND", "items": ["ACT240H1", "ACT245H1", "ACT247H1"]}'::jsonb),
    ('ACT496H1', 'Readings in Actuarial Science', null, 'Independent study under the direction of a faculty member. Persons wishing to take this course must have the permission of the Undergraduate Secretary and of the prospective supervisor. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT497H1', 'Readings in Actuarial Science', null, 'Independent study under the direction of a faculty member. Persons wishing to take this course must have the permission of the Undergraduate Secretary and of the prospective supervisor. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT498Y1', 'Readings in Actuarial Science', null, 'Independent study under the direction of a faculty member. Persons wishing to take this course must have the permission of the Undergraduate Secretary and of the prospective supervisor. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ACT499Y1', 'Readings in Actuarial Science', null, 'Independent study under the direction of a faculty member. Persons wishing to take this course must have the permission of the Undergraduate Secretary and of the prospective supervisor. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('AFR150Y1', 'Africa: A Critical Introduction', '48L/24T', 'A multi-disciplinary study of Africa, emphasizing critical inquiry and analysis of Africa, the cradle of humanity and the most diverse and second largest continent in the world. Topics that will be explored include: pre-colonial, colonial and contemporary African history, cultures, economies, geographies, Africa''s place in the world, politics, religions, spirituality, art, literature, music, race, resistance, gender, sexuality, futurism, environment, Afrofuturism, anticolonial worldmaking, and Pan-Africanism. The course provides a unique opportunity to learn from the African Studies faculty representing diverse geographical and disciplinary backgrounds who will share their cutting-edge research and unique experiences, reading and writing practices.', null, 1, null::jsonb),
    ('AFR199H1', 'Africa in Toronto', '24L', 'Africa in Toronto offers students the unique opportunity to trace, map and document sites and encounters with “Africa” in Toronto across diverse social, political, economic, linguistic and cultural communities in the GTA. What are the diasporic lives of diverse African communities in the GTA? How does Toronto become home for them? Students will get the chance to learn about, reflect on and reimagine global Africa in the GTA by exploring topics such as placemaking, community-building, the politics of belonging, organizing and activism, economic hubs, artistic creation and expressive cultures, foodways and the epic battle over jollof rice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('AFR250Y1', 'Africa in the 21st Century: Challenges and Opportunities', '48L', 'A critical examination of Africa as a living space rather than merely a site of intellectual speculation and study. Uses scholarly and popular literature to explore the issues that engage the attention of ordinary Africans, ranging from the dramatic to the seemingly trivial, as they struggle to fashion meaningful lives in fast-changing societies. Topics include urban transition and city life; economic, political and cultural impacts of globalization; new religious movements and changing conceptions of selfhood; new African diasporas in the West; dynamics of gender relations, kinships and identities; and the politics of liberalization. Materials studied will include print and electronic news media and other mass media resources from Africa and across the world.', 'NEW250Y1', 3, null::jsonb),
    ('AFR251H1', 'Language, Freedom and Linguistic Human Rights in Africa', '24L', 'Examines the language situation in Africa and the extent to which freedom and linguistic human rights are enabled, granted, nurtured, achieved or protected by post-colonial African states. Using linguistic diversity in Africa as a backdrop, presents, discusses and assesses language policies that were adopted by post-colonial African states, particularly in education, and the implications that these policies have for the rights, freedom and empowerment of citizens of African states. Changes and evolving trends in language use and language planning are also discussed.', null, 1, null::jsonb),
    ('AFR260H1', 'Land, Life, and Livelihoods', '24L', 'This course aims to challenge the often-uncritical understanding of land as a thing, object, or a commodity by engaging with land as a bricolage of multiple, dynamic assemblages. Land attracts manifold meanings in different cultural contexts and engenders vibrant discourses around identity, place, and belonging. The materiality of land, fixed in place as to not be ''rolled up like a mat and taken away'', accords human and other-than-human life affordances that are vital to sustenance of life, and provides a fabric on which stories and histories are deeply embedded. In the African context, land constitutes a site where key political struggles transpire, key amongst them struggles against colonialism, and where African futures obtain form and meaning. It is on land that global interests have hugely converged as characterized by global land grabbing and quests for minerals and resources that offer hope to world''s future(s). These features of land impel us to discuss the institutions that govern land and related inscription devices such as maps and boundaries; technologies and techniques that seek to ''improve'' agricultural productivity and biodiversity conservation; and the impacts of climate change on life and livelihoods in Africa.', null, 4, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('AFR270H1', 'African Literature and the Politics of Storytelling', '24L', 'Focuses on the art and politics of storytelling across the continent. Students will engage with various kinds of narrative genres from great African novels to short stories, folktales, popular African films from Nollywood and other industries, as well as more recent forms of storytelling from social media. Topics of discussion will include globalization, colonialism, post-coloniality, neo-imperialism, environmental justice, ecocriticism, artistic expression and African identities. This novel course offers a combination of a wide range of literary and non-literary narrative genres as well as a variety of theoretical and methodological approaches to textual analysis from decolonial theories to ecocriticism, postcolonial environmentalisms, narrative theory, as well as more traditional methods of literary criticism and analysis.', null, 1, null::jsonb),
    ('AFR280Y1', 'Introductory Swahili', '24L/72T', 'Introduction to grammar and basic vocabulary of Swahili. Emphasis on comprehension and oral practice. Reading of selected texts. Relation of the language to its East African cultural context.', 'NEW280Y1', 1, null::jsonb),
    ('AFR290H1', 'The Idea of Africa', '24L/12T', 'An historical examination of Africa as a conceptual category, exploring discourses and representations - both African and non-African - that have produced our understandings of the meanings of Africa and Africanness.', null, 3, null::jsonb),
    ('AFR298H1', 'Popular Uprisings in Africa', '24L', 'In recent years, popular uprisings have mobilized thousands in over 40 African countries, to demand a radical overhauling of existing economic and political systems. This course asks: What are the catalysts, underlying causes and demands of these protest movements? What can we learn from the grassroots organizing that allowed these movements to gain momentum? How might scholars and activists analyzing the popular uprisings in their countries, allow us to develop new vocabularies and frameworks for understanding popular protests and theories of revolution? Case Studies will include popular uprisings in Sudan, Burkina Faso, Algeria, Senegal, Cameroon, Djibouti, DRC, Eswatini and Nigeria and reflect on similar movements around the world.', null, 3, null::jsonb),
    ('AFR299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AFR299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AFR322H1', 'The Contemporary African Novel', '24S', 'Novels written in the last forty years by English, French and Portuguese-speaking Africans. Ideological views concerning colonialism and neo-colonialism. Tradition, religious and secular; the use of African symbolism. A small number of historical and sociological texts are recommended as essential background reading. Works not written in English are read in translation. (Offered in alternate years)', null, 1, null::jsonb),
    ('AFR340H1', 'The Literary Lives of African Women', '24L', 'This course will track the literary history of African women through their writings. Students will study a variety of texts including memoirs, novels, short stories, creative non-fiction, drama, and poetry produced by African women with an eye to the politics of representation and legibility in these texts. This course will ask, how have African women written about their relationships to colonization, domesticity, citizenship, and national politics? It will also engage questions about the varieties of their experiences with motherhood, knowledge-making, displacement, citizenship, and belonging.', null, 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('AFR351Y1', 'African Systems of Thought', '48L', 'The exploration of a range of African cosmologies, epistemologies, and theologies, as well as specific case studies on justice, the moral order, and gender relations. The influence of these richly diverse traditions is traced as well in the writings of African thinkers in the Diaspora.', 'NEW351Y1,  NEW252Y1,  JAP256H1/ JAP356H1', 2, null::jsonb),
    ('AFR352H1', 'International Organizations, NGOs, Development and Change in Africa', '24L', 'Critically explores the role of international organizations such as the World Bank Group, the UN and NGOs in the economic development of Africa.', 'NEW352H1', 3, '{"operator": "OR", "items": ["AFR150Y1", "AFR250Y1"]}'::jsonb),
    ('AFR353H1', 'International Relations of Africa', '24L', 'Explores inter-state relations in Africa, African states'' relations with the West, China, India, Brazil, and international political, economic and financial institutions.', null, 3, '{"operator": "AND", "items": ["AFR150Y1"]}'::jsonb),
    ('AFR354H1', 'African Cultures and Development', '24L', 'Critically examines scholarly debates on the relationships between African cultures and development in various regions of the continent. Draws on interdisciplinary scholarship and development discourses to enhance students'' understanding of African conditions and cultures in the context of development thinking.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR355H1', 'African Youth Languages and Cultures', '24L', 'Examines the nature of youth languages and cultures in contemporary Africa with a focus on their characteristics and the conditions under which they develop. Also considers similarities and/or differences between youth languages and cultures in different regions of Africa and the general youth condition. Includes urban youth languages such as Sheng, Engsh, Tsotsitaal, etc. and music genres associated with youth such as hip hop, Bongo flava, etc. Discusses challenges and opportunities associated with African youth languages as they relate to questions of identity, national integration, regional integration, and development.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR357H1', 'Special Topics in African Studies', '24L', 'An upper level course. Topics of study vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR358H1', 'Special Topics in African Studies', '24L', 'An upper level course. Topics of study vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR359H1', 'The Horn of Africa - Critical Perspectives', '24L', 'Examines the Horn of Africa, its diversity, geopolitics, cultural politics, present conditions and current debates through a critical and comparative lens. Considers social forces in contemporary politics within the region including competing claims, explanations of the underpinnings of the Horn''s conflict, and the promise of peace. Draws upon interdisciplinary scholarship, public discourse, texts and media to reflect on the future of the Horn of Africa at this historical moment.', 'NEW359H1,  NEW357H1 (Special Topics in African Studies: The Horn of Africa: Critical Perspectives) offered in Fall 2018, Fall 2019', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('AFR365H1', 'Art, Media and Politics in Africa and the African Diaspora', '24L', 'Explores the critical intersections between art, media and politics by analyzing the making and circulation of various indigenous and modern art forms and their use as creative and radical strategies for creative expression, dissent, citizenship, and alternative forms of representation, reimaginings, transcendence and agency in African post-colonial contexts, and interconnected with the African Diaspora.', 'NEW357H1 (Special Topics in African Studies: Art, Media and Politics in Africa and the African Diaspora), offered in Winter 2019 and Fall 2019', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('AFR370H1', 'Anticolonialism, Radicalism and Revolutions in Africa', '24L', 'An interdisciplinary exploration of the histories of nationalist and revolutionary movements, ideologies, and regimes in twentieth and twenty-first century Africa, examining the various ways that Africans imagined, actively shaped, and continue to demand freedom and political modernity. Emphasis will be placed on African history methodology (including oral history) and historiography to encourage students to apply a historical lens to approaching key themes and concepts in African Studies such as nationalism, decolonization, the state, politics, citizenship, labour movements, and pro-democracy movements.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('AFR380Y1', 'Intermediate Swahili', '24L/72T', 'Grammar and syntax. Conversation and written composition. Reading of texts: literary, journalistic. Relation of the language to its East African context.', 'NEW380Y1', 1, '{"operator": "AND", "items": ["AFR280Y1"]}'::jsonb),
    ('AFR389H1', 'The Geopolitics and Debates on Africa-China Economic Relations', '24L', 'Explores the geopolitics of Africa-Asia relations, in particular, the unabated and polarized debates and narratives on China''s engagement across sectors in Africa, ''Africa-China'' multifaceted trade relations, strategies and interests, and economic diplomacy. Critically examines the changing landscape of economic cooperation and development financing in contemporary Africa, their underlying impulses and their broader implications.', 'NEW357H1/ AFR357H1 (Special Topics in African Studies: The Geopolitics and Debates on Africa-China Economic Relations), offered in Fall 2020 and Fall 2021', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('AFR391H1', 'African Studies Independent Study Course', '24S', 'The African Studies Independent Study course is designed both to complement regular offerings in African Studies and to provide an opportunity for African Studies students to enrich their studies. Aided and advised by a faculty supervisor, students will conduct extensive research, read relevant literature, and plan, execute, analyze and report on an original and independent investigation of an appropriate topic.', 'NEW391H1 (New College Independent Studies), offered between Winter 2020 to Winter 2023', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR398H0', 'Research Excursion Program', '48S', 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/faculty-staff/experiential-learning/international-indigenous/research-excursions-program. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR398Y0', 'Research Excursion Program', '48S', 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/faculty-staff/experiential-learning/international-indigenous/research-excursions-program. Not eligible for CR/NCR option.', 'NEW398Y0', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR450Y1', 'African Studies Honours Research Seminar', '24S', 'This honours research seminar required of all specialists and majors in African Studies offers critical explorations of the genealogy of African Studies, the transnational study of Africa, Africa''s place in a globalized world, the historical, intellectual and institutional contexts of Africanist knowledge production, its dissemination and consumption in Africa, Europe, the Americas and emerging academic sites in Asia. It engages with the paradigm shifts and vibrant scholarly and epistemic debates across disciplines and geographies as well as unfolding events, public discourses, geopolitics, African popular cultures and the reimagining of African futures through canonical, emergent scholarship and creative media. It emphasizes students'' original and creative research explorations, engaged praxis and search for alternative theorizing and decolonial epistemologies. It is also open to upper level students interested in African Studies and/or research in and on Africa.', null, 1, '{"operator": "AND", "items": ["AFR150Y1"]}'::jsonb),
    ('AFR451H1', 'Special Topics in African Studies', '24L', 'An upper level course. Topics of study vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR452H1', 'Kiswahili in a Globalized World', '24L', 'Examines the state and role of Kiswahili in the globalized world of the 21st century. Traces the changes in the roles of Kiswahili over time from its beginnings as a local East African coastal language to its current status as a regional and international lingua franca, and gives students an opportunity to interact with Kiswahili speakers in Toronto. Explores the challenges and opportunities arising from contact with other cultures and languages through globalization. Globalization as a potent force and its effects on Kiswahili are discussed in detail.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR454H1', 'Migration, Mobility, and Displacement in Contemporary Africa', '24S', 'Why do people move voluntarily or involuntarily? What are the causes and consequences of migration and displacement in Africa? This course critically examines the multifaceted dimensions of migration, mobility, and displacement, with a specific focus on communities and populations displaced by war, environmental destruction and disaster, economic failings, and the quest for economic opportunities, love, education, or individual freedom.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR455H1', 'Conflicts, Negotiations and Peacebuilding in Africa', '24S', 'Examines conflicts and peace negotiations in African contexts such as Somalia, Sudan, the Democratic Republic of Congo, and North Africa through public discourse, citizen actions, policy debates and mobilizations. Explores formal, informal, indigenous and institutional mediation and peace negotiation platforms, strategies, and impulses. Analyzes various conflict zones, case studies and intervention strategies for negotiating and sustaining peace in Africa in the broader context of the war on terror, increasing militarism, and securitization in peacebuilding.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR459H1', 'Advanced Special Topics in African Studies', '24L', 'An upper-level course. Topics of study vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR460H1', 'Climate Change, Food Security, and Sustainability in Africa', '24L', 'Food security is a critical challenge for many African countries and, in the past decades, has been exacerbated by climate change. To understand the complexities of food insecurity and to explore possible pathways for a food-secure Africa, we ask: what is the nexus between food security, climate change, and sustainability in Africa? How is food security intertwined with livelihood security, rights, justice, resource governance, conflicts, natural disasters, uncertainties, and risks and vulnerabilities? What are the challenges and opportunities for sustainable futures in Africa? Which theoretical frameworks illuminate these complexities? Students will learn through case study analyses, guest lectures, modeling and scenario-building exercises, and engagement with indigenous knowledge systems, canonical and emergent interdisciplinary scholarship on the topic.', 'AFR459H1 (Topic: Climate Change, Food Security and Sustainability in Africa), offered in Winter 2022 and Winter 2024', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR465H1', 'African Cities and Urban Futures', '24L', 'From slums, bustling cultural scenes and cityscapes, to diaspora lanes, African cities show diverse trajectories, inequalities and uneven pace of urbanization. Challenging clichés of African cities as ''dystopian'' and ''off the map'', this course critically examines the processes and dynamics of urban transformation and rapid urbanization of African cities and their socio-cultural, ecological, political and economic implications. It interrogates key drivers of urbanization, sustainable urban development, livelihoods, inclusive and just urbanism challenges, urban policies and governance, and the reimagining of African urban futures. Students will learn from cutting edge scholarship and engage with speakers and Africa-based city-builders, policy makers, artists, activists, and social entrepreneurs.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR490Y1', 'African Studies Independent Study Course', '48S', 'The African Studies Independent Study course is designed both to complement regular offerings in African Studies and to provide an opportunity for African Studies students to enrich their studies. Aided and advised by a faculty supervisor, students will conduct extensive research, read relevant literature, and plan, execute, analyze and report on an original and independent investigation of an appropriate topic. The exact Breadth Requirement category to be assigned to this course is based on the topic chosen by the student and approved by their faculty supervisor.', 'NEW490Y1 (if taken before 2025)', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR491H1', 'African Studies Independent Study Course', '48S', 'The African Studies Independent study course is designed both to complement regular offerings in African Studies and to provide an opportunity for African Studies students to enrich their studies. Students, aided and advised by a faculty supervisor, will conduct extensive research, read relevant literature, and plan, execute, analyze and report on an original and independent investigation of an appropriate topic. The exact Breadth Requirement category to be assigned to this course is based on the topic chosen by the student and approved by their faculty supervisor.', 'NEW490H1 [If taken before 2025]', null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AFR499H1', 'Advanced Topics in African Studies', '24S', 'A joint graduate/undergraduate upper-level seminar. Topics vary from year to year, depending on the instructor. Consult the Program Office for course enrolment procedures.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('AMS100H1', 'Global Capitalism', '24L/8T', 'This course explores the rise of capitalism – understood not simply as an economic system but as a political and cultural one as well. It aims to acquaint students with the more important socio-economic changes of the past 600 years with an eye towards informing the way they think about problems of the present time: globalization, growing disparities of wealth, and the exploitation of natural resources. It seeks to foster a critical approach to the way in which the world is organized. A dual mission stands at its centre: it utilizes a focus on capitalism as a tool of scholarly understanding of the way the world has evolved, and it assists students in developing a critique of capitalism as a system.', null, 3, null::jsonb),
    ('AMS200H1', 'Introduction to American Studies', '24L', 'A formal introduction to the interdisciplinary study of the United States and to the field of American Studies. Drawing from a variety of source materials ranging from political and literary to visual culture and material artifacts, this course examines the politics, history and culture of the U.S. A major emphasis will be learning to analyze primary sources.', 'USA200H1', 3, null::jsonb),
    ('AMS210H1', 'Concepts in American Studies', '24L', 'An interdisciplinary introduction to concepts key to the study of the United States in the world. Course materials will range from political, cultural, and literary theory to visual and material artifacts. Examining issues in the politics, history, and culture of the U.S., the course will give a grounding in the methods and ideas that make up the practice of American Studies.', null, 3, null::jsonb),
    ('AMS220H1', 'Depression Era America: History, Politics, Culture', '24S', 'This course explores the 1930s on a number of interconnected levels, prompting students to link the economic, political, and cultural planes of Americans'' lived experience in an informed way. It starts with the impact of the 1929 Crash, looking at the ways this reshaped values, and conceptions of race and gender, and also allowed unprecedented critiques and organizational forms to emerge. It then considers local and federal responses to economic catastrophe, emphasizing the emergence of regulatory mechanisms that further reshaped social relations. With this foundation in place, the course turns to consider three forms of artistic production in which the social dynamics of the age found powerful echo: FSA photography and WPA murals; experimental literature; and cinema.', null, 3, null::jsonb),
    ('AMS300H1', 'Theories and Methods in American Studies', '24L', 'This course, required for majors and minors but open to all who have met the pre-requisites, explores a range of approaches to the field of American Studies. Students will be introduced to some of the many ''theories and methods'' that have animated the field of American Studies, including historical methods; formal analysis of visual and literary texts; and key concepts, such as commodity chain analysis; ''race,'' ''commodity,'' ''gender,'' ''diaspora,'' and ''affect.''', 'USA300H1,  USA300Y1', 1, '{"operator": "OR", "items": ["HIS271Y1", "ENG250Y1", "GGR240H1", "GGR254H1", "POL203Y1", "POL386Y1", {"operator": "AND", "items": ["POL347H1", "POL386H1"]}]}'::jsonb),
    ('AMS310H1', 'Approaches to American Studies', '24L', 'An in-depth, interdisciplinary examination of a specific question concerning U.S. history, politics, and/or culture. Focus varies depending on instructor. Major emphases include reading critically and the initial steps of conducting original research.', null, 1, '{"operator": "OR", "items": ["AMS300H1", "USA300H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('AMS311H1', 'Approaches to American Studies', '24L', 'An in-depth, interdisciplinary examination of a specific question concerning U.S. history, politics, and/or culture. Focus varies depending on instructor. Major emphases include reading critically and the initial steps of conducting original research.', null, 1, '{"operator": "OR", "items": ["AMS300H1", "USA300H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('AMS312H1', 'Approaches to American Studies', '24L', 'An in-depth, interdisciplinary examination of a specific question concerning U.S. history, politics, and/or culture. Focus varies depending on instructor. Major emphases include reading critically and the initial steps of conducting original research.', null, 3, '{"operator": "OR", "items": ["AMS300H1", "USA300H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('AMS313H1', 'Approaches to American Studies', '24L', 'An in-depth, interdisciplinary examination of a specific question concerning U.S. history, politics, and/or culture. Focus varies depending on instructor. Major emphases include reading critically and the initial steps of conducting original research.', null, 3, '{"operator": "OR", "items": ["AMS300H1", "USA300H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('AMS320H1', 'Tearing Down Monuments: Controversies in Public Memory', '24L', 'As statues are kicked off their pedestals all around the world, this class reckons with the legacy and future of public memory cultures. We''ll consider the history, geography, aesthetics, bureaucracy, ecologies, and ideologies of both local and U.S. American memorials. And we''ll examine the birth, life, death, and afterlives of both conventional monuments and emerging forms of material and digital alt-memorialization.', 'AMS199H1', 1, '{"operator": "OR", "items": ["AMS200H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('AMS330H1', 'Transnational America', '24S', 'The United States -- as a global military, cultural, and economic power -- has always been a transnational space. In this course, students will read texts that emphasize the transnational dimensions of the US, learning about a range of topics that may include borders, global supply chains, immigration, food cultures, media, and the reach of the US military. In what ways do the United States and its people exceed their national boundaries? And in what ways are the United States and its people shaped by “elsewhere”?', 'AMS313H1 (Approaches to American Studies: Transnational America) offered in Winter 2024', 3, null::jsonb),
    ('AMS400H1', 'Topics in American Studies', '24S', 'In-depth examination of specific themes relating to American Studies.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('AMS401H1', 'Topics in American Studies', '24S', 'In-depth examination of specific themes relating to American Studies.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('AMS402H1', 'Topics in American Studies', '24S', 'In-depth examination of specific themes relating to American Studies.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('AMS403H1', 'Topics in American Studies', '24S', 'In-depth examination of specific themes relating to American Studies.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('AMS494H1', 'Independent Studies', null, 'Independent Studies. Not eligible for CR/NCR option.', 'USA494H1', null, null::jsonb),
    ('AMS495Y1', 'Independent Studies', null, 'Independent Studies. Not eligible for CR/NCR option.', 'USA495Y1', null, null::jsonb),
    ('ANA200H1', 'Human Visceral Anatomy', '36L/12P', 'This course introduces students to the gross anatomy of human visceral systems.', 'ANA300Y1,  ANA126Y1', 4, null::jsonb),
    ('ANA300Y1', 'Human Anatomy and Histology', '86L/18P', 'Structure of the human body and its relationship to function. Basic human histology, gross anatomy and neuroanatomy.', null, 4, '{"operator": "OR", "items": ["BIO130H1", "BIO152H5", "BIOA01H3", "ANA126Y1", {"operator": "AND", "items": ["ANA124H1", "ANA125H1"]}, "ANA200H1"]}'::jsonb),
    ('ANA301H1', 'Human Embryology', '48L', 'Human embryology from fertilization to the end of the fetal period. Current concepts in mammalian morphogenesis applied to the development of the various organ systems; etiologies and pathogenesis of some of the more common human congenital abnormalities.', null, 4, '{"operator": "AND", "items": ["BIO130H1"]}'::jsonb),
    ('ANA400H1', 'Anatomy Dissection', '24P/24S', 'A focused series of Anatomical dissections will be made and the surgical implications of the findings will be the subject of seminars. Attitudes to dissection of the human body, complications of surgery and other relevant issues will be discussed.', null, 4, '{"operator": "OR", "items": ["ANA300Y1", "ANA126Y1", {"operator": "AND", "items": ["ANA124H1", "ANA125H1"]}]}'::jsonb),
    ('ANA411H1', 'Anatomy in Application: Exercise & Biomechanics', '30P/30S', 'This course will cover musculoskeletal anatomy (both upper and lower limb) topics with an emphasis on applying detailed anatomical review, biomechanical principles and research evidence to explain or clarify exercise principles and myths. This course is offered every other year.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["ANA124H1", "ANA125H1", "ANA126Y1"]}, {"operator": "AND", "items": ["ANA300Y1"]}]}'::jsonb),
    ('ANA420H1', 'Anatomy of the Stem Cell Niche', '24L/12T/2P', 'This course introduces the anatomy and histology of stem cell niches in the adult and relates adult stem cells to organ function throughout the body. It is designed to build upon students'' knowledge of basic human anatomy and histology.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["BIO230H1", "PSL201Y1", "PSL300H1", "ANA301H1", "ANA300Y1", "HMB302H1"]}]}'::jsonb),
    ('ANA498Y1', 'Project in Anatomy', null, 'A research project in Histology, Cellular or Molecular Biology, Developmental Biology, Neuroanatomy or Gross Anatomy. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('ANT100Y1', 'Introduction to Anthropology', '48L/12T', 'What does it mean to be human? In this course, you will learn the diverse and varied ways that anthropologists address this question. You will explore such topics as human origins and biological variation, our primate relatives, the relationship between biology and culture, the diversity of political, economic, and social practices through space and time, the origin of farming and cities, the political use of archaeology and heritage, the relationship between language and society, religion, and how capitalism and Industrialization shape our lives. You will learn from specialists in Evolutionary Anthropology, Archaeology, and Socio-cultural and Linguistic Anthropology and have the chance for hands-on learning and discussion through biweekly tutorials.', null, 3, null::jsonb),
    ('ANT191H1', 'Personhood and Technologies of Reason', '24S', 'The African thinker Achille Mbembe has rightly said that we need a new ''techne of reason'' to respond to planetary changes. Anthropology has been good to think with the body, what is to be a person and the techniques that are salient to both. Artificial Intelligence is asking to rethink what is the limit of the body, reason and agency - the capacity to bring difference in the world. This course introduces key ideas in anthropology, psychoanalysis and religion, on bodies, personhood and forms of reason by focusing on textual and multimedia examples on anthropological accounts of personhood, Artificial Intelligence, and medieval and contemporary forms of mysticism. This is then to ask the question of how different technologies of reason may be co-existing, emerging, colliding while shaping politically different forms of being in the world. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('ANT192H1', 'Murder and Other Deathly Crimes: Anthropological Perspectives', '24S', 'Anthropology has much to say about death. There is foundational literature on sacrifice, suicide, and the rites surrounding the end of life. Anthropology also has a lot to say about violence: war, conflict, revolution. But at the nexus of death and violence lies murder, a culturally and socially salient phenomenon that garners less scholarly attention. This seminar will explore what constitutes murder in different cultural and historical contexts, by reading across anthropology, cultural studies, and film studies. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('ANT193H1', 'Making, Using, and Interpreting Stone Tools', '6L/8P/10S', 'Stone tools are the earliest and longest-lasting record of human technology. This course explores interpreting stone tools from a multidisciplinary perspective. In making, using, and studying stone tools, students will learn how archaeologists form hypotheses and design experiments to understand humans and their technologies in the past. This course presents research that investigate changes in human ancestors'' cognition and livelihoods through the contributions of other disciplines in life and social sciences to the study of stone tools. The course introduces major stone tool discoveries and critically engages with current research through the development of new ideas for research projects. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('ANT194H1', 'Human-nonhuman relations through Manga & Anime', '24S', 'Anthropology has examined various ways human beings imagine and engage with non-human beings in their everyday lives in particular social and cultural contexts. By using manga and anime, specific popular cultural expressive modes developed in Japan, this course examines social and cultural aspects of human relationship with other beings, including but not restricted to animals, plants, microbes, technological objects and spirits from anthropological perspectives. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('ANT195H1', 'Speculative Fiction and Social Reality', '24S', 'How do the imagined worlds of speculative fiction reflect, and reflect upon, the real worlds of their authors and audiences? And on the other hand, how can works of speculative fiction have real-world impacts? Is speculative fiction different, in either of these respects, than other genres of narrative? This course explores a variety of works of speculative fiction from the perspective of an anthropological interest in ideas, imaginations, and narratives in relation to social life. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('ANT197H1', 'Representations of Intellectuals', '24S', 'This course is a First-Year Foundation Seminar and provides an opportunity for exploration of different topics and themes. The course explores ideas of intellectuals who carved transformative theories during war times or under repressive regimes in the twentieth century. Intellectuals featured in the course include Rosa Luxemburg, Frantz Fanon, Walter Benjamin, Lu Xin, Audre Lorde. Further, it would examine cultural representations of them, such as, graphic novels, fictions, essays, films and videos on them or relatable to their ideas. For example, it would assign reading of Red Rosa, a graphic novel of Luxemburg together with her own work Theory of Imperialism. Or it would juxtapose Lorde''s classic, Sister Outsider, with Octavia Butler''s science fiction, Parable of the Sower. First-Year Foundation Seminars are restricted to first-year students and do not normally contribute towards program completion. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ANT199H1', 'Living on the Water in Toronto', '24S', 'What do the Great Lakes mean to people living here? Especially Indigenous people? When and how do people care about the Great Lakes? Poems, stories, social science offer perspectives on the water from anthropology and arts. Field trips including paddling on a river, hiking; talks with local activists and artists. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ANT200Y1', 'Introduction to Archaeology', '48L/24T', 'How did art and technology develop in the course of human evolution?  What led to the development of agriculture and settled village life?  How did social inequality and urbanism emerge?  This course takes a global perspective to explore the archaeological evidence that sheds light on these questions and other aspects of prehistory and early history.  Students will engage with the challenges posed by new discoveries and also with recent developments in archaeological method and theory.  The goal of the course is to involve students with the current state of archaeological research and some of the major issues archaeologists work to address.', null, 3, null::jsonb),
    ('ANT203Y1', 'The Nature of Humans', '48L/24P', 'This course examines where humans fit in the fabric of the natural world. It explores the history of ideas about humans in nature, humans as primates, the story of human evolution and modern human physical and genetic diversity.', null, 4, null::jsonb),
    ('ANT204H1', 'Social Cultural Anthropology and Global Issues', '24L/12T', 'A course focused on recent anthropological scholarship that seeks to understand and explain the transformation of contemporary societies and cultures. Topics may include some of the following: new patterns of global inequality, war and neo-colonialism, health and globalization, social justice and indigeneity, religious fundamentalism, gender inequalities, biotechnologies and society etc.', 'ANT204Y1', 3, null::jsonb),
    ('ANT205H1', 'Medical Anthropology: Sociocultural Perspectives on Illness, Medicine and Care', '24L/11T', 'Introduction to medical anthropology with a focus on questions, methods, and insights from sociocultural anthropology. Explores the relationships among culture, society, and medicine with special attention to power, inequality, and globalization. Examples from many parts of the world, addressing biomedicine as well as other healing systems.', null, 3, null::jsonb),
    ('ANT207H1', 'Core Concepts in Social and Cultural Anthropology', '24L/12T', 'Society, culture, kinship, exchange, community, identity, politics, belief: these and other core concepts are explored in this course, which lays the foundation for advanced courses in social and cultural anthropology.', null, 3, null::jsonb),
    ('ANT208H1', 'Medical Anthropology: an Evolutionary Perspective on Human Health', '24L/10T', 'Introduction to applied evolutionary medical anthropology. It explores evidence for the evolution of human vulnerability to disease across the life cycle (conception to death) and implications for health of contemporary populations in behavioral ecological, cross-cultural, health and healing systems, historical trauma, intersectionality, and climate change, lenses.', null, 4, null::jsonb),
    ('ANT210H1', 'Anthropologists and Indigenous Peoples in North America', '24L/12T', 'This course provides a rigorous introduction to historical and contemporary relations between Indigenous peoples and anthropologists, spanning archaeology, biological/ evolutionary anthropology, and socio-cultural & linguistic fields. The course centers Indigenous experience, critique, and scholarship, and fosters students'' critical thinking skills as applied to the ethics and politics of anthropological research, past and present. The course is organised into three modules: 1. Introduction to Indigenous peoples'' critiques and concerns regarding anthropology 2. Understanding historical context of these issues 3. In-depth discussion of current issues, oriented to emergent and possible future transformations in anthropology''s relations with Indigenous peoples.', 'ANT388H1', 3, null::jsonb),
    ('ANT215H1', 'Fight the Power!: A Global History of Resistance and Revolution', '24L', 'This course examines the efforts of Indigenous communities in North America to subvert, resist, and persist in the face of hegemonic power. Over the course of the semester, students will develop a critical understanding of the inner workings of power and the impact of these structures on the contemporary world. In examining the power-resistance dynamic, this course takes a cross-cultural comparative approach that situates North American case studies in relation to examples of resistance from Africa, Latin America, and the Caribbean. In examining these case studies, students are asked to engage with a variety of primary sources including songs, speeches, literary texts, and material culture.', null, 3, null::jsonb),
    ('ANT253H1', 'Language & Society', '24L/12T', 'This course introduces linguistic analysis with a view towards its application to the study of the relation between culture and social structure. The interplay of pronunciation, grammar, semantics, and discourse with rituals, ideologies, and constructions of social meaning and worldview are discussed in tandem with the traditional branches of linguistic analysisphonology, morphology, grammar, syntax, and semantics. The objective of the course is to provide a broad framework for understanding the role of language in society.', 'JAL253H1', 2, null::jsonb),
    ('ANT299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT311Y0', 'Archaeological Fieldwork', null, null, null, null, null::jsonb),
    ('ANT311Y1', 'Archaeological Fieldwork', null, 'Practical field training through six weeks of excavation on an archaeological site. Basic principles of artifact handling and classification. (Offered only in Summer Session) Not eligible for CR/NCR option.', null, null, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT315H1', 'Arctic Archaeology', '24L', 'Archaeology and ethnohistory of Arctic cultures. Emphasis is on variation in social organization, settlement pattern, economy, ideology, and interaction with the expanding European world-system.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT317H1', 'Archaeology of Eastern North America', '24L', 'This course examines the precontact and early contact period culture history of eastern North America, including Ontario, through archaeological evidence. Topics covered include the earliest peopling of the region at the end of the Ice Age, diversity of hunter-gatherer societies, introduction of agriculture, and the development of the dynamic First Nations societies who eventually met and interacted with Europeans.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT318H1', 'The Preindustrial City and Urban Social Theory', '24L', 'This course offers a comparative examination of the rise and organization of ancient cities through a detailed investigation of urban social theory. We will explore competing anthropological interpretations of urban process while probing the political, ideological, and economic structures of the worlds earliest cities. Students will have the opportunity to consider a broad range of subjects, including mechanisms of city genesis; urban-rural relations; the intersections of city and state; and historical variation in urban landscapes, ideologies, and political economies.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT320H1', 'Ancient Cultures of the Andes', '24L', 'This class offers intensive study of the archaeology and culture history of the Andean region prior to the Spanish conquest. The complexity and distinctiveness of Andean social organization, political institutions, religious ideologies, and economic practices have long fascinated anthropologists. Ultimately, the course will explore Andean cultures over a 10,000 year period, highlighting key debates, current research projects, and innovative theoretical approaches shaping contemporary archeological scholarship in South America and beyond.', null, 3, '{"operator": "OR", "items": ["ANT100Y1", "ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT324H1', 'Tourism & Globalization', '24L', 'The course uses tourism as a lens to examine global connections. Particular focus will be on the politics of cultural encounters. Drawing examples from diverse ethnographic materials, the course explores how different visions of the world come into contact, negotiated and transformed, and how tourist encounters shape peoples everyday lives.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT325H1', 'Indigenous Archaeologies', '24S', 'This course introduces students to the field of Indigenous archaeology. Indigenous archaeology is a form of critical praxis that encompasses archaeological research conducted for, with, and by Indigenous peoples. Throughout the class we explore the colonial origins of archaeology, Indigenous activism and its impacts on the discipline of anthropology, ongoing efforts to decolonize and indigenize cultural heritage, and community-based research methods. Students will all also be introduced to new theoretical perspectives emerging out of the intersection of Anthropology and Indigenous Studies including survivance, refusal, futurity, and resurgence.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH205H1", "ANT210H1", "ANT215H1", "INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}, "INS200H1"]}'::jsonb),
    ('ANT329H1', 'Language & Power Structure', '24L/4T', 'The role of language and symbolism in the representation and manipulation of ideology and power structure. Case materials drawn from the study of verbal arts, gender, law, advertising, and politics with a focus on North America.', null, 2, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1", "ANT253H1", "MCS223H1", {"credits": 0.5, "department": "SOC"}, {"credits": 0.5, "department": "POL"}, {"credits": 0.5, "department": "LIN"}]}'::jsonb),
    ('ANT330Y1', 'Paleoanthropology Field School', '24L/78P', 'This course provides background in the practical and theoretical aspects of fieldwork in Paleoanthropology. Students are trained in the treatment and analysis of fossil vertebrates, plant macro- and micro-fossils and sediments. Excursions to paleoanthropological localities of Homo erectus and Homo sapiens, and excavation at a hominoid site. (Joint undergraduate-graduate) Not eligible for CR/NCR option. Additional fees of up to $2500 for field trip costs will apply. The details and the application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate/curriculum-course-information/field-schools-and-research-opportunities. The application form should be submitted by the deadlines indicated on the website.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT331H1', 'Hormones and Behaviour: Biocultural Anthropological Perspectives', '24L/6T', 'This course takes a deep dive into one angle of biocultural anthropology by introducing bidirectional interactions between human behavior and hormonal responses, with an emphasis on psychosocial stressors, prosociality, challenge, arousal, and biological rhythms. It also surveys logistical and ethical issues concerning the collection and analysis of biomarker data in anthropological, biosocial, biodemographic, and epidemiological research. This course does include lab tutorials covering topics such as anthropometric measurement, biomarker collection techniques, general hormonal assay protocols, survey design, data analysis, and point of care testing techniques. Where possible, we tie in discussions and implications for biocultural theory and measurement. (Course materials fee: $25).', 'ANT382H1 (Hormones and Behavior) offered in Winter 2025', 4, '{"operator": "AND", "items": ["ANT208H1"]}'::jsonb),
    ('ANT333Y1', 'Living Primate Adaptations', '48L/24P', 'A survey of living primates, this lab-oriented course describes and compares the diverse behavioural and anatomical adaptations that are characteristic to this order of mammals. The understanding of the biological diversity and evolutionary history of primates is important for further understanding of human adaptation and evolution.', 'ANT333H1', 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT334Y1', 'Human Skeletal Biology', '48L/48P', 'Exploration of the development and maintenance of the human skeleton and dentition, with emphasis on application to archaeological, forensic and biomedical sciences.', 'ANT334H1', 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT335Y1', 'Human Evolution', '24L/36P', 'This course takes the student on a survey of human evolution from our ape ancestors to modern humans. Students will learn to identify skulls, teeth and limb bones, explore hundreds of casts, and learn how researchers understand human origins and trends in the development of human anatomy and behavior.', 'ANT332H5,  ANT333H5,  ANT434H5,  ANTC17H3', 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT336H1', 'Evolutionary Anthropology Theory', '24L', 'This course will explore the foundational and leading concepts in evolutionary anthropology. Historically important readings and current concepts will be presented and discussed in the context of research, especially in areas of human population biology, ecology and the evolution of Homo sapiens. Topics will include behavioral ecology and life history theory, as well as a critique of the adaptationist program.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT337H1', 'Human Movement', '24L/24P', 'This course will investigate human movement and physical activity patterns through the lens of evolutionary anthropology. The evolution of hominin physical behaviours, such as bipedalism and tool use, will be explored alongside the morphological traits associated with these behaviours. We will also examine social and cultural factors that may moderate physical activities among diverse human groups, including subsistence strategy variation and contemporary views on activity and exercise.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT338H1', 'Molecular Anthropology and Human Evolution', '24L/12P', 'Molecular anthropology is an interdisciplinary field combining biology, genetics, evolution and anthropology. In this class, we will explore the use of DNA for the study of past migrations and admixture patterns, the evolution of pathogens, plant and animal domestication and especially the relationships between recent and archaic humans.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT342H1', 'Anthropology of Race and Racism', '24L', 'This course will examine the role of anthropology in the development, maintenance, as well as critique, of race as a concept and racism as a social, cultural, and structural reality. Topics include: the relationships among anthropology, race, and colonialism; the constructions of race as a social, cultural, and biological concept; ethnographic engagements with whiteness and white supremacy; and the future of anthropology as an anti-racist and anti-colonialist enterprise.', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT343H1', 'Social Anthropology of Gender', '24L', 'Gender concerns the ways that groups define and experience what it is to be male, female, or a gender identity in-between or outside of that binary, and in all societies the boundaries of gender categories are both policed and resisted. In this course we examine how gender is made materially, discursively, and through intersections with other structures of inequality (e.g. race, sexuality, class, etc.).', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT344H1', 'Political Anthropology', '24L', 'This course explores the conceptual and methodological tools anthropologists employ to study the ways social groups enact, resist, and transform social relations that involve the production and distribution of power. It studies how anthropologists theorize politics in relation to power, authority, coercion, and consent. Topics explored in this class include political cultures in state and statelessness societies, political affect and the politics of everyday life, hegemony and resistance, governmentality and bio-politics, violence and militarization, social movements and citizenship, and the difficulties of anthropological research in conflict zones.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT345H1', 'Global Health: Anthropological Perspectives', '24L', 'This course examines medical anthropology''s contributions to, and critiques of, global health policies and programs. Topics covered include: colonialism and health, the political ecology of disease, indigenous constructions of illness and healing, medical pluralism, the politics of primary health care, population policies, reproductive health, and AIDS.', null, 3, '{"operator": "OR", "items": ["ANT205H1", "ANT207H1"]}'::jsonb),
    ('ANT346H1', 'Anthropology of Food', '24L', 'Social anthropological perspective on the nature and meaning of food production, culinary cultures, industrial food, food as metaphor, and famine and hunger.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT347H1', 'Metropolis: Global Cities', '24L', 'The role of culture, cultural diversity, space and performance in urban institutions and settings. The cultural context and consequence of urbanization.', 'ANT347Y1', 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT348H1', 'Medical Anthropology: Health, Power and Politics', '24L/5T', 'This course deepens students'' understandings of health and illness as social, cultural, political and historical phenomena. Drawing on theories and approaches from social-cultural anthropology, students will develop skills in critical analysis of experiences and meanings of healing and illness in particular contexts, with a focus on anthropological critique of dominant health policies, discourses, technologies and practices.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT205H1", "ANT207H1"]}'::jsonb),
    ('ANT352H1', 'Anthropology of Life and Death', '24L', 'What might it mean to think of death as inside of life, as opposed to at the end of it? This class examines Anthropological approaches to understanding life and death in our contemporary moment, one marked by widespread illness, war, policing, suicide, accident, and further loss. How do we go on living surrounded by death every day? Why are certain deaths valued above others? We will examine a range of related themes including funerary rituals, grief and mourning, violence and killing, illness and ageing, and ghosts and the afterlife.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT354H1', 'Right-Wing Nationalisms', '24L/12T', 'Anthropological and other approaches to right-wing nationalism, populism, illiberalism, and “democratic backsliding,” in specific parts of the world and across continents. Economic and geopolitical sources of right-wing nationalist ideas and their patterns of transmission. International cooperation among right-wing nationalists. White supremacism. Conspiracy theories. Connections between extreme and mainstream forms of illiberal nationalism.', null, 3, '{"operator": "OR", "items": [{"credits": 0.5, "department": "ANT"}, {"credits": 0.5, "department": "GGR"}, {"credits": 0.5, "department": "HIS"}, {"credits": 0.5, "department": "POL"}, {"credits": 0.5, "department": "SOC"}]}'::jsonb),
    ('ANT356H1', 'Anthropology of Religion', '24L', 'This course introduces selective anthropological and ethnographic rendering of religion and theology; matter, magic and the miraculous; religion and media. It also engages with some political understandings of religious affects; the religious in movement; mystics and relics; religious practices and their entanglements in colonial histories.', null, 2, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT357H1', 'Social Worlds of Medicine and Care', '24L', 'Presents anthropological perspectives on provision of healthcare as a complex social and cultural phenomenon. Examines hierarchies and division of labour among health care providers, and how social groups come to occupy particular positions. Considers how knowledge and skills are gained through formal training and/or lived experience, how they are recognized and valued, and may become sources of identity. Examines local variations within biomedicine as practiced in different settings around the world.', null, 3, '{"operator": "AND", "items": ["ANT205H1"]}'::jsonb),
    ('ANT358H1', 'Medical Anthropology and Social Justice', '24L', 'It is widely acknowledged that sharp disparities in disease burden and access to medical care characterize global patterns in health. These disparities affect the life chances of much of the worlds population, based on class position, gender, and geographical region.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT205H1", "ANT207H1"]}'::jsonb),
    ('ANT362H1', 'Sports and Play', '24L', 'We tend to think of sports as unserious. This course shows that much serious cultural work is conducted through sports, but also that sports are indeed not always serious. This anthropology of sports engages with sports as both work and play, considering issues like gender, bodies, competition, and pleasure.', null, 1, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT364H1', 'Advocating Environmental and Climate Justice', '24L', 'This course is designed for students eager to participate in, and reflect on, on-going advocacy on climate and environmental justice. Students will be placed, either as individuals, in partners, or in teams, with a government, non-profit or community advocacy group to collaboratively address a specific problem or need of the organization. In classroom discussions, and in assignments students will have an opportunity to reflect critically on their experiences, explore social and ethical issues, and integrate placements with course readings in ways that mobilize or perhaps challenge academic knowledge. Assignments will integrate practice in a range of forms of expression (for instance personal story, policy brief, podcast, interview, news release, or blog) to support the development of the range of expressive skills needed to support working for change. The application form is posted on the following website: https://www.anthropology.utoronto.ca/undergraduate The application form should be submitted by the deadline indicated on the website.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1", "ANT215H1"]}'::jsonb),
    ('ANT366H1', 'Anthropology of Activism and Social Justice', '24L', 'Explores how anthropologists have traditionally studied social movements and how new social movements have challenged anthropologists to rethink some of their ethnographic methods and approaches. Some specific movements covered include those related to indigenous rights, environmentalism, refugees, gay and lesbian issues, biotechnology, new religions, and globalization.', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT370H1', 'Introduction to Social Anthropological Theory', '24P', 'An in-depth critical review of foundational ideas in the development of the practice of Anthropology. Topics may include questioning fieldwork, origins and legacies of functionalism, cultural materialism, politics of culture, power and political economy, globalization and post modernism, gender and post-structuralism.', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT374H1', 'Rethinking Development, or the Improvement of the World', '36L', 'Development, or deliberate intervention to improve the lives of people deemed to be lacking, or left behind, has shaped the modern world for at least a century. Drawing on historical and ethnographic studies, this course examines the trajectory of development as a concept and practice, and traces its effects.', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT376H1', 'Anthropology of Animals', '24L', 'The relationship between humans and other animals is one of the most hotly debated topics of our times. Through key classic and contemporary writings, this course introduces students to the interdisciplinary field of animal studies, and explores how anthropologists and other theorists have critically engaged in debates about animal and human distinctions.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT378H1', 'Gift, Money, and Finance', '24L', 'This course introduces dialogue between anthropological literature and other disciplinary studies in regards to the economy and culture of gift and money transaction as a key aspect of human society. Studying the history of gift and money economy from agricultural societies and diverse developments of finance market culture in recent era through various perspectives (e.g., ethnographic, sociological, politico-economic, and historical views), this course aims to train students developing a critical understanding of capitalism.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT380H1', 'Craft of Social/Cultural Anthropology', '36S', 'This course introduces students to the skills they need to conduct ethnographic research, in particular, participant observation, in-depth interview, as well as writing fieldnotes and research proposals. The emphasis is on interactive, workshop-style small group learning.', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT382H1', 'Special Topics in Biocultural Medical Anthropology', '24L', 'This course combines lecture and discussion, and focuses on a topic in medical anthropology from a biocultural perspective. Topics change from year to year. See Anthropology website for more details.', null, 4, '{"operator": "AND", "items": ["ANT208H1"]}'::jsonb),
    ('ANT384H1', 'Special Topics in Society, Culture and Language', '24L', 'This lecture-format course focuses on a relatively broad topic in socio-cultural and/or linguistic anthropology. Topics change from year to year. For the 2015-16 academic year, the title of this course is "Nature, Culture, Human".', null, 3, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT385H1', 'Special Topics in Sociocultural Medical Anthropology', '24L', 'This course combines lecture and discussion, and focuses on a topic in medical anthropology from a sociocultural perspective. Topics change from year to year. See Anthropology website for more details.', null, 3, '{"operator": "OR", "items": ["ANT205H1", "ANT207H1"]}'::jsonb),
    ('ANT386H1', 'Global Catholicism: Anthropological Approaches', '24L', 'This is a course on material religion and mediation, kingdom and kinship, gender symbolisms and devotions, ecologies of selves and the histories of senses that infuse Catholicism. It challenges us to think about the importance of Catholicism as a global phenomenon expressed through socio-political and cultural practices of the everyday life.', null, 2, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1", "RLG212H1", "RLG203H1"]}'::jsonb),
    ('ANT390H1', 'Special Topics in Anthropology', '24L', 'This lecture-format course focuses on a relatively broad topic anthropology. Topics change from year to year. See Anthropology website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ANT395Y0', 'Special Topics in Anthropology', '48S', 'Studies in anthropology taken abroad. Areas of concentration vary depending on the instructor and year offered.', null, null, null::jsonb),
    ('ANT396Y0', 'Special Topics in Anthropology', '48S', 'Studies in anthropology taken abroad. Areas of concentration vary depending on the instructor and year offered.', null, null, null::jsonb),
    ('ANT398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program . Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program . Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ANT405H1', 'African Diaspora Archaeology', '24L', 'Between the early 1500s and the late 1800s, more than 12 million Africans were trafficked to the Americas through the Atlantic slave trade. This act reoriented the modern world—demographically, economically, politically, and culturally, setting in motion legacies of racial ideologies that continue into the present. Beginning with the slave trade in West Africa, this course traces the construction of Blackness and the archaeological remains connected to Black life in North America, the Caribbean, and South America. Looking at historical and present-day case studies, students will learn how race continues to shape our contemporary worldview—using slave narratives, first-hand accounts, archaeological evidence, and secondary sources to investigate the central themes of African Diaspora archaeology. This course goes from macro to micro to illuminate the legacy of slavery on a more localized scale. Students will also learn how to conduct independent research on specific sites of African diasporic heritage in Ontario and engage in a digital storytelling mapping project using Geographic Information System.', 'ARH482H1 (The Archaeology of Anti-Black Race Massacres in the United States) offered in Fall 2024.', 3, '{"operator": "OR", "items": ["ARH100Y1", "ARH205H1"]}'::jsonb),
    ('ANT406H1', 'Lithic Analysis', '24L/12P', 'Core reduction strategies, replication, experimental archaeology, use-wear, design approaches, ground stone, inferring behaviour from lithic artifacts.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}, {"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}, "ARH312Y1"]}'::jsonb),
    ('ANT407H1', 'Inka and Aztec States', '24L', 'This course provides a comparative study of the emergence, organization, and transformation of the two historically-documented states of the native Americas: the Inka and the Aztec. Students will have the opportunity to analyze ethnohistorical and archaeological data in order to critically evaluate models of the pre-industrial state while gauging the anthropological significance of either convergence or particularity in the historical development of centralized political formations.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}, {"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}]}'::jsonb),
    ('ANT408H1', 'The History Lab: Applied Methods in Historical Archaeology', '24L', 'Artefacts have the potential to reveal a diverse range of information about everyday life in the past, including the inner workings of social institutions, class-based dynamics, and expressions of ethnic and gendered identities. Along with archival documents and oral histories, these materials are the interpretive building blocks that Historical Archaeologists use to answer larger research questions around micro and macro-level negotiations of power, the impact of industrialization on modernity, and the dynamic relationships between individuals and society. Over the semester, students in this course will gain experience in identifying, classifying, and analyzing artefacts from Ontario that date to the nineteenth and early twentieth centuries. In addition to learning these applied skills, students will hone their inference skills by using artefacts and archives to develop research-based interpretations of daily life in the Toronto-area which will be presented publicly through a GIS (Geographic Information Systems) Storymap.', null, 1, '{"operator": "OR", "items": ["ARH100Y1", "ANT200Y1"]}'::jsonb),
    ('ANT409H1', 'Landscape Archaeology', '24L/12P', 'Archaeological survey, spatial analysis of archaeological evidence over landscapes and territories, and ways archaeologists attempt to interpret landscapes, regional settlement systems, agricultural land use, regional exchange and communication, and past people''s perceptions of or ideas about landscape.', null, 3, '{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}'::jsonb),
    ('ANT410H1', 'Hunter-Gatherers Past & Present', '24S', 'Examines the diversity of recent hunter-gatherer societies, as a source of analogues for understanding the archaeological record of past foraging peoples.', null, 3, '{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}'::jsonb),
    ('ANT411H1', 'Advanced Archaeological Theory', '24S', 'Seminar in the critical examination of major schools of archaeological thought.', null, 2, '{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}'::jsonb),
    ('ANT412H1', 'Historical Archaeology', '24L', 'What cultural, social, political, and ecological processes contribute to continuity or change in past social forms and material culture? How do we recognize and study the past dynamics of ethnicity, class, gender, colonialism, and racialization in archaeological remains? Historical archaeology, as the study of the recent past, explores material culture''s role in making visible those erased in the archival record. Using material, documentary, and oral evidence, this course focuses on core debates that have shaped and continue to influence Historical archaeology''s trajectory. We will also learn about the history of the subdiscipline, from its birth to the present day. Taking a broad approach, the first half of this course examines how power is negotiated through the historical and archaeological records by looking at theoretical and methodological approaches in case studies from North America, the Caribbean, and South America. The second half of this course will take a more localized approach where students visit historical sites around Toronto and finishes with a final project using artifactual remains currently in the possession of the City of Toronto.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ANT415Y1', 'Laboratory in Faunal Archaeo-Osteology', '48P/48S', 'Examination and interpretation of faunal material from archaeological sites as evidence for culture. The application form is posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted by the deadline indicated on the website.', null, 5, '{"operator": "AND", "items": ["ARH312Y1"]}'::jsonb),
    ('ANT416H1', 'Archaeology of Ritual and Identity', '24L', 'This course offers a comparative survey of archaeological approaches to ritual practice as it relates to identity politics, personhood, and the negotiation of power relations in past societies. An important goal of the seminar is to introduce students to social theories on the inherent materiality of ritual performance, whether orchestrated in everyday practice or in elaborate religious and political spectacles.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}, {"operator": "OR", "items": ["ANT100Y1", "ANT200Y1", "ARH100Y1", "ANT356H1"]}]}'::jsonb),
    ('ANT419H1', 'Current Debates in Palaeolithic Archaeology', '24S', 'Current research in Palaeolithic Archaeology reflecting emerging issues.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1", "ANT203Y1"]}'::jsonb),
    ('ANT420H1', 'Archaeology of Inequality', '24L', 'How social complexity is manifested in the archaeological record. Origins and evolution of prehistoric complex societies, from small-scale chiefdoms to large-scale states.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}, {"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}]}'::jsonb),
    ('ANT425H1', 'Language in Anthropological Thought', '24L', 'How ideas about language fit into the overall views of humankind as expressed by selected anthropologists, linguists, sociologists, and philosophers.', null, 2, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1", {"operator": "AND", "items": ["ANT253H1", {"credits": 0.5, "department": null}]}]}'::jsonb),
    ('ANT426H1', '''The West'' and Its Others', '24S', 'The history and present of western concepts and images about the ''Other'', in anthropological and other scholarship and in popular culture.', null, 1, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT430H1', 'Primate Conservation Biology', '24L', 'The focus of this course is on the science of primate conservation biology in an anthropological context. Topics will include primate biodiversity and biogeography, human impacts, and conservation strategies/policies. The effects of cultural and political considerations on primate conservation will also be discussed.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT431H1', 'The Real Planet of the Apes', '12L/12P', 'Through fossil labs and lectures, we look back over 30 to 5 million years ago when apes roamed from Spain to China and Germany to Southern Africa. The fossil record of these apes, our ancestors, reveals how we evolved our large brains, dexterous hands, extended growth period and incredible intelligence. We encounter many surprises along the way, such as apes living with pandas in Hungary, animals with a mix of monkey, ape and pig traits and apes the size of polar bears. Of the more than 100 species of fossil apes known, only one gave rise to us.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT433H1', 'Female Biology, Gender, and Sex: Biocultural Evolutionary Approaches', '24S', 'This course explores variation in reproductive lives from a biocultural and evolutionary perspective. Focusing on social-ecological, physiological, and biobehavioral variation in processes such as puberty, pregnancy, birth, lactation, menopause, and aging. The course also engages students in critical evaluation of nuanced biocultural research on sex and gender in context, women''s and LGBTQ+ health.', 'ANT481H1 (Biology, Gender, and Sex) offered in Winter 2025', 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT434H1', 'Health, Diet & Disease in the Past', '24L/12P', 'Advanced exploration of the life histories of past populations, through the application of palaeodietary analyses, palaeopathology and other appropriate research methods.', null, 4, '{"operator": "AND", "items": ["ANT334H1"]}'::jsonb),
    ('ANT435H1', 'Anthropology of Childhood and Childcare', '24L', 'A detailed review of the classic and recently emerging literature on the anthropology of children, childhood, and childcare. Focus is on theories for evolution of human parenting adaptations, challenges in research methodology and implications for contemporary research, practice and policy in the area of care and nutrition of infants and children.', null, 4, '{"operator": "OR", "items": ["ANT203Y1", "ANT208H1"]}'::jsonb),
    ('ANT436H1', 'Primate Ecology & Social Behavior', '24L', 'This course will provide an overview of the ecology and social behavior of extant nonhuman primates. Topics will include socioecology, conservation biology, biogeography, aggression and affiliation, community ecology, communication, and socio-sexual behavior. There will also be extensive discussions of methods used in collecting data on primates in the field.', null, 4, '{"operator": "AND", "items": ["ANT203Y1"]}'::jsonb),
    ('ANT437H1', 'Introduction to Virtual Anthropology', '18L/24P', 'Virtual anthropology is a set of new methods that allow us to digitize objects, analyze, reconstruct and share them digitally, and bring them back into the real world. After a theoretical introduction, students will use surface scanners, photogrammetric software and 3D printers to digitize and study archaeological and anthropological specimens.', null, 5, '{"operator": "OR", "items": ["ANT334H1", "ARH312Y1"]}'::jsonb),
    ('ANT438H1', 'Topics in Emerging Scholarship (Evolutionary Anthropology)', '24S', 'Taught by an advanced PhD student or postdoctoral fellow, and based on his or her doctoral research and area of expertise, this course presents a unique opportunity to explore intensively a particular Evolutionary Anthropology topic in-depth. Topics vary from year to year.', null, 4, '{"operator": "AND", "items": ["ANT203Y1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT441H1', 'Love, Sex, and Marriage', '24S', 'Beginning with anthropology''s early work on kinship, and ending with recent analyses of sex work and the globalization of ideologies of romantic love and companionate marriage, this course will investigate how emotional and sexual relationships are produced, used, conceptualized, and experienced both within particular societies and transnationally.', null, 3, '{"operator": "AND", "items": ["ANT207H1", "ANT343H1"]}'::jsonb),
    ('ANT442H1', 'Social Studies of Autism', '24L', 'Autism is simultaneously celebrated by autists as a core identity and pathologized in public and clinical discourses as a disease to be cured. This course spans anthropology of autism and critical autism studies, examining autism as both lived experience and rubric for a complex set of biosocial and cultural phenomena. Engaging with academic and popular texts and multi-media sources, we explore how knowledge of autism is socially produced in historical, political and cultural contexts; autobiographies and ethnographies of autistic lives; histories of autistic organising; and autism and intersectionality, attending particularly to race and gender.', 'ANT486H1 (Topic: Social Studies in Autism) offered in Summer 2023 and Winter 2024', 3, '{"operator": "OR", "items": ["ANT345H1", "ANT348H1", "ANT357H1", "ANT358H1", "ANT385H1"]}'::jsonb),
    ('ANT446H1', 'Anthropology of Aging, Health, and Care', '36S', 'Introduces anthropological perspectives on the life course and aging, with particular attention to health challenges and care needs, the social and cultural arrangements around these, and the impacts of population aging, global migration, technological change and other broad scale transformations. Emphasizes questions, concepts, and insights from sociocultural medical anthropology. Readings present ethnographic research based in many different parts of the world. Course assignments include an ethnographic interview and analysis; students will be provided guidance on all stages of designing and carrying out this project.', null, 3, '{"operator": "OR", "items": ["ANT203Y1", "ANT204H1", "ANT205H1", "ANT207H1", "ANT208H1", "ANT210H1"]}'::jsonb),
    ('ANT450H1', 'Multispecies Cities', '24S', 'As of 2007, for the first time in human history, more than half the world''s peoples lived in cities. It is estimated that by 2030 over 60% will be urban-dwellers. This demographic shift suggests that for many (if not most) people, their primary encounter with "nature" will be urban based. This course explores the idea of "urban-nature" by 1) focusing on the ways in which various theorists have challenged traditional ways of viewing both "the city" and "nature" and 2) encouraging students to develop their own critical perspectives through ethnographic engagements with the city of Toronto.', null, 3, '{"operator": "OR", "items": ["ANT204H1", {"operator": "AND", "items": ["ANT207H1", {"credits": 0.5, "department": null}]}]}'::jsonb),
    ('ANT455H1', 'Ethnographic Approaches to the Middle East and North Africa', '24L', 'What can Anthropology, as both an academic discipline and a way of knowing, bring to our understanding of the Middle East, a region deeply entangled in global geopolitics? What kinds of questions have social and cultural anthropologists asked when faced with the diversity of a region that stretches from North Africa to West Asia? This course explores the cultural, historical, and political complexity of the region from an ethnographic perspective, while also attending critically to the way "The Middle East" has been constructed in the first place. Rather than attempting an overview of the entire region, it focuses on themes that have compelled anthropological research in the area in recent decades, including but not limited to war, migration, labour, "terrorism", gender, racialization, and religion. We will draw from key academic texts in conversation with other genres of knowledge production including film, journalism, and literature. No previous familiarity with the region is required.', 'ANTC89H3,  ANT484H1 (Topics: Ethnography of the Middle East and North Africa) taken in Winter 2014,  ANT384H1 (Topics: Peoples of the Middle East and North Africa) taken in Winter 2017, Winter 2018.', 2, '{"operator": "AND", "items": ["ANT207H1"]}'::jsonb),
    ('ANT456H1', 'Queer Ethnography', '24L', 'This course explores, first, how and where forms of desire and sexual practice have become sites of anthropological inquiry and exemplars of particular cultural logics. Tracing, then, the transnational turn in the anthropology of sexuality, the course engages important debates about culture, locality, and globalization. By focusing on the transnational movement of desires, practices, and pleasures through activisms, mass media, and tourism, the course asks how sex is global and how globalization is thoroughly sexed. Course material will stress, but not be limited to, forms of same-sex or otherwise queer sexualities.', null, 3, '{"operator": "AND", "items": ["ANT207H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT458H1', 'Indigenous Health Histories and Canadian Settler Colonialism', '24S', 'We focus on the relationship between the health and well-being of Indigenous people/s and Canadian settler colonialism, drawing on scholarship from medical anthropology, history, Indigenous studies and settler colonial studies. The course is centrally concerned with how Indigenous social and political actors have engaged with health, illness, social suffering and healing throughout the 20th century, and informed by anthropological and historical understandings of healthcare systems as permeated by dynamic relations of power.', null, 3, '{"operator": "OR", "items": [{"credits": 0.5, "department": null}, "INS350H1", "INS355H1", "JFP450H1"]}'::jsonb),
    ('ANT459H1', 'Multispecies Ethnography', '24S', 'This course introduces perspectives which extend anthropological inquiry beyond the solely human realm. Building on an acknowledgement of the fundamental interconnectedness of humans and other life forms, it explores the agencies of other-than-humans, including nonhuman animals, land and seascapes, plants, bacteria, "contaminants," and others. The course involves field-site visits and fieldwork projects in Toronto (GTA region) and engages with ethnographic methodologies best suited to investigations of inter-species, inter-life form relationships.', null, 2, '{"operator": "AND", "items": ["ANT376H1"]}'::jsonb),
    ('ANT460H1', 'Global Perspectives on Women''s Health', '24S', 'This fourth-year seminar examines how female gender shapes health and illness. Using case studies of sexual health, fertility and its management, substance use/abuse, mental health, and occupational/labor health risks, the course investigates the material, political, and socio-cultural factors that can put women at risk for a range of illness conditions.', null, 3, '{"operator": "OR", "items": ["ANT343H1", "ANT345H1", "ANT348H1"]}'::jsonb),
    ('ANT462H1', 'Anthropology of Affect', '24S', 'This course examines how anthropologists have studied the way that people hope, imagine, love, and despise. Ethnography of the intimate realms of affect raises important questions about knowledge production and methodology as well as offering insight into how people come to act upon the world and what the human consequences of such action are. The course will also examine how the intimate is socially produced and harnessed in the service of politics and culture. Topics will include grief and its lack; dreams and activism; love and social change; memory and imperialism; sexuality and care; and violence and hope.', null, 2, '{"operator": "AND", "items": ["ANT207H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT463H1', 'Anthropology of Racial Capitalism and Dispossession', '24S', 'This course considers racial capitalism from an anthropological perspective through ethnographies and films which examine the role race, colonialism and white supremacy play in shaping and enabling contemporary forms of capitalist accumulation by dispossession in everyday life. Considering dispossession broadly, we will explore not only processes that dispossess people of property and land, but also of rights, modes of belonging, health, citizenship and life. We will also look at the ways people are organizing to reclaim what they have been dispossessed of or denied, from anti-eviction movements and abolitionist organizing to struggles for reproductive rights, food sovereignty and climate justice.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT464H1', 'Black Ethnographies', '24S', 'Black populations in the African Diaspora defy simple characterizations. In this course, we will examine the experiences of Black people through an ethnographic exploration of their lives. The close analysis of ethnographic monographs and articles will illuminate the ways in which race, gender, ethnicity, class, sexuality, ability, nationality, and other factors, shape the everyday for Black people in different cultural contexts. An additional focus will be a consideration of the experiences of Black anthropologists as ethnographers and scholars who are broadening anthropological discourses.', null, 3, '{"operator": "AND", "items": ["ANT342H1"]}'::jsonb),
    ('ANT465H1', 'Ethnographic Practicum: Toronto Tours', '24P', 'This course provides students with a partnered field experience by conducting ethnographic research on visitor tours in partner organizations in Toronto with faculty''s supervision. The project will be developed in collaboration with the partner organizations to offer students partnership-based experiential learning opportunities. Students will produce detailed ethnographic descriptions of tourist experiences, analyze how media representations and tourism infrastructure shape diverse visitor experiences, explore how existing infrastructure can be potentially repurposed for a decolonial or inclusive tour, and develop skills to communicate their findings to the broader audience.', null, 3, '{"operator": "AND", "items": ["ANT380H1"]}'::jsonb),
    ('ANT472H1', 'Japan in Global Context: Anthropological Perspectives', '24L', 'This course examines how what we know as Japan and its culture has been constructed through global interactions. Topics include gender and sexuality, race and ethnicity, social and family life, work and leisure, and Japanese identity amid changing global power relations.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}'::jsonb),
    ('ANT473H1', 'Ethnographic Practicum: The University', '36S', 'Students carry out original ethnographic research projects on some aspect of life in the University of Toronto: its students, staff and faculty; its hierarchies and habits; and the everyday practices in classrooms, labs, dining halls, offices, clubs, and residence corridors. Class time is used for collective brainstorming, feedback and analysis.', null, 3, '{"operator": "AND", "items": ["ANT380H1"]}'::jsonb),
    ('ANT475H1', 'Reading Ethnography', '24P', 'Students read several full-length ethnographies, both classical and contemporary, and debate what makes for sound ethnographic research and writing, as well as what ethnography is and "should" be as a genre of writing and representation.', null, 3, '{"operator": "AND", "items": ["ANT207H1", "ANT370H1"]}'::jsonb),
    ('ANT477H1', 'Transnational Korea in and outside the Peninsula', '24S', 'This course addresses reading ethnography as a tool to understand compressed and complex modernity such as Korean societies, both in and outside of the Korean peninsula. In particular, this course aims to develop students'' critical thinking on class, ethnicity, gender, family, and migration in Korea and diasporic societies of Koreans in Canada, China, Japan, and US.', null, 3, '{"operator": "AND", "items": ["ANT207H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT480H1', 'Special Topics in Anthropological Research', '24S', 'Unique opportunity to explore a particular anthropological topic in-depth. Topics vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 0.5, "department": "ANT"}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT480Y1', 'Special Topics in Anthropological Research', '48S', 'Unique opportunity to explore a particular anthropological topic in-depth. Topics vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 0.5, "department": "ANT"}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT481H1', 'Special Topics in Evolutionary Anthropology', '24S', 'Unique opportunity to explore in-depth a particular topic in Evolutionary Anthropology. Topics vary from year to year.', null, 4, '{"operator": "AND", "items": ["ANT203Y1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('ANT483H1', 'Special Topics in Linguistic Anthropology', '24S', 'This course will focus on an advanced topic in Linguistic Anthropology. Topic will vary from year- to-year.', null, 2, '{"operator": "AND", "items": ["ANT253H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT484H1', 'Special Topics in Social Cultural Anthropology', '24S', 'Unique opportunity to explore a particular Social Cultural Anthropology topic in-depth. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": ["ANT207H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT485H1', 'Topics in Emerging Scholarship (Society, Culture and Language)', '24S', 'Taught by an advanced PhD student or postdoctoral fellow, and based on his or her doctoral research and area of expertise, this course presents a unique opportunity to explore intensively a particular Socio-cultural or Linguistic Anthropology topic in-depth. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": ["ANT207H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT486H1', 'Special Topics: Socio-Cultural Research Seminar', '24S', 'Unique opportunity to explore a particular Social Cultural Anthropology topic in-depth. Topics vary from year to year.', null, 3, '{"operator": "AND", "items": ["ANT207H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT488H1', 'Special Topics in Medical Anthropology', '24S', 'This discussion-based seminar course focuses on a topic in medical anthropology. Topics change from year to year. See Anthropology website for more details.', null, 3, '{"operator": "AND", "items": ["ANT205H1", "ANT208H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT490Y1', 'Field Course in Social and Cultural Anthropology', '24L/52P', 'An instructor-supervised experiential study project in social and cultural anthropology. Course takes place in an off-campus setting. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ANT204H1", "ANT207H1"]}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('ANT491H1', 'Internship in Anthropology', '24P', 'This course is an opportunity to apply acquired knowledge in anthropology or archeology in a work placement environment. Opportunities may include local community organizations, international development organizations, museum or heritage projects, or media production projects. Only internships that require knowledge and skills in anthropology and/or archeology will be considered. Student must fulfill responsibilities of the internship as well as complete a final research paper. If qualified, the student''s internship supervisor will mark the final paper for the course; if not, an appropriate academic supervisor will be assigned from within the Dept. of Anthropology. Restricted to students in a Specialist or Major program in Anthropology. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 3.0, "department": "ANT"}]}'::jsonb),
    ('ANT491Y1', 'Internship in Anthropology', '48P', 'This course is an opportunity to apply acquired knowledge in anthropology or archeology in a work placement environment. Opportunities may include local community organizations, international development organizations, museum or heritage projects, or media production projects. Only internships that require knowledge and skills in anthropology and/or archeology will be considered. Student must fulfill responsibilities of the internship as well as complete a final research paper. If qualified, the student''s internship supervisor will mark the final paper for the course; if not, an appropriate academic supervisor will be assigned from within the Dept. of Anthropology. Restricted to students in a Specialist or Major program in Anthropology. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 3.0, "department": "ANT"}]}'::jsonb),
    ('ANT497Y1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and supervisor before enrolment in the course. Open in exceptional circumstances to advanced students with a strong background in Anthropology. Course Supervisor must be a member of the Anthropology faculty. A maximum of one year of Independent Research courses is allowed per program. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('ANT498H1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and supervisor before enrolment in the course. Open in exceptional circumstances to advanced students with a strong background in Anthropology. Course Supervisor must be a member of the Anthropology faculty. A maximum of one year of Independent Research courses is allowed per program. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('ANT499H1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and supervisor before enrolment in the course. Open in exceptional circumstances to advanced students with a strong background in Anthropology. Course Supervisor must be a member of the Anthropology faculty. A maximum of one year of Independent Research courses is allowed per program. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('APM236H1', 'Applications of Linear Programming', '36L', 'Introduction to linear programming including a rapid review of linear algebra (row reduction, matrix inversion, linear independence), the simplex method with applications, the duality theorem, complementary slackness, the dual simplex method and the revised simplex method.', null, 5, '{"operator": "OR", "items": ["MAT221H1", "MAT223H1", "MAT223H5", "MATA22H3", "MATA23H3", "MAT240H1", "MAT240H5"]}'::jsonb),
    ('APM306Y1', 'Mathematics and Law', '72L', 'This course examines the relationship between legal reasoning and mathematical logic; provides a mathematical perspective on the legal treatment of interest and actuarial present value; critiques ethical issues; analyzes how search engine techniques on massive databases transform legal research and considers the impact of statistical analysis and game theory on litigation strategies. NOTE This course counts as 0.5 credit in BR=3 and 0.5 credit in BR=5. This course will only contribute 0.5 credit to the Math Minor program.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT133Y1", "MAT135H1", "MAT135H5", "MAT136H1", "MAT136H5", "MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}, {"operator": "OR", "items": ["MAT221H1", "MAT223H1", "MAT240H1"]}]}'::jsonb),
    ('APM346H1', 'Partial Differential Equations', '36L', 'Sturm-Liouville problems, Green''s functions, special functions (Bessel, Legendre), partial differential equations of second order, separation of variables, integral equations, Fourier transform, stationary phase method.', 'MAT351Y1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT235Y1", "MAT235Y5", {"operator": "AND", "items": ["MAT232H5", "MAT236H5"]}, {"operator": "AND", "items": ["MATB41H3", "MATB42H3"]}, "MAT237Y1", "MAT237Y5", "MAT257Y1"]}, {"operator": "OR", "items": ["MAT244H1", "MATB44H3", "MAT244H5", "MAT267H1"]}]}'::jsonb),
    ('APM348H1', 'Mathematical Modelling', '36L/22P', 'An overview of mathematical modelling. A variety of approaches for representing physical situations mathematically followed by analytical techniques and numerical simulations to gain insight. Questions from biology, economics, engineering, medicine, physics, physiology, and the social sciences formulated as problems in optimization, differential equations, and probability. Precise content varies with instructor.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT244H1", "MAT267H1"]}, {"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["STA237H1", "STA247H1", "STA257H1", "MAT370H1", "MAT377H1"]}]}'::jsonb),
    ('APM396H1', 'Independent Reading in Applied Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside undergraduate offerings. Similar workload to a 36L course. Not eligible for CR/NCR option. This course requires an application. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('APM421H1', 'Mathematical Foundations of Quantum Mechanics and Quantum Information Theory', '36L', 'Key concepts and mathematical structure of Quantum Mechanics, with applications to topics of current interest such as quantum information theory. The core part of the course covers the following topics: Schroedinger equation, quantum observables, spectrum and evolution, motion in electro-magnetic field, angular momentum and O(3) and SU(2) groups, spin and statistics, semi-classical asymptotics, perturbation theory. More advanced topics may include: adiabatic theory and geometrical phases, Hartree-Fock theory, Bose-Einstein condensation, the second quantization, density matrix and quantum statistics, open systems and Lindblad evolution, quantum entropy, quantum channels, quantum Shannon theorems. Joint undergraduate/graduate course -  APM421H1/MAT1723H', null, 5, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, "MAT337H1"]}, "MAT357H1"]}'::jsonb),
    ('APM426H1', 'General Relativity', '36L', 'Einstein''s theory of gravity. Special relativity and the geometry of Lorentz manifolds. Gravity as a manifestation of spacetime curvature. Einstein''s equations. Cosmological implications: big bang and inflationary universe. Schwarzschild stars: bending of light and perihelion precession of Mercury. Topics from black hole dynamics and gravitational waves. The Penrose singularity theorem. Joint undergraduate/graduate course -  APM426H1/MAT1700H', null, 5, '{"operator": "OR", "items": ["MAT363H1", "MAT367H1"]}'::jsonb),
    ('APM441H1', 'Asymptotic and Perturbation Methods', '36L', 'Asymptotic series. Asymptotic methods for integrals: stationary phase and steepest descent. Regular perturbations for algebraic and differential equations. Singular perturbation methods for ordinary differential equations: W.K.B., strained co-ordinates, matched asymptotics, multiple scales. (Emphasizes techniques; problems drawn from physics and engineering)', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["APM346H1", "MAT351Y1"]}, {"operator": "OR", "items": ["MAT334H1", "MAT354H1"]}]}'::jsonb),
    ('APM446H1', 'Applied Nonlinear Equations', '36L', 'Partial differential equations appearing in physics, material sciences, biology, geometry, and engineering. Nonlinear evolution equations. Existence and long-time behaviour of solutions. Existence of static, traveling wave, self-similar, topological and localized solutions. Stability. Formation of singularities and pattern formation. Fixed point theorems, spectral analysis, bifurcation theory. Equations considered in this course may include: Allen-Cahn equation (material science), Ginzburg-Landau equation (condensed matter physics), Cahn-Hilliard (material science, biology), nonlinear Schroedinger equation (quantum and plasma physics, water waves, etc). mean curvature flow (geometry, material sciences), Fisher-Kolmogorov-Petrovskii-Piskunov (combustion theory, biology), Keller-Segel equations (biology), and Chern-Simons equations (particle and condensed matter physics). Joint undergraduate/graduate course -  APM446H1/MAT1508H', null, 5, '{"operator": "OR", "items": ["APM346H1", "MAT351Y1"]}'::jsonb),
    ('APM461H1', 'Combinatorial Methods', '36L', 'A selection of topics from such areas as graph theory, combinatorial algorithms, enumeration, construction of combinatorial identities. Joint undergraduate/graduate course -  APM461H1/MAT1302H', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT224H1", "MAT247H1"]}, {"operator": "OR", "items": ["MAT137Y1", "MAT137Y5", {"operator": "AND", "items": ["MAT137H5", "MAT139H5"]}, "MAT157Y1", "MAT157Y5", {"operator": "AND", "items": ["MAT157H5", "MAT159H5"]}]}, {"operator": "OR", "items": ["MAT301H1", "MAT347Y1"]}]}'::jsonb),
    ('APM462H1', 'Nonlinear Optimization', '36L', 'An introduction to first and second order conditions for finite and infinite dimensional optimization problems with mention of available software. Topics include Lagrange multipliers, Kuhn-Tucker conditions, convexity and calculus of variations. Basic numerical search methods and software packages which implement them will be discussed.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT223H1", "MAT224H1"]}, "MAT247H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('APM466H1', 'Mathematical Theory of Finance', '36L', 'Introduction to the basic mathematical techniques in pricing theory and risk management: Stochastic calculus, single-period finance, financial derivatives (tree-approximation and Black-Scholes model for equity derivatives, American derivatives, numerical methods, lattice models for interest-rate derivatives), value at risk, credit risk, portfolio theory. Joint undergraduate/graduate course -  APM466H1/MAT1856H', null, 5, '{"operator": "AND", "items": ["APM346H1", "STA347H1"]}'::jsonb),
    ('APM496H1', 'Independent Readings in Applied Mathematics', null, 'Independent study under the direction of a faculty member. Topic must be outside current undergraduate offerings. Similar workload to a course that has 36 lecture hours. Not eligible for CR/NCR option. Completed applications for this course are due to the Math Undergraduate Program Office no later than the third day of the term that the reading course will start.', null, 5, null::jsonb),
    ('ARH100Y1', 'Introduction to Archaeology', '48L/24T', 'Archaeology entails an active process of uncovering evidence for and learning about aspects of the human past. The goal of this course is to involve students in current archaeological practice, including its socio-political context, and the global structure of the human experience from human evolution through cities and empires. Students will critically engage with ideas both within and outside the discipline on working with descendant communities, stewardship, ethical practice, and the relevance of archaeology to contemporary issues from climate change to social inequality. This course can serve as an introduction for students planning to pursue an archaeology program or as an opportunity to engage with a fascinating topic that is relevant to disciplines ranging from science to humanities.', 'ANT200Y1', 3, null::jsonb),
    ('ARH205H1', 'Archaeological Inference', '24L/6P/6S', 'This course explores ways that archaeologists investigate research questions and interpret archaeological evidence. It introduces some of the main conceptual tools that archaeologists use to make inferences, including analogy, ethnoarchaeology, and experimental archaeology. It also uses practical exercises to help students understand the basic logic of some of the methods that archaeologists use in their research, such as dating methods and identification of spatial patterns. This prepares students for more advanced courses in archaeology.', 'ARH305H1', 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ARH306Y1', 'Archaeological Field Methods', '12L/61P', 'Intensive instruction in archaeological field methods and acquisition of field skills, including archaeological search and survey, site mapping, laying out excavation grids, use of theodolites, total station, and GPS, stratigraphic excavation, stratigraphy, field recording, screening sediment, Ontario license and reporting requirements. Normally this course would take place on campus in the summer. This course has a mandatory Lab Materials Fee of approximately $26 to cover non-reusable materials. The fee will be included on the student''s ACORN invoice. The details and application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate/curriculum-course-information/field-schools-and-research-opportunities. The application form should be submitted at least one week prior to the beginning of classes.', null, null, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1", {"operator": "AND", "items": ["NMC260H1", "NMC262H1"]}, "NMC261Y0"]}'::jsonb),
    ('ARH309H1', 'Archaeology, Ethics, and the Public', '24L', 'An analysis of ethics in contemporary archaeology that covers reburial and repatriation, interpretation of the archaeological record in the context of historically oppressed groups, ethnic minorities, and non-western societies, the ethics of collecting and managing cultural property, relationships with the media, the debates surrounding looting, and other issues.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}'::jsonb),
    ('ARH312Y1', 'Archaeological Laboratory', '28L/44P', 'Techniques for making archaeological data meaningful after excavation or survey. Archaeological measurements, compilation of data, database design, archaeological systematics, and sampling theory in the context of lithics, pottery, floral, faunal and other archaeological remains.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1"]}, {"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}, {"operator": "OR", "items": ["NMC268H1", "EEB225H1", "GGR270H1", "STA220H1", "STA221H1", "STA257H1", "STA261H1"]}]}'::jsonb),
    ('ARH360H1', 'Prehistory of the Near East', '24L', 'From earliest times through the rise of complex hunter-gatherers, and the food producing revolution to politically complex societies in Southwest Asia.', null, 3, '{"operator": "OR", "items": ["ANT200Y1", "ARH100Y1", {"operator": "AND", "items": ["NMC260H1", "NMC262H1"]}]}'::jsonb),
    ('ARH361H0', 'Field Archaeology', null, null, null, null, null::jsonb),
    ('ARH361H1', 'Field Archaeology', null, 'Opportunity for students participating in non-degree credit archaeological digs to submit reports, field notes and term papers for degree credit. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, null, null::jsonb),
    ('ARH361Y0', 'Field Archaeology', null, null, null, null, null::jsonb),
    ('ARH361Y1', 'Field Archaeology', null, 'Opportunity for students participating in non-degree credit archaeological digs to submit reports, field notes and term papers for degree credit. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', null, null, null::jsonb),
    ('ARH398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ARH398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ARH440H1', 'Photogrammetry and 3D Analysis of Material Culture', '12L/12P/12S', 'With the increasing availability of powerful computers and software, 3D modeling and recording has become commonplace in archaeology, architectural history, museum studies, and other areas of cultural heritage research. In this course, students will learn about a powerful new method for 3D recording known as photogrammetry. After a series of tutorials, they will gain firsthand experience creating their own models of various subjects, such as historical architecture and public art in Toronto, and museum objects on campus. They will also learn how to analyze and present 3D content, while thinking critically about the impact of how digital tools are currently being employed by and shaping the agendas of researchers in archaeology, art history, and related fields.', 'ARH482H1 (Special Topics in Archaeology: 3D Modeling and Archaeological Analysis), offered in Fall 2019 and Fall 2021', 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('ARH482H1', 'Special Topics in Archaeology', '24S', 'Unique opportunity to explore a particular archaeological topic in-depth. Topics vary from year to year.', null, null, '{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}'::jsonb),
    ('ARH494H1', 'Topics in Emerging Scholarship (Archaeology)', '24S', 'Taught by an advanced PhD student or postdoctoral fellow, and based on his or her doctoral research and area of expertise, this course presents a unique opportunity to explore intensively a particular Archaeology topic in-depth. Topics vary from year to year.', null, 3, '{"operator": "OR", "items": ["ARH205H1", "ARH305H1"]}'::jsonb),
    ('ARH495H1', 'Archaeology Research Practicum', null, 'Laboratory or practical research on an archaeological project that emphasizes methods and research design in archaeology. Students must obtain the consent of a Supervisor before enrolling. Students are required to give an oral presentation of research results to an open meeting of the Archaeology Centre at the conclusion of the course. Application must be made to the Anthropology Department. Not eligible for CR/NCR option. Instructions on how to obtain an application form are posted on the following website: https://www.anthropology.utoronto.ca/undergraduate. The application form should be submitted at least one week prior to the beginning of classes.', 'ANT497Y1', null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('AST101H1', 'The Sun and Its Neighbours', '24L', 'Our place in the Universe. Phenomena we see in the sky. What we know about the Sun, the planets and comets, and the formation of the solar system – and how we know it. What makes planets suitable for life. Finding out about the nearest stars and their planets. This course is intended for students with no science or engineering background.', 'AST121H1,  AST101H5,  ASTA01H3,  ASTC25H3, CIV100H1,  CIV101H1, CIV102H1. Also excluded are  AST221H1,  ASTC25H3 if taken previously or concurrently.', 5, null::jsonb),
    ('AST121H1', 'Origin and Evolution of the Universe', '24L/12T', 'The origin of the Universe and all that it contains, from the chemical elements, stars and galaxies, and life. The course is intended for students who are enrolling in science and engineering courses.', 'AST101H1,  AST201H1,  AST210H1. Also excluded are  AST221H1,  AST222H1 if taken previously or concurrently.', 5, null::jsonb),
    ('AST198H1', 'Great Astronomical Issues', '24S', 'There are some fundamental questions which humankind has asked itself over the centuries. Many of these involve astronomical origins, events, and objects. Astronomers now have the tools with which to attempt to answer some of the most fundamental questions, such as "Where did it all begin, where are we in space and time, are we alone, and who and what are we?" This seminar will explore some of these great issues. The selection of topics will be made initially by the instructor, but will be modified by the seminar participants at the first class meeting. Topics could include: stellar evolution and the future of the Sun, origin of the elements, origin and future of the Universe, origin of the Earth, origin of life, and extinction of the dinosaurs, global warming, the scientific method, astronomy and the public. Participants will be expected to join actively in lively discussions and to prepare and lead some of the seminars. Restricted to first-year students. Not eligible for CR/NCR option.', 'AST199H1', 5, null::jsonb),
    ('AST199H1', 'Astronomy at the Frontier', '24S', 'This seminar series aims at building up general scientific literacy, by discussing selected topics in current astronomy, cosmology, and space science. We will delve into the physical foundation behind the questions being asked and how the answers are being sought. Students will have an opportunity early in the course to select topics of particular interest to them and this will govern the choice of readings as well. Topics could include: formation of stars; lives and deaths of stars; stellar corpses: white dwarfs, neutron stars, and black holes; planets around other stars; recent results from Hubble and other telescopes; architecture of the solar system; exploration in the solar system; the invisible universe: dark energy and dark matter; first light; formation of galaxies; the age and future of the universe. Participants should be comfortable with basic mathematics and quantitative reasoning. Students will be expected to do independent research for essays, presentations, etc. Restricted to first-year students. Not eligible for CR/NCR option.', 'AST198H1', 5, null::jsonb),
    ('AST201H1', 'Stars and Galaxies', '24L', 'What we know about the properties and life cycles of stars, of galaxies, and of the Universe itself – and how we know it. How astronomers develop methods for understanding phenomena that span such vast ranges in distance and time. This course is intended for students with no science or engineering background.', 'AST121H1,  AST210H1,  AST201H5,  ASTA02H3,  CIV100H1,  CIV101H1,  CIV102H1. Also excluded are  AST221H1,  AST222H1,  ASTB23H3 if taken previously or concurrently.', 5, null::jsonb),
    ('AST210H1', 'Great Moments in Astronomy', '24L', 'From the Copernican Revolution to twentieth century astrophysics. Emphasis is placed on the process of discovery which has led to major advances in knowledge about the Universe. The course includes an outline of some of the most significant puzzles of our day and an examination of the potential for new revolutions in our knowledge. This course is best suited to science students.', 'AST101H1,  AST121H1,  AST201H1', 5, null::jsonb),
    ('AST221H1', 'Stars and Planets', '36L', 'The (astro)physics of stars and planets, their observed variety, their structure, formation and evolution. Introduction to telescopes and instrumentation.', 'AST221H5,  ASTB23H3,  ASTC25H3', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": ["MAT136H1", "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('AST222H1', 'Galaxies and Cosmology', '36L', 'The (astro)physics of stellar systems, galaxies, and the Universe, their structure, formation, and evolution.', 'AST222H5,  ASTB23H3,  ASTC25H3', 5, '{"operator": "OR", "items": ["AST221H1", "AST221H5"]}'::jsonb),
    ('AST251H1', 'Life on Other Worlds', '24L/12T', 'Scholarly discussion of the probability that there are planets with life elsewhere in the universe, from the perspective of current ideas concerning the origin and evolution of the universe, the solar system and life. Search techniques and possibilities for interstellar travel and space colonies are discussed.', 'AST221H1,  AST222H1,  AST222H5,  ASTB23H3,  ASTC25H3', 5, null::jsonb),
    ('AST299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program . Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST301H1', 'Observational Astronomy', '36P', 'A hands-on introduction to telescopes and observational astronomy for students with little experience in the physical sciences. Through laboratory exercises and observations of the sky, students will learn the techniques that have enabled the major discoveries of modern astronomy, from the expansion of the universe to the existence of Earth-like planets orbiting other stars. Hands-on activities will teach how telescopes work and how we can measure the distances, motion, and chemical composition of celestial objects. Basic arithmetic is used, but no advanced mathematics. This course is intended for students without a formal science background to gain experience with hands-on observational astronomy.', 'AST221H1,  AST222H1,  AST325H1,  AST326Y1,  AST110H5,  AST221H5,  AST222H5,  ASTB23H3,  ASTC25H3', 5, '{"operator": "OR", "items": ["AST101H1", "AST201H1", "AST251H1"]}'::jsonb),
    ('AST310H1', 'Indigenous Worldviews & Astronomy', '24L', 'An in-depth exploration of astronomy, the Solar System, and the night sky through the lens of Indigenous knowledges, primarily that of Indigenous peoples from Turtle Island. Indigenous peoples have lived on Turtle Island since time immemorial and have a sophisticated relationship with the night sky that is influenced by their worldviews and their relationships with the land. In this course, students will learn about Indigenous perspectives for understanding nature and astronomy and learn to understand astronomy through these perspectives. Students will also learn about the intersection of western astronomy and ongoing colonization to understand the responsibilities of western astronomers for respecting treaties and Indigenous rights as well as presenting an Indigenous lens regarding space exploration.', null, 5, '{"operator": "AND", "items": [{"credits": 0.5, "department": "AST"}]}'::jsonb),
    ('AST320H1', 'Introduction to Astrophysics', '24L/12T', 'The formation, equilibrium and evolution of structure on all astronomical scales from the largest to the smallest: universe, clusters of galaxies, galaxies, clusters of stars, gas clouds and stars.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY252H1", "PHY294H1", "PHY242H5"]}, "AST221H1", "AST222H1"]}'::jsonb),
    ('AST325H1', 'Introduction to Practical Astronomy', '39P', 'Through experiment and observation, develop the core skills to collect, reduce, and interpret astronomical data. Develop understanding and usage of telescopes, instruments, and detectors; reduction and analysis methods; simulations and model fitting; data and error analysis.', 'AST326Y1', 5, '{"operator": "AND", "items": ["AST221H1", "AST222H1"]}'::jsonb),
    ('AST326Y1', 'Practical Astronomy', '78P', 'Through experiment and observation, develop the core skills to collect, reduce, and interpret astronomical data. Develop understanding and usage of telescopes, instruments, and detectors; reduction and analysis methods; simulations and model fitting; data and error analysis. This course is an expanded version of  AST325H1 that gives a wider exposure to practical astronomy.', 'AST325H1', 5, '{"operator": "AND", "items": ["AST221H1", "AST222H1"]}'::jsonb),
    ('AST398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('AST424H1', 'Introduction to Astrophysical Research', '24L', 'A literature study or guided research project that develops methods and skills applicable to the physical sciences, with an emphasis on communication, including writing proposals and reports, and delivering presentations. This course is intended for students in the final year of the Astronomy & Astrophysics Major. Students are required to attend the weekly departmental colloquia or seminars. Not eligible for CR/NCR option.', 'AST425Y1', null, '{"operator": "OR", "items": ["AST320H1", {"operator": "AND", "items": ["AST221H1", "AST222H1"]}]}'::jsonb),
    ('AST425Y1', 'Research Topic in Astronomy', '48L', 'A research project done in consultation with an individual staff member in the Department leading to a detailed written report and oral presentation. This course is intended for students in the final year of the Astronomy and Physics specialist program. Students must enrol with the Undergraduate Secretary of the Department. Enrolment is guaranteed only for specialist students with at least a B+ average in program courses and requires identifying a supervisor. Others who wish to take  AST425Y1 should consult the course coordinator or the undergraduate chair. Not eligible for CR/NCR option.', null, 5, '{"operator": "AND", "items": ["AST320H1", {"operator": "OR", "items": ["AST325H1", "AST326Y1", "PHY324H1", "PHY350H1", "PHY354H1", "PHY356H1", "PHY357H1", "PHY358H1", "PHY407H1", "PHY408H1", "PHY450H1", "JPE395H1"]}]}'::jsonb),
    ('AST430H1', 'Supervised Study in Astronomy & Astrophysics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('AST431H1', 'Supervised Study in Astronomy & Astrophysics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('AST431Y1', 'Supervised Study in Astronomy & Astrophysics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('BCB330Y1', 'Special Project in Bioinformatics and Computational Biology', null, 'An opportunity for specialized individual research in bioinformatics and computational biology by arrangement with a supervisor. Approval of the application by the BCB coordinator is required.  Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('BCB410H1', 'Applied Bioinformatics', '24L', 'Practical introduction to concepts, standards and tools for the implementation of strategies in bioinformatics and computational biology. Student led discussions plus a strong component of hands-on exercises.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1"]}, {"operator": "OR", "items": ["CSC324H1", "CSC373H1"]}]}'::jsonb),
    ('BCB420H1', 'Computational Systems Biology', '24L', 'Current approaches to using the computer for analyzing and modeling biology as integrated molecular systems. Lectures plus hands-on practical exercises. The course extends and complements an introductory Bioinformatics course.', null, 5, '{"operator": "OR", "items": ["BCH441H1", "MGY441H1", "BCB410H1"]}'::jsonb),
    ('BCB430Y1', 'Advanced Special Project in Bioinformatics and Computational Biology', null, 'An opportunity for advanced specialized individual research in bioinformatics and computational biology by arrangement with a supervisor. Approval of the application by the BCB coordinator is required.   BCB330Y1 is a recommended preparation for this course however students should not normally conduct their project in the same laboratory or continue their previous project. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('BCH210H1', 'Biochemistry I: Proteins, Lipids and Metabolism', '36L/24T', 'This introductory course in biochemistry will cover the fundamentals of proteins, enzymes, biological membranes and the metabolism of carbohydrates and lipids for energy production. This course is intended for students who are NOT taking  BCH242Y1 as part of their program.', 'BCH242Y1, [ CHM361H5(UTM) and  CHM362H5(UTM)], [ BIOC12H3(UTSC) and  BIOC13H3(UTSC)],  CHMB62H3(UTSC)', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}'::jsonb),
    ('BCH242Y1', 'Introduction to Biochemistry', '64L/12T/18P', 'This introductory course in biochemistry will serve as the foundation for upper-level BCH courses taken by students specializing in biochemistry and related specialist programs. The major topics include protein structure, enzyme mechanisms and function, gene expression, lipid and membrane structure and function, and the metabolism of carbohydrates, lipids and amino acids for energy production. Laboratory techniques will also be introduced to understand the role of biochemistry for research. Please note that there are five laboratories accompanying this course. (Lab fees:$10)', 'BCH210H1 and  BCH311H1, [ CHM361H5 (UTM) and  CHM362H5 (UTM)], [ BIOC12H3 (UTSC) and  BIOC13H3 (UTSC)],  CHMB62H3 (UTSC)', 5, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}'::jsonb),
    ('BCH299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('BCH299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('BCH311H1', 'Biochemistry II: Nucleic Acids and Biological Information Flow', '24L/12T', 'Nucleic acids and flow of information in biological systems. Information storage and transmission by nucleic acids, as well as new molecular technologies will be discussed. Registration in one of the tutorial sessions is mandatory. Note: Students that have a SDF in  BCH210H1 are not permitted to enrol in  BCH311H1 until a final passing grade (50%) appears on the transcript. BCH2** WITH COURSE EXCLUSION TO  BCH210H1 meets the prerequisite requirement for  BCH311H1.', 'MGY311Y1,  PSL350H1', 4, '{"operator": "AND", "items": ["BCH210H1"]}'::jsonb),
    ('BCH340H1', 'Proteins: From Structure to Function', '24L/6T', 'Proteins are the main functional units in the cell. In this course, a detailed overview of protein structure and function will be given with strong emphasis on the basic principles in the field. Students will be introduced to folded and intrinsically disordered proteins. Biophysical methods to study protein stability and folding will be discussed, as well as experimental approaches to determine protein structure and function. Students will be introduced to catalysis, kinetics, and the mechanisms that regulate enzyme activity. Finally, proteomic methods to studying protein networks in cells will be presented. The course will offer a solid basis in protein biochemistry. It is recommended for those interested in pursuing graduate studies or professional degrees in health or medicine.', null, 4, '{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}'::jsonb),
    ('BCH370H1', 'Laboratory Course in Biochemical Techniques', '24L/48P', 'This course is designed to provide hands-on experience at an introductory level, employing a variety of biochemical techniques commonly used in research and clinical diagnostic laboratories. This course is intended for students who are not proceeding further in biochemistry. It is highly recommended that students take this course in their third year as space is limited and priority will go to third-year students. This course will be offered in the FALL & WINTER terms. Attendance in the first week of class is mandatory in order to receive safety information and laboratory protocols. (Enrolment limited.) (Lab fees: $40)', 'BCH377H1,  CHM379H1', 4, '{"operator": "AND", "items": ["BCH210H1"]}'::jsonb),
    ('BCH372Y1', 'Summer Research in Biochemistry', '144P', 'This course provides opportunities to pursue an original individual research project in a particular area of biochemistry, under the direct supervision of a Biochemistry Department faculty member. Students are responsible for arranging for supervision by a Biochemistry Department faculty member. To apply for enrolment, students are required to complete the application form by contacting the Course Coordinator by the end of April. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["BCH242Y1"]}'::jsonb),
    ('BCH373H1', 'Independent Research Project', '72P', 'This course provides an opportunity for individual research with a specific topic of study. Students are mentored and supervised by research scientists and faculty associated with the University of Toronto. It provides students an opportunity to enhance and apply their knowledge and understanding learned in other courses. Direct supervision must be provided by a faculty member within the Department of Biochemistry. Not eligible for the CR/NCR option.', 'BCH473Y1,  BCH374Y1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH242Y1", "BCH210H1"]}, "BIO230H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('BCH374Y1', 'Research Project in Biochemistry', '144P', 'This course provides opportunities to pursue an original individual research project in a particular area of biochemistry, under the direct supervision of a Biochemistry Department faculty member. Students are responsible for arranging for supervision by a Biochemistry Department faculty member. To apply for enrolment, students are required to complete the application form by contacting the Course Coordinator before the end of August. Not eligible for CR/NCR option.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BCH242Y1", "BIO230H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}, {"operator": "AND", "items": ["BCH210H1", "BIO230H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}]}'::jsonb),
    ('BCH375H1', 'Independent Research Project', '72P', 'This course provides an opportunity for individual research with a specific topic of study. Students are mentored and supervised by research scientists and faculty associated with the University of Toronto. It provides students an opportunity to enhance and apply their knowledge and understanding learned in other courses. Direct supervision must be provided by a faculty member within the Department of Biochemistry. Not eligible for the CR/NCR option.', 'BCH473Y1,  BCH374Y1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH242Y1", "BCH210H1"]}, "BIO230H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('BCH377H1', 'Biochemistry Laboratory I', '12L/48P', 'An introduction to fundamental laboratory techniques in modern biochemistry. Experiments illustrate and develop the concepts described in lecture courses and serve as a foundation for more advanced training in biochemistry laboratory courses. Enrollment in this course is generally restricted to students enrolled in the Biochemistry, Immunology, and Molecular Genetics & Microbiology (Genetics Stream) Specialist programs. (Lab fees: $25)', 'BCH370H1,  CHM379H1', 4, '{"operator": "AND", "items": ["BCH242Y1"]}'::jsonb),
    ('BCH378H1', 'Biochemistry Laboratory II', '12L/48P', 'This course builds upon the fundamental laboratory techniques acquired in  BCH377H1. Students gain hands-on experience in experimental design and data analysis, exploring numerous modern and classic biochemistry and molecular biology experimental techniques used in research laboratories. Enrolment in this course is generally restricted to students enrolled in the Biochemistry Specialist program.', null, 4, '{"operator": "AND", "items": ["BCH377H1"]}'::jsonb),
    ('BCH399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('BCH399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('BCH422H1', 'Membrane Proteins: Structure, and Function', '24L', 'Structural features of membrane proteins, their biogenesis and methods of analysis. Function of membrane proteins as transporters, channels, pumps and receptors. Molecular aspects of disease processes linked to membrane proteins.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH425H1', 'Structural Biology: Principles and Practice', '24L', 'Theory of modern biophysical techniques as applied to the study of the structure and function of macromolecules; emphasis on X-ray crystallography, electron cryomicroscopy, NMR spectroscopy, and other spectroscopic methods.', null, 4, '{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}'::jsonb),
    ('BCH426H1', 'Regulation of Signalling Pathways', '24L', 'This course is focused on the molecular aspects of signal transduction, covering how cells receive and then transmit signals via intracellular proteins such as kinases and phosphatase and how this ultimately regulates cell function. Specific topics covered include regulation and signalling by extracellular ligands including morphogens, growth factors and/or insulin, how signalling pathway crosstalk modulates cell function and low and high throughput methodological approaches used to elucidate signalling mechanisms.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH428H1', 'Genomics of Microbial Communities in Human Health and Beyond', '24L/12P', 'There is a growing appreciation that microbes do not operate in isolation but form parts of larger populations and communities (microbiomes) with unique considerations for human health. Combining lectures, small group discussions, and a computer lab component, this course will cover how genomics can be applied to analyze microbial communities and the transformative discoveries that continue to result.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "CSB349H1"]}]}'::jsonb),
    ('BCH440H1', 'Protein Homeostasis', '24L', 'Protein homeostasis is dependent on the coordinated synthesis, folding, localization and degradation of the thousands of proteins in a living cell. This course deals with selected aspects of the process with emphasis on: i) protein folding and the role of chaperones, ii) protein degradation via the ubiquitin proteasome system, iii) protein folding and quality control in the ER and iv) ER-associated degradation and the unfolded protein response. The course will serve as a foundation for those with an interest in how cellular protein levels and conformations are maintained.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH444H1', 'Protein Trafficking in the Secretory & Endocytic Pathways', '24L', 'This course examines the molecular details of the secretory and endocytic pathways in the cell. Some of the specific topics covered will include protein translocation into the ER, chaperones and protein folding in the ER, retrotranslocation and protein degradation, the Unfolded Protein Response (UPR), vesicle biogenesis and ER-Golgi transport, regulated secretion, basic concepts in endocytosis and protein sorting in polarized cells. Emphasis is placed on current experimental approaches. A good understanding of basic biochemical methods is an asset.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH445H1', 'Organelles in Cell Function and Death', '24L', 'Advanced principles and concepts of cell biology are covered, including the structure, life cycle, and dynamic behavior of cell organelles. The cellular processes regulated by organelles, including the life and death of the cell and cellular communication, are highlighted. The course will also cover techniques and technologies that have advanced studies of the cell.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH446H1', 'Membrane Dynamics of the Cell Surface', '24L', 'This course covers the principles and concepts related to molecular cell biology of the cell surface in multicellular organisms. Topics include: biophysical properties of cells, membranes, and extracellular matrix, dynamic remodelling of the cytoskeleton; cell-cell and cell-matrix interactions; maintenance of planar and apical-basal cell polarity; cytokinesis, viral uptake by macropinocytosis and engulfment by phagocytosis. In addition to lectures, groups of students will interpret a recent scientific paper related to the course material to be formally presented during regular class hours.', 'CSB331H1,  CSB428H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH448H1', 'Structure and Function of the Nucleus', '24L', 'This course examines the structure and function of the cell nucleus and the genome through the lens of biochemistry, molecular biology, cell biology and evolution. A focus is placed on the major scientific developments that shaped our current understanding. Topics that will be covered are eukaryogenesis, junk DNA, the structure of DNA and chromatin, the transfer of information between genotype and phenotype, the filtering of information found in the genome into biologically relevant molecules such as mRNA, the processing and export of these products from the nucleus into the cytoplasm, and the translation of mRNA into protein. We will also investigate how various organelles, such as the endoplasmic reticulum and mitochondria, played a role in the evolution of the nucleus. Finally we will investigate how biological information is partitioned during mitosis.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('BCH449H1', 'Medical Biochemistry', '24L/12T', 'This course will apply core biochemical principles to explain the pathogenesis of emerging diseases at the molecular level and describe advanced biochemical technologies used to understand and treat these illnesses. Students will be exposed to how biochemical principles influence medical diagnoses, therapy and the development of new drugs.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH242Y1", {"operator": "AND", "items": ["BCH210H1", "BCH311H1"]}]}, "BIO230H1"]}'::jsonb),
    ('BCH450H1', 'Antibiotics and Antibiotic Targets', '24L/12T', 'This course will cover the action of the biochemical targets of the existing antibiotics (nucleotide-, RNA-, DNA-, protein- and cell wall synthesis, the manner in which these pathways are inhibited in antimicrobial therapy and the biochemical basis of antibiotic resistance. The biochemistry and origin of naturally occurring and synthetic antibiotics will be introduced. (Enrolment limited.)', 'BCH350H1', 4, '{"operator": "OR", "items": ["BCH242Y1", {"operator": "AND", "items": ["BCH210H1", "BCH311H1"]}]}'::jsonb),
    ('BCH470H1', 'Independent Research Project', '144P', 'This course provides an opportunity for individual research with a specific topic of study. Students are mentored and supervised by research scientists and faculty associated with the University of Toronto. It provides students an opportunity to enhance and apply their knowledge and understanding learned in other courses. Direct supervision must be provided by a faculty member within the Department of Biochemistry. Not eligible for the CR/NCR option.', 'BCH473Y1', 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BCH340H1", "BCH377H1", "BCH378H1", "MGY311Y1"]}, {"operator": "AND", "items": ["BCH370H1", "BCH311H1"]}]}'::jsonb),
    ('BCH471H1', 'Independent Research Project', '144P', 'This course provides an opportunity for individual research with a specific topic of study. Students are mentored and supervised by research scientists and faculty associated with the University of Toronto. It provides students an opportunity to enhance and apply their knowledge and understanding learned in other courses. Direct supervision must be provided by a faculty member within the Department of Biochemistry. Not eligible for the CR/NCR option.', 'BCH473Y1', 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BCH340H1", "BCH377H1", "BCH378H1", "MGY311Y1"]}, {"operator": "AND", "items": ["BCH370H1", "BCH311H1"]}]}'::jsonb),
    ('BCH472Y1', 'Advanced Summer Research Project in Biochemistry', '144P', 'This course provides opportunities to pursue an original individual research project in a particular area of biochemistry, under the direct supervision of a Biochemistry Department faculty member. Students are responsible for arranging for supervision by a Biochemistry Department faculty member. To apply for enrolment, students are required to complete the application form by contacting the Course Coordinator by the end of April. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["BCH340H1", "BCH377H1"]}'::jsonb),
    ('BCH473Y1', 'Advanced Research Project in Biochemistry', '144P', 'This course provides opportunities to pursue an original individual research project in a particular area of biochemistry, under the direct supervision of a Biochemistry Department faculty member. Students are responsible for arranging for supervision by a Biochemistry Department faculty member. To apply for enrolment, students are required to complete the application form by contacting the Course Coordinator before the end of August. Not eligible for CR/NCR option.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BCH340H1", "BCH377H1", "MGY311Y1"]}, {"operator": "AND", "items": ["BCH370H1", "BCH311H1"]}]}'::jsonb),
    ('BCH478H1', 'Advanced Biochemistry Laboratory', '24L/84P', 'Experiments extend students'' technical abilities as well as their knowledge and application of practical theory. This course is designed as an advanced successor in a progression of biochemistry laboratory experiences in  BCH242Y1 and  BCH377H1 that will equip students with a spectrum of practical abilities that are of vital importance in scientific research. (Lab fees: $25)', null, 4, '{"operator": "AND", "items": ["BCH340H1", "BCH377H1", "MGY311Y1"]}'::jsonb),
    ('BCH479H1', 'Advanced Seminar in Biochemistry', '24S', 'This seminar course will foster close interactions between students and Faculty and encourage in depth discussion not only of results but the ways the results were presented and the rationales for experimental design. Critical thinking skills will be developed, as will presentation skills, as students become presenters of results and take on the role of scientist presenting and analyzing new findings. Writing skills will be developed through a written assignment. Students within the audience will also have access to the experimental papers and be encouraged to pose thoughtful questions about research and the ways that research can be communicated within the scientific community. This seminar course will foster an appreciation of scientific writing and give students a venue to develop their communication skills. The goal of the seminar course is to improve both the written and oral scientific communication skills and to increase the knowledge of key papers in Biochemistry. Note: In addition to the required courses listed in the prerequisites, students enrolling in this course need to contact the Department at biochemistry.undergrad@utoronto.ca.', null, 4, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BCH340H1", "BCH370H1"]}, {"operator": "AND", "items": ["BCH340H1", "BCH377H1"]}]}'::jsonb),
    ('BIO120H1', 'Adaptation and Biodiversity', '24L/15P', 'Principles and concepts of evolution and ecology related to origins of adaptation and biodiversity. Mechanisms and processes driving biological diversification illustrated from various perspectives using empirical and theoretical approaches. Topics include: genetic diversity, natural selection, speciation, physiological, population, and community ecology, maintenance of species diversity, conservation, species extinction, global environmental change, and invasion biology. A lab coat is required. (Lab Materials Fee: $26)', null, 4, null::jsonb),
    ('BIO130H1', 'Molecular and Cell Biology', '36L/15P', 'One of the goals of modern biology is to understand how the basic building blocks of life give rise to biological form and function. This course provides students with a common lexicon to understand the key principles and concepts in molecular and cell biology, with a focus on how the building blocks of life lead to functioning cells. (Lab Materials Fee: approximately $11). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', 'BIOA01H3,  BIO152H5', 4, null::jsonb),
    ('BIO220H1', 'From Genomes to Ecosystems in a Changing World', '24L/15P', 'Dynamics of genetic and ecological change in biological systems, from genomes to ecosystems. Evolutionary genetic and ecological perspectives on wide-ranging topics including disease, aging, sexual conflict, genetics of human differences, conservation, and global climate change. Applications of evolutionary, ecological, and molecular-genetic principles and processes. Responsibilities of human societies in a changing world. (Lab Materials Fee: $26).', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('BIO230H1', 'From Genes to Organisms', '36L/15P', 'The genome is the "book of life," providing instructions to construct an organism. This course introduces genome biology and explores how the building blocks of life are networked into functioning organisms. We will investigate how cells perceive internal and external cues, how gene expression is shaped by this perception, and how these events give rise to tissues, organs, and whole organisms. (Lab Materials Fee: approximately $16). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', 'BIO255H1', 4, '{"operator": "AND", "items": ["BIO130H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, {"operator": "AND", "items": ["CHM138H1", "CHM139H1"]}, "CHM151Y1"]}]}'::jsonb),
    ('BIO251H1', 'Form, Function and Development in Plants', '24L/12T', 'This course is an introduction to structure, function and ecology of vegetative and reproductive processes in plants with a focus on flowering plants and gymnosperms. Topics of study in lecture and laboratory tutorials include photosynthesis, transport processes, plant reproduction, patterns of plant growth and development, and the role of hormones in plant development.', null, 4, '{"operator": "AND", "items": ["BIO120H1"]}'::jsonb),
    ('BIO255H1', 'From Genes to Organisms with Advanced Laboratory', '36L/33P', 'The genome is the "book of life," providing instructions to construct an organism. This course introduces genome biology and explores how the building blocks of life are networked into functioning organisms. We will investigate how cells perceive internal and external cues, how gene expression is shaped by this perception, and how these events give rise to tissues, organs, and whole organisms. The Enhanced Laboratory provides the opportunity for greater laboratory skill development in modern investigative techniques and is intended for students interested in conducting their own laboratory research. (Lab Materials Fee: $53). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', 'BIO230H1', 4, '{"operator": "AND", "items": ["BIO130H1", {"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, {"operator": "AND", "items": ["CHM138H1", "CHM139H1"]}, "CHM151Y1"]}]}'::jsonb),
    ('BIO260H1', 'Concepts in Genetics', '48L/12T', 'This is a problem based course which discusses classical, molecular, developmental, and population genetics and genomics with emphasis on model organisms for genetic analysis.', 'HMB265H1', 4, '{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}'::jsonb),
    ('BIO270H1', 'Animal Physiology I', '24L/9P', 'Animal physiology is a biological sub-discipline that aims to understand, in physical and chemical terms, how animals work. This course uses examples from throughout the animal kingdom, in a comparative approach, to introduce and study homeostasis and the endocrine system. Accompanying laboratories reinforce concepts introduced in lectures and provide opportunities for students to experience firsthand the role that experimentation, data collection, interpretation of data, and communication of data plays in the nature of the scientific process. (Lab Materials Fee: approximately $11). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', null, 4, '{"operator": "AND", "items": ["BIO130H1"]}'::jsonb),
    ('BIO271H1', 'Animal Physiology II', '24L/9P', 'Animal physiology is a biological sub-discipline that aims to understand, in physical and chemical terms, how animals work. This course uses examples from throughout the animal kingdom in a comparative approach to introduce and study the nervous and cardiorespiratory systems. Accompanying laboratories reinforce concepts introduced in lectures and provide opportunities for students to experience firsthand the role that experimentation, data collection, interpretation of data, and communication of data plays in the nature of the scientific process. (Lab Materials Fee: approximately $11). Lab coat and safety glasses are required for use in laboratories; students are responsible for purchasing these items (approximate cost is $27).', null, 4, '{"operator": "AND", "items": ["BIO270H1"]}'::jsonb),
    ('BMS100H1', 'Introduction to Book & Media Studies', '24L/12T', 'Introduces the academic study of media in all its forms, including books and print media as well as modern electronic and digital media. Provides an overview of key theories of media, culture, and society and relates them to contemporary issues, enabling students to apply different critical approaches to their everyday experiences with media.', 'SMC219Y1,  CCT218H5,  MDSA01H3', 1, null::jsonb),
    ('BMS110Y1', 'The Printed Book', '48L', 'In this full-year seminar, students will learn about the revived art of letterpress printing. Starting with a historical overview of the printing itself—from the development of movable type onwards—and its massive impact on society, this course will teach students about the importance of printing, the development of the book as technology, and their power, then and now, to shape humanity. Topics covered will include the development of movable type and of the printing press, the emergence of books as a form of knowledge transmission, and the way both have affected the way we live our lives. Students will have an opportunity to produce printed materials using 19th and 20th century printing presses.', null, 3, null::jsonb),
    ('BMS200Y1', 'Book & Media Histories', '48L/24T', 'Traces the long history of media in culture and society, including books and other communication technologies. Covers historical developments including orality and writing, printing and the book, image and sound reproduction, wired and wireless communication, electronic and broadcast media, and contemporary digital media. Examples and case studies will be drawn from a variety of different sociocultural contexts, media industries, and creative practices.', 'SMC219Y1', 3, null::jsonb),
    ('BMS201H1', 'Information Literacy, Writing, and Research for Book & Media Studies', '24L', 'Develops foundational skills for students in Book & Media Studies, including academic writing, information literacy, media literacy, citation, qualitative and quantitative research, primary and secondary sources, library resources, and practical techniques for analyzing different forms of media.', 'ACMB01H3', 1, null::jsonb),
    ('BMS300H1', 'Special Topics in Book & Media Theories', '24L', 'This course offers students the opportunity to explore key issues and questions in the theory of books and media. The exact topic will change depending on the instructor. Possible topics include but are not limited to: specific theorists, theoretical schools, or traditions; theories of particular aspects or forms of media; theoretical debates or comparative approaches; interdisciplinary theory.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS301H1', 'Special Topics in Book & Media Cultures', '24L', 'This course offers students the opportunity to explore cultural questions and issues related to books and media. The exact topic will change depending on the instructor. Possible topics include but are not limited to: cultural studies approaches; issues of identity and representation; media and ideology; national, regional, or sub-cultural media; cross-cultural analysis; media genres, styles, and conventions.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS302H1', 'Special Topics in Book & Media Histories', '24L', 'This course offers students the opportunity to explore book and media history and historical research. The exact topic will change depending on the instructor. Possible topics include but are not limited to: particular periods or areas in book and media history; histories of specific media forms or styles; histories of media representation; historical research methods and approaches; industrial histories; comparative histories.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS303H1', 'Special Topics in Book & Media Industries', '24L', 'This course offers students the opportunity to explore the industrial contexts in which books and media are made. The exact topic will change depending on the instructor. Possible topics include but are not limited to: particular media industries; national or regional publishing or media industries; approaches to studying media and cultural industries; specific aspects of media production, distribution, or reception; the relationship between different media industries; convergence and consolidation in media industries.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS311H1', 'Open Topics in Book & Media Studies', '24L', 'This course is reserved for unique topics not already covered in other courses. The exact topic will change depending on the instructor.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS312Y0', 'Open Topics in Book & Media Studies', '48L', 'Offered as part of the Summer Abroad Program, this course provides students the opportunity to explore book and media cultures and historical research. The exact topic will change depending on the instructor. Possible topics include but are not limited to: particular periods or areas in book and media history; histories of specific media forms or styles; histories of media representation and cultures; historical research methods and approaches; cross-cultural analysis; national, regional, or sub-cultural media; comparative histories and culture. Students should check the Summer Abroad Program website for details.', null, 1, null::jsonb),
    ('BMS314H1', 'Media Revolutions', '24L', 'This class offers a deeper examination of the intersections of technology and human thought, perception and culture. The advent of new media technologies, from literacy through to social media, will be examined as revolutions in technology, semantic fields of cultural meaning-making and human action. Students gain a strong focus on technological advancements as insights into cross-cultural change at significant turning points in book and media history.', 'SMC314H1', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS316H1', 'Social Media & Digital Platforms', '24L', 'Social media, digital platforms, and networked technologies are deeply embedded in our contemporary lives, both shaping and shaped by users. But what are their social, cultural, political, and economic impacts? What consequences do they have for how we think, feel, socialize, work, play, and understand ourselves? Students in this course will explore, examine, and debate these questions with reference to their everyday experiences and current examples.', 'CCT331H5,  MDSB15H3', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS319H1', 'Media Ethics', '24L', 'Provides students with a theoretical foundation that enables them to identify and analyze ethical issues in mainstream and non-mainstream media. Traditional principles of journalistic truth-seeking, objectivity, and minimizing harm are revisited in the light of global, interactive media, produced by both citizens and professionals.', 'MDSC63H3', 2, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS320H1', 'Media and Trauma', '24L', 'This course explores the intersection of media studies and cultural trauma theory through decolonizing frameworks. Students will learn theoretical foundations of cultural trauma theory with which they will engage mixed media narratives including film, books, music, video games and social media. Throughout the semester, we will focus on the construction of survivor-centered narratives amidst norms of popular media cultures and industries.', 'BMS301H1 (Special Topics in Book and Media Cultures: Trauma & Media), offered in Fall 2021, Summer 2022, Fall 2022;  BMS301H1 (Special Topics in Book and Media Cultures: Books, Media & Music), offered in Winter 2022;  SMC317H1 (Books, Media, and Music: Trauma), offered in Fall 2020 and Summer 2021', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS331H1', 'The History of the Book: Elements of Bibliography and Print Culture', '24L/12T', 'An exploration of the history of the book from ancient inscriptions to e-books. This course develops an awareness of the interplay between material object and conceptual categories in book history by focusing on significant episodes in the evolution of the book as a medium, such as the rise of the context and the introduction of print. This course also delves in the practices of bibliography, the features of typography, and the material details of the printing process, while also highlighting the interdisciplinary nature of book history from a global perspective. Typically, this course will involve in-person workshops and visits to print studios and rare books collections on campus.', 'SMC228H1', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS332H1', 'The History of Reading: Readers, Readerships, Reception', '24L', 'This course explores the history of reading. Attention is given to the pivotal episodes in this history with a focus on its changing modes and shifting cultural significance. By surveying the habits, institutions, and aims of reading, students in this course will gain a greater understanding of its rich history and its complex evolution, and will enable them to reflect on the critical place of reading in their daily lives.', 'SMC229H1', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS333H1', 'Impacts of Advertising Typography', '24L', 'Creative and eye-catching typography has long been used to sell products and services. In this course, the history of advertising typography will be explored in connection with its influence on popular culture, consumer markets, and the on the rise of typographic trends. A special emphasis will be placed on the development and use of wood type during the nineteenth century and its role in the proliferation of advertising media. Students will have an opportunity to produce printed materials using 19th and 20th century printing presses.', null, 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS350H1', 'Propaganda and Media', '24S', 'This course assesses ways in which governments, political parties, news agencies and other groups and institutions use media to shape particular messages or describe current events. Each week the seminar will focus on a major historical event, the manner in which it was reported and interpreted, and principal challenges to that interpretation. A wide variety of media will be analyzed including: books, newspapers, film, radio, television, and the internet. Events such as the War on Terror, the Great War, the Dreyfus Affair, the Irish Famine, and the "Red Scare" are among some of the topics that will be discussed. Students will prepare unique assignments akin to the work done by communications officers.', 'SMC470H1', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS351H1', 'The Illustrated Dante', '24L', 'This course will explore the multifaceted relationship between text, image, and culture from late medieval illuminated manuscripts up to the present day through an examination of illustrated versions of Dante''s Divine Comedy. As early as the fourteenth century and into the present day, the reading and reception of Dante Alighieri''s Divine Comedy has been tied to its presentation in illustration. Students will also study how engagements with Dante''s poem have given life to visual responses and creative re-elaborations.', 'BMS302H1S (Special Topics in Book & Media Histories: The Illustrated Dante) offered in Winter 2024.', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS352H1', 'Media and the Myths of Romance', '24L', 'This course explores the intersections of historical and contemporary media narratives, technologies, and industries in the construction and representation of mainstream romance narratives. Romance tropes and myths will be deconstructed through feminist, queer, disability and decolonial theories of gender, class, sexuality, race and body image at the intersections of film, music, literature, tv, video games and/or social media to expose marginalizing and disempowering tropes at the center of dominant constructions and representations of romantic love.', 'BMS301H1 (Special Topics in Book & Media Cultures: Media & The Myths of Romance) offered in Winter 2024.', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS353H1', 'Fandom, Fan Fiction, and Participatory Culture', '24L', 'In this course, students will explore the idea of fandom, the history of fandom and fandom scholarship, fan activities across the globe, and what it means to be a fan. By applying the broad conceptual frame of participatory culture, the course will examine a wide range of fan creations. It will also examine the evolution of fan interaction with the objects of fandom, with the media industry, and with society at large. Students will have the opportunity to explore and create some fan artefacts of their own, and in the process, to dive deep into the complex world of fandom.', 'BMS301H1 (Special Topics in Book & Media Cultures: Fandom and Fan Fiction) offered in Fall 2023.', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS354H1', 'Transnationalism and East Asian Media', '24L', 'This course examines East Asian media industries and cultures in a transnational context. Topics to be explored include media production, distribution, reception, and regulation; representation, identity, and nationhood; cross-cultural exchange; and the global circulation of East Asian media. Media and cultural forms examined may include print media, film, television, radio, news media, popular music, animation, comics, video games, digital media, and social media.', null, 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS380H1', 'Staging Britishness from Shakespeare to the BBC', '24L', 'This course explores various approaches to the staging of national identity and history in Britain from the sixteenth century to the present day. Students will study a range of dramatic works and examine evolving ideas of what can constitute a national stage or theatre. Subjects to be explored include ceremonial royal pageantry from Elizabethan England to televised coronations and investitures; the history of television, radio, and the BBC as a communal playhouse; arts festivals, national exhibitions, and the amateur pageant play; revisionist stagings of Shakespeare''s history plays; challenges to ideas of Britishness in England, Scotland, and Wales. (Offered in alternate years.)', null, 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('BMS381H1', 'Cool Britannia? Popular Music Culture and Postwar Britain', '24L', 'Since the 1960s "British Invasion," British popular music has been associated with the cultural strength of modern Britain and the voice and character of its ''people.'' Through an examination of major musical movements from the 1950s to the present day (including skiffle, punk, 2-Tone, New Romantic, Britpop, grime), students will explore how these perceptions have been perpetuated and challenged through various media amidst evolving understandings of nation, class, race, gender, and empire. Topics include the role of pirate and state-sanctioned radio; the history of music magazines; and the relationship between music and film, television, fashion, photography, and the national media. Offered in alternate years.', null, 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS382H1', 'Fortune-Telling and Media Throughout the Centuries', '24L', 'From the astrologers in ancient Babylon to Tarot card printers in early modern Europe and contemporary AI, fortune-telling has been practiced for millennia across various cultures. This course examines the global history of fortune-telling and its legacy of responsive adaptiveness to diverse changes in media technology. Topics include early observations of the heavens, the implications of the print revolution and definitions of readership, the rise of broadcast media, the invention of the internet, and contemporary technologies.', 'BMS301H1 (Fortune Telling and Media) offered in Fall 2024.', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS386H1', 'Book and Media Internship', '48P', 'Credit is offered to a student doing an internship with a media organization. A faculty supervisor assesses and assigns the necessary written component cognate to the internship. Students are responsible for securing their own internship. A description of the internship, working bibliography, marking scheme, and academic supervisor''s support must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/bms-internship-form or from the SMC Principal''s Office, smc.programs@utoronto.ca. Enrolment in this course is intended for Book and Media Studies Majors not enrolled in the Arts & Science Internship (ASIP) stream of the program. Not eligible for CR/NCR option.', 'SMC386H1', 3, '{"operator": "OR", "items": [{"operator": "AND", "items": ["BMS100H1", "BMS200Y1", "BMS201H1"]}, "SMC219Y1"]}'::jsonb),
    ('BMS387H1', 'Advertising and Media', '24L', 'This course presents a critical media studies approach to advertising and consumer culture, past and present. Advertising, marketing, branding, and promotion play a central role in capitalist societies and media industries, reflecting and refracting dominant cultural attitudes and ideologies. How does advertising shape what and how we consume? What are its social, cultural, economic, and environmental impacts? Students will learn to analyze the form, content, and ideology of advertisements, and think critically about the advertising they are subjected to in everyday life.', 'CCT316H5,  MDSB03H3', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS389H1', 'Libraries, Special Collections, and Archives', '24L', 'This course takes a hands-on approach to introduce students to different types of printed and manuscript primary and secondary sources. Students will learn to apply information literacy concepts, and library and archival theories to the analysis, critique, evaluation, and use of materials drawn from the University of Toronto''s collections of library, rare book, and archival materials. This course will touch on current topics within information literacy, including, but not limited to, digitization, the ethical collection and use of oral and written information; post-colonial practices; racial, cultural, and gender representations; and archival neutrality.', null, 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS391H1', 'The Media Franchise', '24L', 'Reflective of the broader logics of media convergence, media franchises spread their commercial interests and imaginary worlds across many multiple media. For media industries, franchises maximize profits by linking together movies, TV series, books, comics, games, toys, merchandise, and promotional paratexts to encourage consumption. At the same time, they are a platform for new forms of serial narrative, world-building, and transmedia storytelling, and generate vibrant, diverse fan cultures that are sometimes at odds with franchise producers. Drawing on a wide range of scholarly and critical work, this course examines popular media franchises from historical, economic/industrial, formal/aesthetic, and sociocultural perspectives.', 'SMC301H1 (The Media Franchise, offered in Winter 2018, 2019, 2020, and 2021),  BMS303H1 (The Media Franchise, offered in Fall 2022)', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS392H1', 'Media Identities', '24L', 'An exploration of media''s influence on the constructions and representation of identity and power relations across race, gender and class in individual and collective spheres. Applies a social justice and intersectional framework to media technologies and industries in order to expose socio-political influence on identity and to position media consumption and production as potential vehicles for restorative mediations of marginalized identities.', 'CCT314H5,  MDSC02H3', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS393H1', 'Media Ecology', '24L', 'This course presents an advanced introduction to Media Ecology, an interdisciplinary field of inquiry which examines how media environments affect human affairs, understanding, feelings, and values. Building on the assigned readings, students will examine the various theories of Media Ecology, honing their skills of assessment, analysis, criticism, and reflection. An interdisciplinary approach informed by literature, philosophy, anthropology, semiotics, aesthetics, and history will provide students with the opportunity to critically evaluate some crucial and controversial issues facing contemporary society.', 'BMS300H1 (Media Ecology) offered in Winter 2022 and Fall 2022', 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS394H1', 'Independent Study in Book and Media Studies', null, 'An independent research project to be proposed by the student and supervised by a full-time faculty member affiliated with the Book & Media Studies Program. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Students must have approval of an instructor willing to supervise the project. Final approval is granted by the program director. Not eligible for CR/NCR option.', 'BMS395Y1', null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 3.0, "department": "BMS"}]}'::jsonb),
    ('BMS395Y1', 'Independent Study in Book and Media Studies', null, 'An independent research project to be proposed by the student and supervised by a full-time faculty member affiliated with the Book & Media Studies Program. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Students must have approval of an instructor willing to supervise the project. Final approval is granted by the program director. Not eligible for CR/NCR option.', 'BMS394H1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": "BMS"}]}'::jsonb),
    ('BMS400H1', 'Advanced Topics in Book & Media Theories', '24S', 'This course is an advanced seminar on theoretical approaches to books and media. Students can expect to take an active role in leading course discussions and developing their own research projects. The exact topic will change depending on the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS401H1', 'Advanced Topics in Book & Media Cultures', '24S', 'This course is an advanced seminar on the cultural aspects of book and media studies. Students can expect to take an active role in leading course discussions and developing their own research projects. The exact topic will change depending on the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS402H1', 'Advanced Topics in Book & Media Histories', '24S', 'This course is an advanced seminar on the history of books and media. Students can expect to take an active role in leading course discussions and developing their own research projects. The exact topic will change depending on the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS403H1', 'Advanced Topics in Book & Media Industries', '24S', 'This course is an advanced seminar on the industrial and economic aspects of books and media. Students can expect to take an active role in leading course discussions and developing their own research projects. The exact topic will change depending on the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS411H1', 'Advanced Open Topics in Book & Media Studies', '24S', 'This seminar is reserved for unique topics not already covered in other courses. The exact topic will change depending on the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS420H1', 'Bookbinding Then and Now', '24L', 'A survey of the history and development of bookbinding technologies from the sixteenth century to the modern day. Through a combination of lectures and tutorials, this course will explore how the construction of books as physical objects has influenced the transmission of knowledge and the development of society. Special attention is paid to binding structures. Students will have an opportunity to fabricate book objects.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS421H1', 'Histories of Letterpress Printing', '24L', 'In this senior seminar course, students will have a hands-on opportunity to learn about the Western letterpress tradition from its fifteenth century emergence to its nineteenth century rise as an industrial trade. Framed by the apprenticeship model that supported the growth of printers as a trade, where apprentices would train under a master to become a journeyman, this course will expose students to all steps involved in producing letterpress materials set within a historical context. Social issues associated with the printing industries, such as working conditions and the rise of guilds, will also be explored. Students will have an opportunity to produce printed materials using 19th and 20th century printing presses.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS430H1', 'Mindful Media', '24S', 'This seminar integrates critical media studies with mindfulness pedagogy to yield an experiential and theoretical exploration of critical media literacy. A critical media studies lens is applied to various topics that dominate contemporary mediascapes, such as violence, mental health, body image, etc. Through experiential practice and study of mindfulness pedagogy, students develop practices of critical media literacy able to be applied to their own lives and in future work/study in various media industry and educational praxes.', 'BMS401H1 (Advanced Topics in Book & Media Cultures: Mindful Media: Theory & Practice) offered in Winter 2024.', 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS431H1', 'Media and Environmental Justice', '24S', 'This course explores the relatively new field of ecomedia to consider how media technologies, mainstream media practices and dominant media narratives intersect and contribute to global environmental crises. Students will engage in individual and collaborative qualitative and experiential research methods to apply critical media literacy skills and decolonial lenses to reimagine how contemporary media practices can promote environmental justice and/or cultivate a reparative eco-consciousness on individual and collective levels.', 'BMS401H1 (Advanced Topics in Book & Media Cultures: Environmental Justice & Media) offered in Winter 2023.', 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS432H1', 'The Game Industry', '24S', 'Commercial video games are an extremely profitable global industry, emblematic of how media is produced, distributed, marketed, and monetized in contemporary capitalism. Students will examine a variety of issues, including the history of the industry, consolidation and concentration of ownership, digital distribution and platformization, systemic sexism, racism, and discrimination in the industry, labour and collective organizing, independent and alternative game production cultures, local, regional, national and transnational contexts, and more. To make sense of these complex phenomena, students will learn to apply critical lenses and methods from game studies, media industry studies, and cultural studies. No previous experience or expertise with video games or knowledge of the game industry is required to take this course.', 'BMS403H1 (Advanced Topics in Book & Media Industry: The Game Industry) offered in Winter 2024.', 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS433H1', 'Video Games and Culture', '24S', 'From early mainframe computers to arcades, home video game consoles, mobile devices, VR, and beyond, digital games have become increasingly central within contemporary culture. Why do we make and play games? How do games produce experiences, make meaning, and reflect or refract ideology, and what impact do they have on players? Who gets to make, play, and find representation in games, and who is left out? What role do games play in the contemporary media ecosystem? Through scholarly research and interactive examples, this seminar-style class will explore digital games and culture from a variety of critical perspectives, including history, industry, technology, culture, politics, and aesthetics. No previous experience or expertise with video games is required.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS434H1', 'Boys'' Love and the Culture of Desire', '24L', 'The Boys'' Love genre of homoerotic stories primarily written by women for women originated in East Asia and has gained international popularity in recent years. From novels and manga to live action TV series, the world of Boys'' Love is ever expanding to become increasingly more inclusive and global, reflecting a fast-changing world and an amazingly multifaceted understanding of desire. This class looks at Boys'' Love from its historical origins to its modern manifestations, to explore how the genre reflects the hidden desires of its international audience communities.', 'BMS401H1 (Advanced Topics in Book & Media Cultures: Boys'' Love and the Culture of Desire) offered in Winter 2023.', 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "BMS"}]}'::jsonb),
    ('BMS494H1', 'Independent Study in Book and Media Studies', null, 'An independent research project to be proposed by the student and supervised by a full-time faculty member affiliated with the Book & Media Studies Program. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Students must have approval of an instructor willing to supervise the project. Final approval is granted by the program director. Not eligible for CR/NCR option.', 'BMS495Y1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 6.0, "department": "BMS"}]}'::jsonb),
    ('BMS495Y1', 'Independent Study in Book and Media Studies', null, 'An independent research project to be proposed by the student and supervised by a full-time faculty member affiliated with the Book & Media Studies Program. A full proposal including a course description, working bibliography, marking scheme, and approval from your academic supervisor must be submitted for approval by the Program Coordinator and Director. More information and application forms are available at https://stmikes.utoronto.ca/academic-forms or from the SMC Principal''s Office, smc.programs@utoronto.ca. Completed forms must be submitted to the Principal''s Office by the first day of classes in September/May for F courses, or January/July for S courses. Meeting times are determined in consultation with your supervisor, and may be in person or online as appropriate. Students must have approval of an instructor willing to supervise the project. Final approval is granted by the program director. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 6.0, "department": "BMS"}]}'::jsonb),
    ('BPM100H1', 'The Art & Science of Human Flourishing', '12L/12P', 'A multi-cultural survey of recipes for a life of “flourishing,” through satisfaction, well-being, resilience, and accomplishment, as well as critical scholarship on concepts and practices of human flourishing. Students explore perspectives from the sciences and the humanities about what it means to flourish across diverse cultures and contexts, each week covering a specific theme and set of practices that expand self-awareness, enhance social connectivity, and facilitate purpose and passion.', null, 2, null::jsonb),
    ('BPM214H1', 'Socially Engaged Buddhism', '24L', 'Explores how Socially Engaged Buddhism has developed in response to global conversations on systemic oppression, climate justice, equity, decolonization, and trauma. We examine the roots of Engaged Buddhism in countries such as Vietnam, China & Taiwan, Sri Lanka, Thailand, and India, and its transformation into a global movement. Themes include Buddhist environmental activism, and Buddhist protest movements, along with research on the application of Buddhist teachings in healthcare, education, business, and the criminal justice system.', 'NEW214H1,  NEW214Y1', 3, null::jsonb),
    ('BPM232H1', 'Buddhism and Psychology', '36L', 'An overview of the encounter between Buddhism and psychology over the last century, with cross-disciplinary study of topics such as self, embodiment, impermanence, suffering, liberation, and insight. We explore how (and why) scientists, psychologists, and Buddhist reformers have reinterpreted Buddhism as “science” and how Buddhist contemplative practices such as mindfulness or compassion training have been transformed and promoted by modern psychology.', 'NEW232H1,  NEW232Y1', 2, null::jsonb),
    ('BPM330H1', 'Mindfulness-Informed Interventions for Mental Health', '36L', 'An exploration of how mindfulness-based approaches are being used in biomedical mental health interventions. We study mindfulness from historical, societal, structural, cultural, professional, and personal perspectives, with an emphasis on its Buddhist foundations and on concepts of the embodied mind. We look at how recent socio-political phenomena are inspiring diverse applications and adaptations of mindfulness-based interventions.', 'NEW330H1', 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('BPM332H1', 'Buddhism and Psychotherapy', '36L', 'A multi-cultural and interdisciplinary study of therapeutically-oriented practices and theories of the mind. Areas considered include positive psychology, psychoanalysis, cognitive-behavioural therapy, mindfulness meditation, and Jungian psychology, with comparison to various Buddhist teachings and practices.', 'NEW332H1', 2, null::jsonb),
    ('BPM333H1', 'Buddhism and Cognitive Science', '36L', 'An interdisciplinary exploration of how cognitive science may connect with Buddhist terms, concepts, and practices, studying topics such as wisdom, mindfulness, meditation, insight, self-control, flow, or mystical experience.', 'NEW333H1', 2, null::jsonb),
    ('BPM334H1', 'Science of Wisdom: Buddhist and Western Traditions', '36L', 'Provides a conceptual and contemplative interdisciplinary exploration of “wisdom traditions.” Buddhist approaches to self-actualization and wisdom will be compared to traditions from Mesopotamia, classical Greece, Christianity, the Renaissance, etc. Coursework includes guided experiential exercises for various traditions.', 'NEW334H1', 2, null::jsonb),
    ('BPM335H1', 'Meditation and the Body', '36L', 'An overview of scientific research on the psychological and neurophysiological effects of meditation. We explore the effects of different meditation styles on brain structure, brain activity, neurochemistry and other biological processes. Effects of meditation on mental health, pain, social behavior, aging, memory, and cardiovascular function are also a major focus. The use of meditation in the treatment and prevention of illness is critically reviewed.', 'NEW335H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('BPM336H1', 'Special Topics in Buddhism, Psychology and Mental Health', '36L', 'Topics vary from year to year depending on the instructor.', null, 2, null::jsonb),
    ('BPM337H1', 'Special Topics in Buddhism, Psychology and Mental Health', '36L', 'Topics vary from year to year.', null, null, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}]}'::jsonb),
    ('BPM338H1', 'Exploring Mindful Awareness', '36L', 'An overview of mindfulness as a systematic investigation of subjective experience, with a survey of classic descriptions and contemporary scientific literature. Students will explore meditative practices in class and maintain a meditation practice outside class.', 'NEW338H1,  NEW432H1 (Advanced Special Topics in Buddhism, Psychology and Mental Health: Cultivating Consciousness), offered in Fall 2012, Fall 2013, Fall 2014, Summer 2015, and Winter 2016', 2, '{"operator": "OR", "items": ["BPM232H1", "NEW232Y1", "BPM332H1", "BPM333H1", "BPM334H1", "BPM335H1", "BPM339H1"]}'::jsonb),
    ('BPM339H1', 'Mind, Consciousness and the Self', '36L', 'An interdisciplinary study of theories of mind, consciousness, and the self, placing Buddhist traditions in dialogue with scientific theories of the mind in psychology.', 'NEW339H1', 2, null::jsonb),
    ('BPM381H1', 'Buddhist Perspectives on Current Social Issues', '36L', 'Explores teachings and principles in Buddhist canonical sources and considers their application to a wide range of social, political, and environmental crises we are facing today, including climate justice, systemic racism, burnout and mental health. We explore how Buddhist teachings are applied and adapted across different sectors of society including healthcare, education and business.', 'NEW214Y1/  NEW336H1 (Special Topics in Buddhism, Psychology and Mental Health: Buddhist Perspectives on Current Social Issues), offered in Winter 2020 or Winter 2021/  BPM336H1 (Special Topics in Buddhism, Psychology and Mental Health: Buddhist Perspectives on Current Social Issues), offered in Winter 2022', 2, null::jsonb),
    ('BPM432H1', 'Advanced Research in Meditation, Psychology and Neuroscience', '36L', 'This seminar-based course prepares students for advanced research on meditation by exposing them to diverse theories, tools and techniques used in the field. Students will learn about the scientific method and develop critical thinking skills; critique scientific research articles on meditation; practice communication skills; and propose their own original study on meditation.', null, 2, null::jsonb),
    ('BPM433H1', 'Advanced Exploration of Buddhist Psychology and Practice', '36S', 'An in-depth, interdisciplinary exploration of how Buddhist teachings are set in conversation with contemporary scientific research on topics such as suffering, wellbeing, and compassion, through a mixture of lecture, textual analysis, discussion, and hands-on experiential practice.', null, 2, null::jsonb),
    ('BPM438H1', 'Mindfulness Meditation: Science and Research', '36S', 'An exponential increase of scientific research on aspects of Buddhist theories of mind and mindfulness meditation has contributed to the growing popularity of mindfulness across the sectors of healthcare, education and business. Examines the theoretical and empirical basis of mindfulness-based interventions and applications in healthcare settings and beyond. Critically addresses the roots of mindfulness, current models and adaptations, relevant applications, interventions and outcomes. Quantitative and qualitative research methodology will be reviewed, and conceptual, methodological, statistical, and interpretive limitations of the scientific literature will be discussed. The course aims to build scientific literacy skills through the assessment, critique, and discussion of peer reviewed journal articles.', 'NEW438H1', 5, '{"operator": "OR", "items": ["PSY201H1", "SOC202H1", "STA220H1"]}'::jsonb),
    ('BPM498H1', 'Advanced Topics in Buddhism, Psychology and Mental Health', '24S', 'An upper-level seminar. Topics vary from year to year, depending on the instructor.', null, null, '{"operator": "AND", "items": ["BPM232H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('BPM499H1', 'Advanced Topics in Buddhism, Psychology and Mental Health', '24S', 'A joint graduate/undergraduate upper-level seminar. Topics vary from year to year, depending on the instructor. Consult the Program Office for course enrolment procedures.', null, null, '{"operator": "AND", "items": ["BPM232H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('CAR120Y1', 'Introduction to Caribbean Studies', '48L/24T', 'Explores the complex and diverse languages, geographies, regional and national histories, cultural practices, intellectual traditions and political and economic landscapes of the Caribbean region, its people and its diasporas. Students will be introduced to the main questions, themes, and debates in Caribbean Studies. Lectures and readings develop the skills to take an interdisciplinary approach to Caribbean Studies. This is a team taught course.', 'NEW120Y1', 3, null::jsonb),
    ('CAR215H1', 'Caribbean Foodways Across History, Culture and Diaspora', '24L', 'Examines the historical roots of regional Caribbean food from the colonial period to the present day, and then moves to study Caribbean food in the global and Caribbean-Canadian diasporas, in the literary imagination, as a marker of personal, group and national identity, and as cultural expression.', 'NEW315H1,  CAR315H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CAR220H1', 'Comparative Caribbean Literature', '24L', 'Introduction to the rich and multi-linguistic literary traditions of the Caribbean and its diaspora, focusing on both canonical and emergent texts of Caribbean literature. Texts not originally written in English are read in translation.', 'NEW220H1,  NEW222H1,  NEW222Y1,  NEW223Y1', 1, null::jsonb),
    ('CAR221H1', 'Comparative Caribbean Literature and Visual Culture', '24L', 'Focuses on recent literary and visual texts produced in the last decade, from the Caribbean, insular and continental, and its diaspora. Texts not originally written in English are read in translation. While  CAR220H1 is an excellent companion course,  CAR221H1 can be taken independently.', 'NEW221H1,  NEW222H1,  NEW222Y1,  NEW223Y1', 1, null::jsonb),
    ('CAR225H1', 'Caribbean Societies', '24L/12T', 'Offers an interdisciplinary introduction to Caribbean sociology, focusing on the writings of thinkers and scholars from the era of decolonization to the more contemporary period. Themes may include: colonial encounters in the making of Caribbean societies; the role of religion; popular consciousness; histories of capitalism and exploitation; the relationship between political institutions and the wider society; "development", dependency and "underdevelopment".', 'NEW225H1,  NEW224Y1', 2, null::jsonb),
    ('CAR226H1', 'Caribbean Political Thought', '24L/12T', 'Examines currents of Caribbean political thought from the Haitian Revolution to the present. Themes may include: struggles for independence and liberation, particularly the Haitian and Cuban Revolutions; theories of dependency; Caribbean political systems; regional integration; contemporary political issues facing Caribbean societies today; analyses of capitalism by Caribbean thinkers.', 'NEW226H1,  NEW224Y1', 2, null::jsonb),
    ('CAR316H1', 'Caribbean Religions', '24L', 'Explores the complex and dynamic practices, philosophies and political and cultural contexts of Caribbean religions. Topics may include the profound impact - in both the Caribbean and its diasporas - of Caribbean Christianities, Hinduism and Islam as well as Afro-Creole religions such as Vodun, Rastafari and Santeria.', 'NEW316H1,  NEW329H1 (Special Topics in Caribbean Studies: Caribbean Religions), offered in Fall 2014 and Fall 2015', 2, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR317H1', 'Caribbean Women Writers', '24L', 'A critical feminist reading of selected works of fiction, poetry and essays by Caribbean women writers. The aim is to appraise the development of this literature, situate texts within the key social and political debates which have influenced the region''s literary output, as well as to consider the implications of the environments within which these writers function.', 'NEW317H1,  WGS330H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CAR321H1', 'Caribbean Visual Arts, Social Media and Performance', '24L', 'Explores themes relating to visual arts, social media and theatre in the Caribbean. Topics may include: theatre, film, mixed media arts, the role of the internet and online publishing in the arts and the relationship between artists, the state and wider society.', 'NEW321H1', 1, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR324H1', 'Capitalism and Crisis in the Caribbean', '24L', 'This upper level course examines the interplay between wider global processes and intra-regional responses that together help shape contemporary Caribbean realities. Topics include: economic crisis and structural adjustment; tourism; the agricultural sector; the Caribbean Single Market and Economy; migration and diaspora.', 'NEW324H1,  NEW324Y1', 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR325H1', 'Caribbean Women Thinkers', '24L', 'An examination of the historical and political significance of writings (literary, political, scholarly) by Caribbean women who engage problems within Caribbean culture and provide insights into the endeavours of the peoples of the region.', 'NEW325H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CAR328H1', 'Caribbean Indentureship and its Legacies', '24L', 'Explores indentured migration and its legacies from the 17th century through to the present. Encourages students to think comparatively and transnationally about indentureship and diaspora, as well as indentured migration''s relationship to contract and labour law.', 'NEW328H1,  NEW326Y1', 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR329H1', 'Special Topics in Caribbean Studies', '24L', 'An upper level course. Topics of study vary from year to year.', null, null, null::jsonb),
    ('CAR332Y0', 'Puerto Rican Culture and Environment', '48L', 'Based on readings, lectures, experiential activities and discussions,  CAR332Y0 examines the cultural and environmental history of Puerto Rico. The course explores debates on colonialism, capitalist modernity, development, ecosystems, religion, race and politics. Such analysis will help with the consideration of Puerto Rico as the last colony of the Americas within the larger context of the Caribbean. The course will include on-site excursions related to the lectures and reading material covered. This course will be taught in English.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CAR342Y0', 'The Dominican Republic: Culture and Environment', '48L', 'This course examines the cultural and environmental histories of the Dominican Republic. It traces key moments in the nation''s history which have been significant for both the environmental destiny and the cultural character of the society. We will pay special attention to the social and ecological consequences of the nation''s tourist industry in the 21st century. In the process we cover a range of issues concerning global capitalism, ecopolitics, race and cultural production. The course includes weekly excursions and will be taught in English.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CAR421H1', 'Global Perspectives on the Haitian Revolution', '24S', 'Examines the colonial pre-history of the Haitian Revolution (1791-1804). Explores how this transatlantic revolution unfolded, including the emancipation of slaves, Toussaint, Louverture, and the roles played by Spain, the United States and Britain. A reflection on the Revolution in contemporary literature and film.', 'NEW421H1', 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR422H1', 'Caribbean Regionalism', '24S', 'In a public lecture in 1958, Trinidadian CLR James described Federation as the means to "accomplish the transition from colonialism to national independence." This course explores the shift from James'' vision to Jamaican economist Norman Girvan''s observation that contemporary "...governments tend to perceive supranationality as less an exercise in collective sovereignty and more a diminution of national sovereignty." Among the topics to be considered are: histories of regionalism; formal and informal dimensions of regional identity-making practices; freedom of movement; governance mechanisms; and widening and deepening debates, with particular reference to the non-Anglophone Caribbean and Latin America.', 'NEW422H1,  NEW329H1 (Special Topics in Caribbean Studies: Caribbean Regionalism), offered in Winter 2018;  NEW423H1 (Special Topics in Caribbean Studies: Caribbean Regionalism), offered in Winter 2019', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('CAR426H1', 'Special Topics in Caribbean Studies', '36S', 'An upper level seminar. Topics vary from year to year, depending on the instructor.', null, null, null::jsonb),
    ('CAR426Y1', 'Special Topics in Caribbean Studies', '72S', 'An upper level seminar. Topics vary from year to year, depending on the instructor.', null, null, null::jsonb),
    ('CAR427H1', 'Caribbean Diasporic Narratives: London, Paris, Toronto, Berlin, New York', '24S', 'Focusing on London, Paris, Toronto, Berlin and New York as major conduits through which the migratory flow of Caribbean literary production takes place, this course will explore both foundational and emergent works of fiction from the English, French and Spanish Caribbean.', null, null, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR428H1', 'Caribbean Migrations and Diasporas', '24S', 'Examines Caribbean migration in the post-slavery era. Topics include: Caribbean diasporas in the West; labour migrations such as the Panama Canal migration; Caribbean migrant communities in Central America; intra-regional migrations between the Caribbean islands; ''guest worker'' programs; remittances and their impact; heritage tourism and ''return'' migrations.', 'NEW428H1,  HISC70H3', 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR429H1', 'Caribbean Diaspora in Canada', '24S', 'Explores the transnational circuits through which the Caribbean diaspora makes a living and makes life in contemporary Canada. How do we make sense of the Caribbean experience in Canada? What might an engagement with the Caribbean teach us about Canada as a diasporic space?', 'NEW429H1,  NEW329H1 (Special Topics in Caribbean Studies: Travels and Tribulations), offered in Summer 2013 and Summer 2014', 3, '{"operator": "OR", "items": ["CDN355H1", "HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('CAR499H1', 'Advanced Topics in Caribbean Studies', '24S', 'A joint graduate/undergraduate upper-level seminar. Topics vary from year to year, depending on the instructor. Consult the Program Office for course enrolment procedures.', null, null, '{"operator": "AND", "items": ["CAR120Y1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('CAS100H1', 'Locating Asia: An Introduction to Contemporary Asian Studies', '24L/6T', 'This course provides an introduction to Contemporary Asian Studies, focusing on the rapid social, political, economic, and cultural changes taking place in the dynamic regions of East Asia, South Asia, and Southeast Asia.', null, 3, null::jsonb),
    ('CAS200H1', 'State Power and Social Diversity in Asia', '24L', 'This course is an introduction to Contemporary Asian Studies. It covers detailed case study material from South Asia, Southeast Asia, and East Asia. It introduces students to the interdisciplinary study of political, sociocultural and economic interactions among these regions, as well as the transnational forces shaping internal dynamics throughout Asia. In addition, it examines the ways that forces stemming from Asia are affecting global processes, pushing scholarship to engage questions about colonialism, nationalism, "race," religion, markets, urbanization, migration, and mass mediated culture. This course provides preparation for more advanced courses on Asia and globalization and provides an introductory gateway for the Contemporary Asian Studies major and minor. May be taken in the first year of studies.', null, 3, null::jsonb),
    ('CAS201H1', 'Global Asian Studies: Insights and Concepts', '24L', 'This course addresses Asia empirically in contemporary global formations and as an idea in the global imagination. It introduces students to concepts and theories central to scholarship on Asia and its transnational formations. It provides foundational theoretical and conceptual material to understand global issues as they play out in the politics, economies, cultures and contemporary social worlds of contemporary Asian sites. Interdisciplinary analytical and research concepts are introduced to provide area studies grounding. This course provides preparation to delve into deeper research on Asia connected to broad questions about the natures of democracy, authoritarianism, market formation, social justice, and the media of cultural expression. It informs students aiming to take more advanced courses on Asia and globalization and provides one part of the foundation for the Contemporary Asian Studies major and minor.  CAS201H1 introduces the theoretical and conceptual frameworks that are explored through further grounded empirical case studies in upper year CAS courses.', null, 3, null::jsonb),
    ('CAS202H1', 'Asia and the World in the 21st Century', '24L', 'This interdisciplinary course explores a variety of sites and topics in South, Southeast, and East Asia. It explores themes including contemporary and historical articulations of socio-economic development, (post)colonial political formations, urbanization processes, climate change, labour struggles, gender studies, migration, citizenship, and social justice. The course examines the diversity of Asian modernities, cross-regional linkages, and changing approaches to area studies over time. It provides a foundation for the Contemporary Asian Studies major and minor, preparing students for taking more advanced courses on Asia in the global context.', null, 3, null::jsonb),
    ('CAS310H1', 'Comparative Colonialisms in Asia', '24L', 'This course analyzes the impact of colonialism in South, East, and Southeast Asia and the various ways in which pre-colonial traditions intersect with and reshape colonial and postcolonial process across the various regions of Asia. The course will examine the conjunctures of economy, politics, religion, education, ethnicity, gender, and caste, as these have played out over time in the making and re-making of Asia as both idea and place. Attention will be paid to postcolonial and indigenous theories, questions of ''the colonial'' from the perspective of Asian Studies, and debates about the meaning of postcolonialism for the study of Asia now and in the future.', null, 3, null::jsonb),
    ('CAS320H1', 'Comparative Modernities in Asia', '24L', 'Since at least the late 1700s, the effects of capitalism across the globe have profoundly transformed the landscapes of human livelihood, consumption, production and governance in Asia. While colonial empires have declined, new empires have emerged, and a growing number of countries have witnessed the rise of nationalism and independent states, social, political and technological revolutions, and most recently neoliberal globalization. This course theorizes and explores these dramatic changes in a comparative framework. It is aimed at students wishing to better understand the great transformations of modern Asia in a global context.', null, 3, null::jsonb),
    ('CAS350H1', 'Asian Youth Cultures', '24L', 'In focusing on youth in Asia, this course brings together two disputed cultural formations of substantial contemporary importance. Both youth and Asia are increasingly invoked on the global stage in support of a wide range of interests. Examining practices of young people and the idea of youth in the context of Asia requires critical attention to the promises and fears that attach to the rise of Asian economies, international demographic transitions, the growth of a global middle-class, increasing consumption disparities, changing immigration patterns, expanding technological skills, global/local environmental concerns, and young people''s shifting political priorities and loyalties. The course may feature a significant amount of social theory, with authors such as Michel Foucault, Roland Barthes, Louis Althusser, and Stuart Hall.', null, 1, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('CAS360H1', 'Asian Genders', '24L', 'This course will explore ways that gender is mobilized and produced in parts of Asia. It seeks to understand gender and sexuality in their diversity and in attempts to "fix" or locate it in various bodies and places. Attempts will be made to see how gender is made knowable in terms of sexuality, medicine, nation, class, ethnicity, religion, and other discourses. The course assumes a willingness to read challenging theory – such as the writings of Judith Butler, Michel Foucault, and Eve Sedgwick – and asks that students commit to regular attendance.', null, 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('CAS370H1', 'Asian Cities', '24L', 'This course offers a multidisciplinary perspective of urban life in Asia. The thematic focus will be on how the urban intersects with modernities and postcolonial formations. Drawing on recent scholarship in the social sciences and the humanities, we will examine the realignment of cultural, political, and economic forces associated with Asia''s diverse processes of urbanization.', null, 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('CAS390H1', 'Special Topics', '24L', 'Course content varies in accordance with the interest of the instructor. Check http://munkschool.utoronto.ca/ai/cas for an updated description.', null, null, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('CAS393H1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and a faculty supervisor before enrolment in the course. Open to advanced CAS major and minor students with a strong background in contemporary Asian studies. A maximum of one year of Independent Research courses is allowed per program. Contact hours with the supervisor may vary, but typically comprise of one hour per week. Not eligible for CR/NCR option. To enrol, please contact ai.asianstudies@utoronto.ca to request an application form, which should be filled out in consultation with the faculty supervisor and include a detailed description of the course topic, reading list, and assignments/marking scheme. Students must submit the completed form to ai.asianstudies@utoronto.ca at least one week before the start of term.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('CAS393Y1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and a faculty supervisor before enrolment in the course. Open to advanced students in the CAS major and minor with a strong background in contemporary Asian studies. A maximum of one year of Independent Research courses is allowed per program. Contact hours with the supervisor may vary, but typically comprise of one hour per week. Not eligible for CR/NCR option. To enrol, please contact ai.asianstudies@utoronto.ca to request an application form, which should be filled out in consultation with the faculty supervisor and include a detailed description of the course topic, reading list, and assignments/marking scheme. Students must submit the completed form to ai.asianstudies@utoronto.ca at least one week before the start of term.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('CAS400H1', 'Advanced Seminar in Methods in Contemporary Asian Studies', '24S', 'This seminar challenges students to hone their growing mastery in Contemporary Asian Studies by engaging with advanced theory about the peoples and places of the continent. Readings address colonial history and emphasize the contemporary period throughout Asia. As the culmination of a student''s studies in CAS, the course requires students to grapple with post-colonial conditions in Asia.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "CAS"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('CAS413H1', 'Asia and Canada', '24S', 'This service-learning course partners teams of students with non-governmental organizations (NGOs) that work for the betterment of people and places in Asia. Students cultivate professional skills in project management, consulting, communications, and team-building. Projects for NGOs include components such as: research, video production, social media enhancement, website development, compiling reports, or youth outreach campaigns.', 'NEW413H1,  SAS413H1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('CAS414H1', 'The Public Event in Asia', '24S', 'This upper-level seminar will introduce students to the interdisciplinary study of popular culture in Asia through a focus on public events. Readings about all kinds of performances, including ritual, popular protest, festivals, sports, cinema, television, digital media events, and the performing arts will help students learn methodological tools to interpret the politics and meanings of public culture as it articulates with class, ethnicity, religious community, gender and caste. The course will furthermore familiarize students with a range of theoretical lenses for conceptualizing the different meanings of the "event" and the "public" from a perspective grounded in the histories of South Asia, Southeast Asia, East Asia, and their diasporas.', 'NEW414H1,  SAS414H1', 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('CAS420H1', 'Asia and the New Global Economy', '24S', 'This course explores the rise of Asia and its integration into the new global economy (labour, capitalism, knowledge economy, economic nationalism, inequality, gender, the meaning of capitalism, democracy, among others), exposing students to diverse disciplinary perspectives. Geographical coverage is pan-Asian, including East, Southeast and South Asia.', 'JPA420H1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('CAS430H1', 'Nationalism and Revolution in Asia', '24L', 'This course explores the far-reaching social, political, and cultural transformations in modern East, Southeast, and South Asia, focusing on the twentieth-century revolutionary histories and struggles to establish modern nation-states. The course adopts a topical approach within a chronological and comparative framework to highlight major historical movements and theoretical issues significant to the Asian experience.', 'ASI430H1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('CAS450H1', 'Asian Pathways Research Practice', '24S', 'This seminar builds on the systematic overview of research methodologies of the Contemporary Asian Studies major and its capstone course,  CAS400H1.  CAS450H1 provides students with the opportunity to research questions of contemporary relevance stemming from Asia and its transnational networks and communities. Addressing a range of methodologies, including historical-archival, ethnographic, visual/media, and statistical/quantitative, the course emphasizes research experience outside the classroom, in Asia as well as locally with communities in Toronto. Students will develop their own research contributions while working collaboratively.', 'CAS400Y1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CAS"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('CAS460H1', 'Global China and Its Growing Footprints in Asia and Around the World', '24L', 'This course traces the domestic roots of China''s global expansion. The end of "bide your time, hide your strength" era signals a more confident China and an expansionist stance. Intense domestic competition and excess supply have pushed state-owned and private enterprises alike to seek cheaper manufacturing base and consumer markets overseas. However, increased presence of Chinese capital and people have been met with open arms, but also cynicism, and even resistance. This course will examine the rise of Global China, traces the domestic roots of its rise, the implications for its relations with host countries as well as state-society relations in host countries from Asia to elsewhere.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CAS"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('CAS490H1', 'Special Topics in Contemporary Asian Studies', '24S', 'Course content varies in accordance with the interest of the instructor. Check http://munkschool.utoronto.ca/ai/cas for an updated description.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CAS"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('CAS498H1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and a faculty supervisor before enrolment in the course. Open to advanced CAS major and minor students with a strong background in contemporary Asian studies. A maximum of one year of Independent Research courses is allowed per program. Contact hours with the supervisor may vary, but typically comprise of one hour per week. Not eligible for CR/NCR option. To enrol, please contact ai.asianstudies@utoronto.ca to request an application form, which should be filled out in consultation with the faculty supervisor and include a detailed description of the course topic, reading list, and assignments/marking scheme. Students must submit the completed form to ai.asianstudies@utoronto.ca at least one week before the start of term.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["CAS200Y1", {"operator": "AND", "items": ["CAS201H1", "CAS202H1"]}]}, "CAS310H1"]}'::jsonb),
    ('CAS498Y1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and a faculty supervisor before enrolment in the course. Open to advanced CAS major and minor students with a strong background in contemporary Asian studies. A maximum of one year of Independent Research courses is allowed per program. Contact hours with the supervisor may vary, but typically comprise of one hour per week. Not eligible for CR/NCR option. To enrol, please contact ai.asianstudies@utoronto.ca to request an application form, which should be filled out in consultation with the faculty supervisor and include a detailed description of the course topic, reading list, and assignments/marking scheme. Students must submit the completed form to ai.asianstudies@utoronto.ca at least one week before the start of term.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": "CAS"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('CDN197H1', 'Inventing Canada', '24S', 'This course explores the ways that Canadian history and identity have been commemorated, interpreted and experienced, now and in the past. The course focuses in particular on who has been included or excluded in commemorative efforts over time. Key topics include representations of women, Indigenous peoples, and political figures on screen and through public installations like museum exhibits, plaques and statues. Case studies highlighting a range of interpretive media will encourage students to work with and discuss a range of primary and secondary sources, build critical thinking and academic writing skills. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('CDN198H1', 'Canada, Colonialism and Settler Relations', '24S', 'A First Year Foundations seminar focused on exploring Canada''s colonial history and recent efforts to enact appropriate settler relations through an interdisciplinary lens. Topics will include contemporary land claims and treaty-making processes, the Royal Commission on Aboriginal Peoples, governmental apologies for the mistreatment of Indigenous peoples, the Truth and Reconciliation Commission, land acknowledgements, practices of allyship through social movement such as Idle No More, and efforts to influence Canada''s overseas mining practices. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('CDN199H1', 'Canada- Hong Kong Migration', '24S', 'This course surveys the effects of migrations and cultural connections between Hong Kong and Canada from the 1960s. Students will discuss and analyze the impact of migrations, and study the connection between the two locations from the perspectives of history, culture and literature, politics and democracy, economic and financial development and the network of people and community. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('CDN202H1', 'Aspects of Québec Culture', '24S', 'An exploration of modern Québec culture as expressed in literature and the performing arts. Through a selection of internationally-known entertainers, we examine form, artistic innovation, communication of information and knowledge, and spectatorship. Novels and plays provide key elements such as tradition and historical context.', null, 1, null::jsonb),
    ('CDN205H1', 'Topics in Canadian Studies I', '24L', 'A focused introduction to specific issues in Canadian culture and society. Content will vary from year to year. Specific course information will be available on the Canadian Studies website at www.uc.utoronto.ca/canadianstudies.', null, null, null::jsonb),
    ('CDN218H1', 'Voices in Canadian Writing', '24S', 'A study of the variety of voices in Canadian fiction with a focus on contemporary writers. Issues such as marginalization, migration, diaspora and the formulation of the Canadian canon are discussed.', null, 1, null::jsonb),
    ('CDN221H1', 'Culture and the Media in Canada', '24L', 'An exploration of the encounter between culture and mass communication in Canadian society. The course considers the role of major cultural institutions such as the CBC, the NFB, and their granting bodies. The emergence of digital media and its relationship to mass media is also addressed.', null, 1, null::jsonb),
    ('CDN225H1', 'Asian Canadian Space & Place', '24L', 'A comprehensive examination of how Asian Canadian communities shape urban and suburban environments. Explore how urban planning and peoples'' local decisions interact to create space, place, and culture. The course applies a multidisciplinary lens, with an emphasis on culture and heritage, place and identity formation, diasporas, multiculturalism, and nationalism.', 'CDN325H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CDN235H1', 'Learning While Black', '24S', 'This course employs Blackness as an embodied subjectivity (both individual and collective) that is central to Black learners and the Black experience in education. Using creative, critical and decolonial methods of teaching and learning, this course will engage an interdisciplinary study of what it means to learn while being Black (both historically and contemporarily) in contexts of colonialism, slavery and anti-Black racism in Canada. The course will also engage a critical interrogation of the role that education systems (can) play for Black freedom, liberation, and self-determination, both locally, in Canada and globally.', null, 3, null::jsonb),
    ('CDN240H1', 'Italian Canadian Studies', '24L', 'An interdisciplinary course that examines the social, economic, and political forces and events that have shaped the Italian Canadian experience. Topics include initial and subsequent settlement patterns including suburbanization, identity formation, education, mobility, work, media, multiculturalism, transnationalism, and political participation and representation. The course interrogates the complexities of the social and cultural interactions of Italian Canadians in the context of the changing demography of Canada.', null, 3, null::jsonb),
    ('CDN265H1', 'Race and Racialization in Canada', '24S', 'This course will address the history, theory, experience and representation of race and racialization in Canada, using both critical and creative methods. Students will also gain a critical understanding of how racialized communities resist racism. Specific topics may include social construction, phenotyping, power, privilege, intersectionality, Indigeneity, Blackness, Asianness, whiteness, decolonization, diaspora, relationality, anti-racism, solidarity, allyship, and coalitions.', null, 2, null::jsonb),
    ('CDN267H1', 'What is Canada?', '24L', 'This interdisciplinary course examines critical, cultural, and community responses to the question “What is Canada?”, past and present. Issues addressed include Indigeneity and nation to nation relations, evolving formations of identity, belonging, and citizenship, and intersections of sexuality, gender, race, ethnicity, and faith. Theoretical concepts introduced include settler colonialism and decolonization, immigration and diaspora, nationalism and multiculturalism, memory and reclamation, activism and resistance.', null, 1, null::jsonb),
    ('CDN268H1', 'Canada and Globalization', '36L', 'Students examine the impact of contemporary globalization on Canada, and for Canada''s place in the world. The course is interdisciplinary in its approach and addresses globalization from a wide range of perspectives, including mobility, trade, urbanization, health, religion, environmental change, technology, communications, and the arts.', null, 3, null::jsonb),
    ('CDN280H1', 'Canadian Jewish History', '24L', 'This course focuses on initial settlement patterns of Jews in Toronto and elsewhere, community growth including suburbanization, and contemporary challenges such as anti-Semitism and assimilation.', null, 3, null::jsonb),
    ('CDN305H1', 'Topics in Canadian Studies II', '24L', 'An in-depth study of selected questions in contemporary Canadian culture and society. Content will vary from year to year. Specific course information will be available on the Canadian Studies website at www.uc.utoronto.ca/canadianstudies/.', null, null, null::jsonb),
    ('CDN307H1', 'Asian Cultures in Canada', '24S', 'An exploration of the cultural histories and creative productions of a wide range of Asian communities in Canada. Experts in specific areas - literature, dance, drama, film - will be invited to present their work.', null, 1, null::jsonb),
    ('CDN320H1', 'Experiential Learning', '12L/12P/12S', 'This course provides students with an opportunity to participate in experiential learning. Placements are made with partners active in community-led initiatives, with an emphasis on local Canadian change-makers, grassroots, not-for profit and public initiatives. In their coursework, students will be introduced to best practices and principles for experiential learning and community-based engagement. Critical readings, hands-on research activities, and guest speakers will foreground the complexities of agency and activism. Lectures and course materials provide critical models experiential learning methods for assessing and reporting on challenges, best practices, and outcomes over the placement experience.', null, 3, '{"operator": "OR", "items": ["CDN265H1", "CDN267H1", "CDN268H1"]}'::jsonb),
    ('CDN335H1', 'Black Canadian Studies', '24S', 'The course introduces students to the emerging field of Black Canadian Studies, and approaches it as an intellectual, cultural and political endeavour that is steeped in a long tradition of Black resistance against colonialism, slavery and anti-Black racism. To counter the ways Black communities are all too often erased and overlooked in society, this course focuses on deepening students'' knowledge and understanding of Black communities in Canada, and the historical and contemporary contributions, experiences, and social issues these communities encounter as they navigate life in what is now known as Canada. This course examines the constitution of Blackness in Canada, as it intersects with other social relations of identity and power such as gender, class and sexuality. Black intellectual traditions and cultural expressions in literature, music, media, education, social justice movements, and the workplace are also addressed as noteworthy spaces which shape, influence and represent the Black Experience in Canada.', null, 3, '{"operator": "OR", "items": ["CDN265H1", "CDN267H1", "CDN268H1"]}'::jsonb),
    ('CDN340H1', 'The History of Canada-U.S. Relations', '24L', 'Over time, Canadians and Americans have developed distinct identities and cultures, but their histories have always been closely linked. This course examines the complex interrelationship between Canada and the United States. from the colonial period through the present day, especially its political, cultural, and indigenous dimensions.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": "CDN"}]}'::jsonb),
    ('CDN355H1', 'Digital Media, Digital Makers', '24S', 'This course is an introduction to Digital Humanities interdisciplinary research and practice relevant to Canadian Studies broadly. Working with a range of digital tools and platforms for text analysis, story mapping, data visualization, and digital curation, student projects will engage critically and creatively with theoretical and practical questions encountered in digital knowledge production in different disciplines (Humanities and Social Sciences). No prior tech experience required.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": "CDN"}]}'::jsonb),
    ('CDN365H1', 'The Canadian Arctic', '24S', 'This course surveys topics related to the Canadian Arctic. Through a critical interdisciplinary lens, the course looks at a broad set of issues including discovery and history, the environment and climate change, economic and resource development, sovereignty and security, social conditions, governance, and First Nations, Inuit, and Metis perspectives.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "Canadian Studies"}]}'::jsonb),
    ('CDN367H1', 'Canadian Pluralism', '24S', 'Students will examine the complexities of social and cultural interaction in the context of changing Canadian demographics. This course compares and contrasts policies regarding Indigenous rights, migration, multiculturalism, and citizenship with contemporary cultural narratives in literature, painting and film.', null, 1, '{"operator": "OR", "items": ["CDN265H1", "CDN267H1", "CDN268H1"]}'::jsonb),
    ('CDN368H1', 'Canada''s Borders', '24S', 'The Canadian border is being reshaped by the increasing transnational movement of people, goods and ideas. Students will examine border issues relating to mobility, trade, and security from a wide range of interdisciplinary perspectives, from public policy to contemporary media, such as TV, films, and novels.', null, 3, '{"operator": "OR", "items": ["CDN265H1", "CDN267H1", "CDN268H1"]}'::jsonb),
    ('CDN370H1', 'Special Topics in Canadian Studies', '24S', 'An in-depth study of selected questions in contemporary Canadian culture and society. Content will vary from year to year. Specific course information will be available on the Canadian Studies website at www.uc.utoronto.ca/canadianstudies/.', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('CDN380H1', 'Contemporary Jewish Canadian Communities', '24L', 'This course examines: the relationship between prominent Canadians who happen to be Jews and those whose works are founded in Jewish identity; the diversity of the community on the basis of religion, language, class, ideology, etc.; contributions to the arts and scholarship; and the role and contribution of Jewish women.', null, 1, null::jsonb),
    ('CDN385H1', 'Re-Imagining Canada: Creative Visions of Our Past, Present, and Futures', '24S', 'Artists and writers are re-imagining Canada, exploring alternate pasts, presents, and futures, often critiquing systemic inequities by positing “what ifs” of resistance and renewal, while reclaiming agency, voice, and power for those who are disadvantaged in society. This course will examine these re-imaginings across various media such as fiction, poetry, graphic novels, films, multimedia installations, performance art, paintings, virtual reality works, and video games. Examples will be drawn from a wide variety of genres such as speculative fiction, Afrofuturism, Indigenous arctic horror, trans, queer, Indigenous and Indigiqueer perspectives.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CDN390H1', 'Chinese Canadian Studies', '24S', 'This course examines socio-cultural, political and economic aspects of Chinese communities in Canada. It explores how the study of Chinese Canadians challenges and augments our understanding of issues such as immigration and diaspora, multiculturalism, and race and ethnicity.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CDN395H1', 'Independent Study in Asian Canadian Studies', null, 'An opportunity to write an independent research paper in Asian Canadian Studies under direction of a faculty member. Students wishing to take this course must have their essay proposal and supervisor approved by the Canadian Studies Program Director. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/canadian-studies/courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('CDN405H1', 'The University in Canada', '24S', 'This seminar course will address the role of universities in Canadian society and in the lives of Canadians. Students will explore both contemporary issues in Canadian higher education and consider the historical contexts from which they emerged.', null, 3, null::jsonb),
    ('CDN406H1', 'Topics in Canadian Studies III', '24S', 'An in-depth study of selected questions in contemporary Canadian culture and society. Content will vary from year to year. Specific course information will be available on the Canadian Studies website at www.uc.utoronto.ca/canadianstudies.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "Canadian Studies"}]}'::jsonb),
    ('CDN420Y1', 'Senior Essay', '48S', 'Students select an appropriate research topic and, in consultation with the Program Director, make arrangements with a suitable supervisor. Preferably, research projects must be approved by the supervisor and by the Director of the Canadian Studies Program by April of the preceding academic year. Students meet periodically during the year in seminar to participate in peer evaluations of: statement of research, literature review, methods of analysis, and to share reports of progress in research. Normally open only to Majors and Specialists in the Canadian Studies program. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/canadian-studies/courses.', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('CDN425H1', 'Independent Research in Canadian Studies', null, 'An opportunity to write a substantial research paper in Canadian Studies that integrates research methodologies and conceptual frameworks developed over the student''s course of study. Students must have their topic and supervisor approved by the Canadian Studies program director. Not eligible for CR/NCR option. Students must submit an application form that includes a written proposal and confirms that a faculty member has agreed to supervise. Applications must be submitted to the UC Programs Office (UC 173) for approval by the Program Director. Applications are due before the first day of course enrolment. Application form is available at the University College website at https://www.uc.utoronto.ca/canadian-studies/courses.', null, null, '{"operator": "AND", "items": [{"credits": 15.0, "department": null}]}'::jsonb),
    ('CDN430Y1', 'Senior Seminar: Special Topics in Canadian Studies', '48S', 'An upper level seminar. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('CDN435Y1', 'Active Citizenship in a Canadian Context', '48S', 'This course draws from theoretical works to critically examine the experiences of citizenship of various communities in Canada. A service learning component is incorporated so that students can themselves engage in active citizenship. The course develops extra-curricular expertise that can contribute to a student''s professional CV.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CDN440H1', 'Afrofuturisms: Black Canadian Perspectives', '24S', 'This course explores Afrofuturism through Black Canadian perspectives and experiences. As an interdisciplinary course, it draws on both critical and creative methods from Black feminist, decolonial, critical race and critical sociological theories, as well as Black cultural traditions and expressions in music, literature, social movements and the arts as pivotal spaces of possibility and resistance, where alternative futures are both imagined and realized for Black people in Canada. Topics to be explored include Black freedom and resistance, and the roles that speculative fiction, the arts, education, technology and African Indigenous spiritual traditions play in Black Canadian framings and approaches to Afrofuturism.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('CDN450H1', 'Asian Canadian Memory and Practice', '24S', 'A study of Asian Canadian cultural history and practice with a focus fiction, poetry, film and media, and the communities that have formed around them. The course focusses on the evolution of key practices, community formations, frames, debates, themes and issues.', null, 1, '{"operator": "OR", "items": ["CDN265H1", "CDN307H1"]}'::jsonb),
    ('CDN455H1', 'Asian Canadian Ecologies and Futurities', '24S', 'A study of Asian Canadian ecological writing and speculative fiction. This course focuses on Asian Canadian critical and imaginative contributions to a better world. By the end of this course, students will understand some frames and contents of Asian traditional knowledge and will be able to explain how such knowledges are carried into the present. They will understand how some Asian Canadian writers already do this. They will be able to imagine how such knowledges might be carried into the future.', null, 1, '{"operator": "OR", "items": ["CDN265H1", "CDN307H1"]}'::jsonb),
    ('CDN470H1', 'Special Topics in Canadian Studies', '24S', 'An in-depth study of selected questions in contemporary Canadian culture and society. Content will vary from year to year. Specific course information will be available on the Canadian Studies website at www.uc.utoronto.ca/canadianstudies/.', null, null, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}]}'::jsonb),
    ('CHC120H1', 'Catholicism in Conversation', '24L/12T', 'What is Catholicism, as an idea, as a social movement, as an object of scorn, devotion or delight? What meaning does Catholic tradition have in the contemporary world? This seminar explores these and similar questions through lectures and conversations with diverse scholars—faculty, fellows and friends—of the St. Michael''s College community.', 'SMC103Y1,  SMC120H1', 3, null::jsonb),
    ('CHC130H1', 'Playing with Fire: Alchemy, Astrology, and Magic', '24L/12T', 'This course offers an historical introduction to alchemy, astrology, and magic, with a focus on the development, defence, condemnation, and progressive marginalization of these controversial pursuits in and around the Christian world(s). Students will learn about such topics as the search for the philosopher''s stone, the casting of horoscopes, the design of wondrous machines… and the risks associated with meddling with spirits! Lectures will examine these learned traditions on their own terms, while inviting discussions about their enduring popularity, their connections with the rise of modern science and their reception in popular culture.', null, 2, null::jsonb),
    ('CHC200H1', 'Christianity and the Arts', '24L/12T', 'This course introduces students to creative works from throughout the global Christian tradition. The course explores the complex relationships that exist between religious and aesthetic imperatives, between theological and material sources, between beauty and suffering, and between artists and their patrons and audiences.', 'SMC200H1', 1, null::jsonb),
    ('CHC203Y1', 'Christianity and Society Through the Ages', '48L/24T', 'This course explores the historical engagement of various Christian traditions with the prevailing political, social, and ethnic cultures in the western world and beyond. Students will also examine the development of Christianity as it confronts changes in the symbolic and intellectual universes from antiquity to post-modernity.', 'SMC203Y1', 2, null::jsonb),
    ('CHC215H1', 'Varieties of Christian Community', '24S', 'Christian history has been characterized by an enduring and fruitful search for forms of religious community. This course surveys some communal attempts to express Christianity, monasticism, forms of common life for clerics, the Mendicants, lay confraternities, religious orders, and contemporary lay movements.', 'SMC215H1', 3, null::jsonb),
    ('CHC218H1', 'Christianity and Education', '24L', 'An exploration of pedagogy and child development theory, with a particular focus on the way Christians have employed these educational techniques historically. Attention will be given to the diversity of institutions and approaches to curriculum development across Christian history.', 'SMC218H1', 2, null::jsonb),
    ('CHC232H1', 'Christianity and Science', '24L', 'This course examines different models of relating Christianity and Science. Beginning with the biblical view on the natural world and moving to the present, the lectures develop a wide range of approaches.', 'SMC232H1', 2, null::jsonb),
    ('CHC300H1', 'Special Topics in Christianity and Culture I', '24L', 'An advanced seminar in Christianity and Culture as determined by the instructor. In some terms this course may require an application. This will be clearly noted in the Timetable.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC304H1', 'Christianity, Law and Society', '24L', 'An examination of Canon Law; the process by which it came into being, and its impact on contemporary culture. Premises and techniques of ecclesial law-making are compared to those of other systems of legislation. Specific sections of the Code of Canon Law are examined.', 'SMC304H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC305H1', 'Christianity and Popular Culture', '36L', 'An examination of both overt and covert representations of Christian ideas in contemporary popular media. We examine the ways in which Christian themes have been appropriated and subverted in mass media, while also examining the innovative ways these themes, such as redemption, sacrifice, vocation, and hope, are presented anew.', 'SMC305H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC306H1', 'The Catechism of the Catholic Church', '24L', 'Introduces students to the Catechism of the Catholic Church (1994) and its antecedents. After an historical survey of religious instruction in the Church, the students will engage in a close reading of selected sections of the Catechism of the Catholic Church.', 'SMC310H1,  SMC306H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC307H1', 'Scripture in Christian Tradition', '24L/12T', 'The formation and content of the Christian Bible; an introduction to the history of its interpretation and of the role it has played and continues to play in Christian life and culture.', 'SMC307Y1,  SMC307H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC308H1', 'Marriage and the Family in the Catholic Tradition', '24L', 'A close reading of the Code of Canon Law touching on the themes of marriage and the family; relationship to other fundamental Church statements (e.g. Familiaris Consortio); examination of issues raised by opposition between church teaching and other views.', 'SMC308H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC309H1', 'Christianity and Politics', '24L/12T', 'This course explores developments in the relations between the Catholic Church and the states of Western Europe and America from the Enlightenment to the present. Of particular concern is Catholicism''s response to the political theories of the Enlightenment, the secularization of the state and social justice issues.', 'SMC309H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC311H1', 'Why the Church', '24S', 'The Catholic Church claims to be the continuation of the event of Christ in history, the guarantor of the authenticity of each person''s encounter with Christ, and the means by which His memory may be cultivated. The course examines the reasons for these claims and the forms they have taken.', 'SMC311H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC312H1', 'Catholicism and Education', '24S', 'The Catholic Church has developed a distinctive approach to the pedagogical enterprise. This course explores aspects of this approach by an examination of canonical legislation and other texts published by ecclesiastical authorities and their application in Canada.', 'SMC312H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC313H1', 'Catholic Education in Ontario', '24L', 'An historical appraisal of the evolution of Catholic schools, universities, and catechetical education in Ontario. Special emphasis is placed on the evolution of Ontario''s separate school system.', 'SMC313H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC322H1', 'Women and Christianity', '24S', 'An exploration of what Pope John Paul II, among others, called the "feminine tradition" in Christian life and thought. Possible topics include women''s roles in the early church, Marian dogmas and devotions, women mystics and Doctors of the Church, and Christian feminisms and New Feminisms in the contemporary period.', 'SMC322H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC327H1', 'Ritual and Worship', '24L/12T', 'An introduction to Christian ritual and worship, in cross-cultural and ecumenical perspective. Biblical roots, historical development and diverse adaptions of Christian worship in Europe, North America and the global South.', 'SMC216Y1,  SMC327H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC330H1', 'Christ in Christian Tradition', '24L/12T', 'Faith in Christ is central to Christianity. This course offers an advanced introduction to classical debates about the person and work of Christ, the modern Quest of the Historical Jesus, and selected feminist, liberationist and indigenized perspectives on Christ from Asia, Africa and Latin America.', 'SMC330Y1,  SMC330H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC364H1', 'The Christian Book', '24L', 'An interdisciplinary examination of the Bible as artifact and as an index of culture, art, and language. Topics include: the mediaeval giant Bibles, illuminated and illustrated Bibles, the Gutenberg Bible, The King James Bible, the Bible industry, the Bible online, the Bible as sacred object, sacred language and vernacular.', 'SMC364H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC365H1', 'Christianity, Art, and Architecture', '24L/12T', 'An exploration of visual arts and architecture as mediums for expressing Christian faith. The course will examine notable developments in Christian history, the proliferation of new forms in the contemporary period, and important local works, such as the Donovan Collection and/or the rich legacy of church architecture in the GTA.', 'SMC365H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC367H1', 'Christianity, Literature, and Theatre', '24L', 'This course introduces students to works of literary and dramatic arts from throughout the global Christian tradition. The course explores the complex relationships that exist between religious, narrative, and performative imperatives; between theological and cultural sources; between authority and experience; and between writers, playwrights, and their readerships and audiences.', 'SMC201H1,  SMC367H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC368H1', 'Varieties of Christian Experience', '24L', 'Exploration of the variety of forms which Christian personal experience has taken in the course of history (martyrdom, mysticism, monasticism, sanctification of ordinary life, etc.) in order to appreciate their variety, complexity, and deep unity.', 'SMC205H1,  SMC368H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC369H1', 'Christianity and Music', '24L', 'The various roles given music in Christian tradition and the impact of Christianity on Western music. Case studies from Gregorian chant to the present illustrate major issues (sacred vs. profane, acceptable styles or instruments, text and music, emotion and rationalism) to provide a critical vocabulary applicable to present works. Some background in music is required.', 'SMC206H1,  SMC369H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC370H1', 'The Bible and Biology', '24L/12T', 'Episodes and issues in the development of biology, genetics and evolutionary theory in relation to Christian understandings of the natural world, the human person, and God. Possible topics include genetic determinism, mind and intelligence, gender, reproductive technologies, cosmology and ecology.', 'SMC370H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC371H1', 'Faith and Physics', '24L', 'The complex interplay between religious belief, culture, and the emergence of modern physical theory: rise and fall of mechanistic theories, relativity, particle physics and models of the Universe, Big Bang theory and Black Holes, etc.', 'SMC371H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC372H1', 'The Catholic Church in Canada', '24L', 'An exploration of the historical development of Catholic communities and institutions in all regions of Canada since the 16th century. Emphasis placed on themes of mission, church-state relations, ethnicity, belief and practice, social justice, gender, and secularization.', 'SMC320H1,  SMC372H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC378H1', 'Major Christian Thinkers, up to 1300', '24L', 'An advanced introduction to the Christian intellectual tradition through a study of key texts from before 1300. Selected authors discuss a range of religious, intellectual, and cultural issues, from foundational Christian beliefs to the challenges of integrating non-Christian learning into Christian societies, institutions, scholarship, and literature.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC379H1', 'Major Christian Thinkers, 1300 to present', '24L', 'An advanced introduction to the Christian intellectual tradition through a study of key texts from around the year 1300 to the present. Selected authors discuss a range of religious, intellectual, and cultural issues, from their role in the shaping of early modern and modern institutions to the challenge of integrating Christian values and ideals into our postmodern, plural, and global society.', 'SMC208Y1,  SMC379H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC382H1', 'Literature and the Christian Child', '24L/12T', 'An exploration of connections between a child''s moral development and literature in Christian traditions. We examine literary, historical and philosophical developments appropriate to the child''s imagination. The course will include the study of poems, catechetical materials, novels and other texts written for children.', 'SMC217H1,  SMC382H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('CHC383H1', 'God and Geometry', '24L', 'This course engages controversial issues in the natural sciences of importance to Christian faith, with particular emphases on their ancient and the medieval origins and enactments. Examples include: Harmony vs. Chaos, Creation vs. Evolution, Free Will vs. Determinism, Reason vs. Revelation, Miraculous vs. Natural Causation.', 'SMC233H1,  SMC383H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb)
